-- بيانات مقرر كيمياء 2-2 (المقرر 3، قيد الإعداد) — الجزء 8 من 8. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem22-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الأحماض الدهنية؟', null, null, '["كحولات ذات سلاسل طويلة تحتوي على مجموعات هيدروكسيل متعددة","أحماض كربوكسيلية ذات سلاسل طويلة تحتوي عادة على 12–24 ذرة كربون","أحماض أمينية تحتوي على مجموعة أمين ومجموعة كربوكسيل","إسترات تتكون من اتحاد الجليسرول مع ثلاثة أحماض"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 219 — الأحماض الدهنية'),
('mcq', 2, 'يمثل الشكل الآتي حمضين دهنيين في كل منهما 18 ذرة كربون. أي الحمضين غير مشبع؟ ولماذا؟', null, '[{"src":"qimg/chem22/c6-l3a-fa-pair.svg","alt":"صيغتان هيكليتان (خطيتان) لحمضين دهنيين مرقمين (1) و(2)، في كل منهما 18 ذرة كربون. يبدأ كل حمض من اليسار بمجموعة كربوكسيل: ذرة كربون ترتبط برابطة ثنائية بذرة O وترتبط بمجموعة HO، تليها سلسلة كربونية متعرجة، وكل رأس أو نهاية خط يمثل ذرة كربون. الحمض (1): توجد رابطة ثنائية C=C (خطان متوازيان) بين ذرتي الكربون التاسعة والعاشرة بالعد من ذرة كربون الكربوكسيل، والسلسلة منثنية عندها لأن جزأي السلسلة على جانب واحد من الرابطة الثنائية (ترتيب سيس)، فتنحرف بقية السلسلة نحو الأسفل. الحمض (2): سلسلة متعرجة مستقيمة جميع روابطها بين ذرات الكربون أحادية."}]'::jsonb, '["(2)؛ لأن سلسلته الكربونية مستقيمة وطويلة","(2)؛ لأن جميع روابطه بين ذرات الكربون أحادية","(1)؛ لأنه يحتوي على مجموعة كربوكسيل إضافية","(1)؛ لأنه يحتوي على رابطة ثنائية بين ذرتي كربون"]'::jsonb, 'فهم', 'تمييز من الشكل', 'متوسط', 'الكتاب ص 219 — الشكل 6-13'),
('mcq', 3, 'ما عدد ذرات الكربون في حمض البالمتيك CH₃(CH₂)₁₄COOH؟ وما نوعه؟', null, null, '["16 ذرة كربون، وهو حمض دهني مشبع","14 ذرة كربون، وهو حمض دهني مشبع","16 ذرة كربون، وهو حمض دهني غير مشبع","15 ذرة كربون، وهو حمض دهني غير مشبع"]'::jsonb, 'تطبيق', 'تحليل صيغة', 'متوسط', 'الكتاب ص 219 — الأحماض الدهنية (س63 ص 233)'),
('mcq', 4, 'يمثل الشكل الآتي حمض اللينوليك. كم رابطة ثنائية بين ذرات الكربون في جزيئه؟ وما نوعه؟', null, '[{"src":"qimg/chem22/c6-l3a-linoleic.svg","alt":"صيغة هيكلية لحمض دهني: في اليسار مجموعة كربوكسيل (ذرة كربون مرتبطة برابطة ثنائية بذرة O ومرتبطة بمجموعة HO)، تليها سلسلة كربونية متعرجة، وعدد ذرات الكربون الكلي 18 ذرة. في السلسلة رابطتان ثنائيتان C=C: الأولى بين ذرتي الكربون 9 و10، والثانية بين ذرتي الكربون 12 و13 بالعد من ذرة كربون الكربوكسيل، وتفصل بينهما ذرة كربون واحدة (CH₂)، والسلسلة منثنية عند كل رابطة ثنائية (ترتيب سيس). بقية الروابط بين ذرات الكربون أحادية."}]'::jsonb, '["رابطتان ثنائيتان، وهو حمض دهني غير مشبع","ثلاث روابط ثنائية، وهو حمض دهني غير مشبع","لا توجد روابط ثنائية، وهو حمض دهني مشبع","رابطة ثنائية واحدة، وهو حمض دهني غير مشبع"]'::jsonb, 'تطبيق', 'تحليل صيغة من الشكل', 'متوسط', 'الكتاب ص 219، 223 — الأحماض الدهنية (س17 ص 223)'),
('mcq', 5, 'يحتوي معظم الأحماض الدهنية الطبيعية على عدد زوجي من ذرات الكربون. ما سبب ذلك؟', null, null, '["لأن كل رابطة ثنائية في السلسلة تحتاج إلى ذرتي كربون","لأن مجموعة الكربوكسيل تحتوي على ذرتي كربون","لأن ذرات الكربون تُضاف إلى السلسلة ذرتين معًا في تفاعلات إنزيمية","لأن الجليسرول يرتبط بذرتي كربون من كل حمض دهني"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 219 — الأحماض الدهنية'),
('mcq', 6, 'أي العبارات الآتية تصف الحمض الدهني غير المشبع وصفًا صحيحًا؟', null, null, '["يحتوي على رابطة ثنائية واحدة على الأقل بين ذرتي كربون في سلسلته","يحتوي على الرابطة الثنائية C=O في مجموعة الكربوكسيل","يحتوي على أقل من 12 ذرة كربون في سلسلته","لا يحتوي على مجموعة كربوكسيل في نهاية سلسلته"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 219 — الأحماض الدهنية'),
('mcq', 7, 'الصيغة العامة للأحماض الدهنية المشبعة CH₃(CH₂)ₙCOOH. ما قيمة n لحمض دهني مشبع يحتوي على 24 ذرة كربون؟', null, null, '["24","23","21","22"]'::jsonb, 'تطبيق', 'تحليل صيغة', 'صعب', 'الكتاب ص 219 — الصيغة العامة للأحماض الدهنية'),
('essay', 1, 'عرّف الأحماض الدهنية، ثم قارن بين الأحماض الدهنية المشبعة وغير المشبعة من حيث الروابط بين ذرات الكربون، مع ذكر مثال على كل نوع وكتابة صيغته المكثفة.', null, null, null, 'فهم', 'تعريف ومقارنة', 'سهل', 'الكتاب ص 219 — الأحماض الدهنية'),
('essay', 2, 'صنّف الأحماض الدهنية الآتية إلى مشبعة وغير مشبعة، وحدد عدد ذرات الكربون وعدد الروابط الثنائية C=C في كل منها: (أ) CH₃(CH₂)₁₀COOH (ب) CH₃(CH₂)₇CH=CH(CH₂)₇COOH (ج) CH₃(CH₂)₁₆COOH. ثم فسّر لماذا لا تُعدّ الرابطة الثنائية C=O في مجموعة الكربوكسيل دليلًا على عدم التشبع.', null, null, null, 'فهم', 'تصنيف وتفسير', 'متوسط', 'الكتاب ص 219 — الأحماض الدهنية'),
('essay', 3, 'الصيغة الجزيئية لحمض الستيريك المشبع (18 ذرة كربون) C₁₈H₃₆O₂، ولحمض الأوليك (18 ذرة كربون ورابطة ثنائية C=C واحدة) C₁₈H₃₄O₂. لديك حمضان دهنيان صيغتاهما الجزيئيتان: (س) C₁₆H₃₂O₂ و(ص) C₂₀H₃₄O₂. (أ) استنتج من الصيغتين العلاقة بين عدد ذرات الكربون وعدد ذرات الهيدروجين في الحمض الدهني المشبع، والنقص في عدد ذرات الهيدروجين الذي تسببه كل رابطة ثنائية C=C. (ب) حدد أي الحمضين مشبع وأيهما غير مشبع، مع التبرير. (ج) احسب عدد الروابط الثنائية C=C في الحمض غير المشبع.', null, null, null, 'تحليل', 'استنتاج من الصيغة', 'صعب', 'الكتاب ص 219 — الأحماض الدهنية المشبعة وغير المشبعة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L3-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الأحماض الدهنية أحماض كربوكسيلية ذات سلاسل طويلة، ويحتوي معظم الأحماض الدهنية الطبيعية على ما بين 12 و24 ذرة كربون، وصيغتها العامة CH₃(CH₂)ₙCOOH.', '["الأحماض الدهنية تحتوي على مجموعة كربوكسيل –COOH لا على مجموعات هيدروكسيل متعددة.","","الأحماض الأمينية وحدات بناء البروتينات، وتحتوي على مجموعة أمين لا توجد في الأحماض الدهنية.","هذا وصف الجليسريد الثلاثي الذي تدخل الأحماض الدهنية في تكوينه، لا وصف الحمض الدهني نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('mcq', 2, 3, 'الحمض الدهني غير المشبع يحتوي على رابطة ثنائية أو أكثر بين ذرات الكربون، والحمض (1) فيه رابطة ثنائية C=C (حمض الأوليك)، أما (2) فكل روابطه أحادية فهو مشبع (حمض الستيريك).', '["استقامة السلسلة وطولها لا يجعلان الحمض غير مشبع؛ فالحمض (2) مستقيم لأنه مشبع.","الحمض الذي جميع روابطه بين ذرات الكربون أحادية حمض مشبع لا غير مشبع.","كلا الحمضين يحتوي على مجموعة كربوكسيل واحدة، والتشبع يتعلق بالروابط بين ذرات الكربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('mcq', 3, 0, 'عدد ذرات الكربون = 1 (CH₃) + 14 (CH₂) + 1 (COOH) = 16 ذرة، ولا توجد في الصيغة أي رابطة ثنائية بين ذرات الكربون؛ فهو حمض دهني مشبع.', '["","عُدّت مجموعات CH₂ فقط وأُهملت ذرة كربون CH₃ وذرة كربون مجموعة الكربوكسيل.","العدد صحيح، لكن الصيغة لا تحتوي على رابطة C=C فالحمض مشبع لا غير مشبع.","أُهملت ذرة كربون مجموعة الكربوكسيل، كما أن الحمض مشبع لخلو صيغته من C=C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('mcq', 4, 0, 'في السلسلة الكربونية رابطتان ثنائيتان C=C (بين ذرتي الكربون 9 و10 و بين 12 و13)، أما الرابطة C=O فهي في مجموعة الكربوكسيل بين الكربون والأكسجين ولا تُعدّ. ووجود رابطة ثنائية أو أكثر بين ذرات الكربون يجعل الحمض غير مشبع.', '["","عُدّت الرابطة C=O في مجموعة الكربوكسيل مع الروابط الثنائية، والتشبع يتعلق بالروابط بين ذرات الكربون فقط.","في السلسلة رابطتان ثنائيتان C=C ظاهرتان، فالحمض غير مشبع.","في السلسلة رابطتان ثنائيتان C=C لا واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('mcq', 5, 2, 'يحتوي معظم الأحماض الدهنية على عدد زوجي من ذرات الكربون؛ لأنها تُبنى بإضافة ذرتي كربون معًا في الوقت نفسه في تفاعلات إنزيمية.', '["الأحماض الدهنية المشبعة لا تحتوي على روابط ثنائية، ومع ذلك فعدد ذرات الكربون فيها زوجي غالبًا.","مجموعة الكربوكسيل –COOH فيها ذرة كربون واحدة فقط.","","الحمض الدهني يرتبط بالجليسرول عبر مجموعة الكربوكسيل برابطة إستر واحدة، ولا علاقة لذلك بعدد ذرات الكربون في الحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('mcq', 6, 0, 'يُسمّى الحمض الدهني غير مشبع إذا احتوى على رابطة ثنائية أو أكثر بين ذرات الكربون، ويُسمّى مشبعًا إذا لم يحتوِ على روابط ثنائية بين ذرات الكربون.', '["","الرابطة C=O موجودة في مجموعة الكربوكسيل في كل الأحماض الدهنية المشبعة وغير المشبعة، فلا تميز غير المشبع.","عدد ذرات الكربون لا يحدد التشبع، ومعظم الأحماض الدهنية الطبيعية فيها 12–24 ذرة كربون.","كل الأحماض الدهنية أحماض كربوكسيلية تحتوي على مجموعة الكربوكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('mcq', 7, 3, 'ذرات الكربون في الصيغة = 1 (في CH₃) + n (في مجموعات CH₂) + 1 (في COOH) = n + 2، فإذا كان العدد 24 فإن n = 24 − 2 = 22، والصيغة CH₃(CH₂)₂₂COOH.', '["هذا العدد الكلي لذرات الكربون، ولم تُطرح منه ذرتا الكربون في CH₃ وCOOH.","طُرحت ذرة كربون واحدة فقط (CH₃ أو COOH)، والصحيح طرح ذرتين.","طُرحت ثلاث ذرات كربون، مع أن خارج القوس ذرتي كربون فقط (CH₃ وCOOH).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.841Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأحماض الدهنية أحماض كربوكسيلية ذات سلاسل طويلة، يحتوي معظمها على ما بين 12 و24 ذرة كربون، وصيغتها العامة CH₃(CH₂)ₙCOOH. الأحماض الدهنية المشبعة لا تحتوي على روابط ثنائية بين ذرات الكربون، مثل حمض الستيريك CH₃(CH₂)₁₆COOH. أما الأحماض الدهنية غير المشبعة فتحتوي على رابطة ثنائية أو أكثر بين ذرات الكربون، مثل حمض الأوليك CH₃(CH₂)₇CH=CH(CH₂)₇COOH.', '["تعريف الأحماض الدهنية: أحماض كربوكسيلية ذات سلاسل طويلة (12–24 ذرة كربون عادة)","المشبعة: لا تحتوي على روابط ثنائية بين ذرات الكربون","غير المشبعة: تحتوي على رابطة ثنائية أو أكثر","مثال صحيح على حمض مشبع مع صيغته (الستيريك أو البالمتيك)","مثال صحيح على حمض غير مشبع مع صيغته (الأوليك أو اللينوليك)"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الأحماض الدهنية: أحماض كربوكسيلية ذات سلاسل طويلة (12–24 ذرة كربون عادة)","marks":2},{"element":"المشبعة: لا تحتوي على روابط ثنائية بين ذرات الكربون","marks":1},{"element":"غير المشبعة: تحتوي على رابطة ثنائية أو أكثر","marks":1},{"element":"مثال صحيح على حمض مشبع مع صيغته (الستيريك أو البالمتيك)","marks":1},{"element":"مثال صحيح على حمض غير مشبع مع صيغته (الأوليك أو اللينوليك)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف الأحماض الدهنية: أحماض كربوكسيلية ذات سلاسل طويلة (12–24 ذرة كربون عادة)؛ المشبعة: لا تحتوي على روابط ثنائية بين ذرات الكربون؛ غير المشبعة: تحتوي على رابطة ثنائية أو أكثر؛ مثال صحيح على حمض مشبع مع صيغته (الستيريك أو البالمتيك)؛ مثال صحيح على حمض غير مشبع مع صيغته (الأوليك أو اللينوليك)"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الحمض الدهني بأنه كحول طويل السلسلة","عدّ الرابطة الثنائية C=O في مجموعة الكربوكسيل دليلًا على عدم التشبع","كتابة صيغة حمض غير مشبع دون رابطة C=C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.842Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CH₃(CH₂)₁₀COOH: فيه 1 + 10 + 1 = 12 ذرة كربون، ولا توجد فيه روابط ثنائية بين ذرات الكربون، فهو مشبع (حمض اللوريك). (ب) CH₃(CH₂)₇CH=CH(CH₂)₇COOH: فيه 1 + 7 + 2 + 7 + 1 = 18 ذرة كربون، ورابطة ثنائية C=C واحدة، فهو غير مشبع (حمض الأوليك). (ج) CH₃(CH₂)₁₆COOH: فيه 1 + 16 + 1 = 18 ذرة كربون، ولا روابط ثنائية C=C، فهو مشبع (حمض الستيريك). والتشبع وعدمه يُحدَّدان بوجود روابط ثنائية بين ذرات الكربون أو عدم وجودها، أما الرابطة C=O فهي بين ذرة كربون وذرة أكسجين، وتوجد في مجموعة الكربوكسيل في كل الأحماض الدهنية المشبعة وغير المشبعة.', '["(أ) مشبع، 12 ذرة كربون، لا روابط ثنائية C=C","(ب) غير مشبع، 18 ذرة كربون، رابطة ثنائية C=C واحدة","(ج) مشبع، 18 ذرة كربون، لا روابط ثنائية C=C","التشبع يتعلق بالروابط بين ذرات الكربون، والرابطة C=O بين الكربون والأكسجين وتوجد في كل الأحماض الدهنية"]'::jsonb, '["عدّ ذرات الكربون: ذرة في CH₃ + ذرات (CH₂) + ذرات CH=CH + ذرة في COOH.","البحث عن CH=CH في الصيغة: موجودة في (ب) فقط."]'::jsonb, '[{"element":"(أ) مشبع، 12 ذرة كربون، لا روابط ثنائية C=C","marks":1},{"element":"(ب) غير مشبع، 18 ذرة كربون، رابطة ثنائية C=C واحدة","marks":1},{"element":"(ج) مشبع، 18 ذرة كربون، لا روابط ثنائية C=C","marks":1},{"element":"التشبع يتعلق بالروابط بين ذرات الكربون، والرابطة C=O بين الكربون والأكسجين وتوجد في كل الأحماض الدهنية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) مشبع، 12 ذرة كربون، لا روابط ثنائية C=C؛ (ب) غير مشبع، 18 ذرة كربون، رابطة ثنائية C=C واحدة؛ (ج) مشبع، 18 ذرة كربون، لا روابط ثنائية C=C؛ التشبع يتعلق بالروابط بين ذرات الكربون، والرابطة C=O بين الكربون والأكسجين وتوجد في كل الأحماض الدهنية"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الرابطة C=O دليلًا على عدم التشبع فتُصنَّف كل الأحماض غير مشبعة","نسيان عدّ ذرة كربون CH₃ أو ذرة كربون COOH","الحكم على التشبع بعدد ذرات الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.842Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في حمض الستيريك 36 ذرة هيدروجين لـ 18 ذرة كربون، أي إن عدد ذرات الهيدروجين ضعف عدد ذرات الكربون، فالصيغة العامة للحمض الدهني المشبع CₙH₂ₙO₂. وحمض الأوليك فيه 34 ذرة هيدروجين، أي أقل من الستيريك بذرتين؛ فكل رابطة ثنائية C=C تنقص ذرتي هيدروجين. (ب) (س) C₁₆H₃₂O₂: عدد ذرات الهيدروجين 32 = 2 × 16، فهو حمض مشبع. (ص) C₂₀H₃₄O₂: الحمض المشبع ذو 20 ذرة كربون صيغته C₂₀H₄₀O₂، و(ص) فيه 34 ذرة هيدروجين فقط، فهو غير مشبع. (ج) النقص في ذرات الهيدروجين = 40 − 34 = 6 ذرات، وكل رابطة ثنائية تنقص ذرتين، فعدد الروابط الثنائية = 6 ÷ 2 = 3 روابط C=C.', '["العلاقة: الحمض المشبع CₙH₂ₙO₂، وكل رابطة C=C تنقص ذرتي هيدروجين","(س) C₁₆H₃₂O₂ مشبع؛ لأن صيغته تطابق CₙH₂ₙO₂ (32 = 2 × 16)","(ص) C₂₀H₃₄O₂ غير مشبع؛ لأن فيه ذرات هيدروجين أقل من الحمض المشبع المماثل","الحمض المشبع ذو 20 ذرة كربون صيغته C₂₀H₄₀O₂","عدد الروابط الثنائية في (ص) = (40 − 34) ÷ 2 = 3 روابط C=C"]'::jsonb, '["حمض الستيريك: 36 ÷ 18 = 2 ← الحمض المشبع CₙH₂ₙO₂.","الأوليك: 36 − 34 = 2 ← كل رابطة C=C تنقص ذرتي هيدروجين.","(س): 2 × 16 = 32 = عدد ذرات H ← مشبع.","(ص): 2 × 20 = 40 ≠ 34 ← غير مشبع.","عدد الروابط C=C = (40 − 34) ÷ 2 = 3."]'::jsonb, '[{"element":"العلاقة: الحمض المشبع CₙH₂ₙO₂، وكل رابطة C=C تنقص ذرتي هيدروجين","marks":1},{"element":"(س) C₁₆H₃₂O₂ مشبع؛ لأن صيغته تطابق CₙH₂ₙO₂ (32 = 2 × 16)","marks":1},{"element":"(ص) C₂₀H₃₄O₂ غير مشبع؛ لأن فيه ذرات هيدروجين أقل من الحمض المشبع المماثل","marks":1},{"element":"الحمض المشبع ذو 20 ذرة كربون صيغته C₂₀H₄₀O₂","marks":1},{"element":"عدد الروابط الثنائية في (ص) = (40 − 34) ÷ 2 = 3 روابط C=C","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: العلاقة: الحمض المشبع CₙH₂ₙO₂، وكل رابطة C=C تنقص ذرتي هيدروجين؛ (س) C₁₆H₃₂O₂ مشبع؛ لأن صيغته تطابق CₙH₂ₙO₂ (32 = 2 × 16)؛ (ص) C₂₀H₃₄O₂ غير مشبع؛ لأن فيه ذرات هيدروجين أقل من الحمض المشبع المماثل؛ الحمض المشبع ذو 20 ذرة كربون صيغته C₂₀H₄₀O₂؛ عدد الروابط الثنائية في (ص) = (40 − 34) ÷ 2 = 3 روابط C=C"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن (ص) مشبع لأن عدد ذرات الكربون فيه أكبر","عدّ النقص في ذرات الهيدروجين (6) عددًا للروابط الثنائية","مقارنة (ص) بحمض الستيريك ذي 18 ذرة كربون بدل الحمض المشبع ذي 20 ذرة كربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.842Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
