('mcq', 1, 'ما التركيب الكيميائي للصابون؟', null, null, '["جليسريدات ثلاثية غير مشبعة","إسترات من حمض دهني وكحول طويل السلسلة","ستيرويدات ذات أربع حلقات ملتحمة","أملاح الصوديوم للأحماض الدهنية"]'::jsonb, 'تذكر', 'تذكر تركيب', 'سهل', 'الكتاب ص 221 — الصابون'),
('mcq', 2, 'وُضع في أنبوب اختبار ماء وقليل من الزيت فتكونت طبقتان منفصلتان، ثم أُضيف قليل من الصابون ورُجّ الأنبوب جيدًا، فانتشر الزيت في الماء في صورة قطيرات صغيرة جدًّا ولم تعد الطبقتان واضحتين. ما تفسير ذلك؟', null, null, '["تفاعل الصابون مع الزيت فحوّله إلى جليسرول يذوب في الماء","ارتبطت السلاسل غير القطبية للصابون بالزيت، وذابت أطرافه القطبية في الماء","أصبح الزيت قطبيًّا بعد أن ذابت فيه الأطراف القطبية للصابون","رفع الصابون درجة حرارة الماء فأصبح الزيت قابلًا للذوبان فيه"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 221 — الصابون'),
('mcq', 3, 'ما الذي يجعل الطرف –COO⁻ Na⁺ في جزيء الصابون قابلًا للذوبان في الماء؟', null, null, '["احتواؤه على الرابطة الثنائية C=O التي تتفاعل مع الماء","أنه غير قطبي مثل جزيئات الماء","أنه طرف أيوني قطبي ينجذب إلى جزيئات الماء القطبية","أنه يحتوي على سلسلة هيدروكربونية قصيرة"]'::jsonb, 'فهم', 'تفسير خاصية', 'متوسط', 'الكتاب ص 221 — الصابون'),
('mcq', 4, 'يمثل الشكل الآتي جزيء صابون. أي جزأيه يرتبط بجزيئات الزيوت والأوساخ؟ ولماذا؟', null, '[{"src":"qimg/chem22/c6-l3a-soap.svg","alt":"صيغة هيكلية لجزيء: في اليسار ذرة كربون ترتبط برابطة ثنائية بذرة O (إلى أعلى) وبرابطة أحادية بذرة O⁻ يجاورها أيون Na⁺، ثم تمتد منها نحو اليمين سلسلة كربونية متعرجة طويلة (16 ذرة كربون في الجزيء كله). تحت الرسم قوسان: القوس (ص) تحت المجموعة –COO⁻ Na⁺ في الطرف الأيسر، والقوس (س) تحت السلسلة الهيدروكربونية الطويلة."}]'::jsonb, '["الجزء (س)؛ لأنه سلسلة هيدروكربونية غير قطبية","الجزء (س)؛ لأنه طرف قطبي يذوب في الماء","الجزء (ص)؛ لأنه أيوني يجذب الجزيئات غير القطبية","الجزء (ص)؛ لأنه سلسلة طويلة غير قطبية"]'::jsonb, 'فهم', 'تفسير من الشكل', 'متوسط', 'الكتاب ص 221 — التصبن والصابون'),
('mcq', 5, 'يبين الشكل الآتي جزيئات صابون تحيط بقطرة زيت في الماء. لماذا يمكن إزالة قطرة الزيت المحاطة بجزيئات الصابون بالماء؟', null, '[{"src":"qimg/chem22/c6-l3a-micelle.svg","alt":"رسم تخطيطي داخل وسط مائي كُتب في ركنه «ماء». في الوسط دائرة صفراء كُتب داخلها «زيت أو أوساخ»، تحيط بها 12 جزيئًا، لكل جزيء دائرة حمراء صغيرة يمتد منها خط متعرج. الخطوط المتعرجة تتجه نحو مركز الدائرة الصفراء وتنغرس أطرافها داخلها، والدوائر الحمراء تبقى خارجها في الماء. مفتاح الرموز في الأسفل: (1) الدائرة الحمراء، (2) الخط المتعرج."}]'::jsonb, '["لأن الأطراف (2) القطبية تذيب الزيت وتحوله إلى مادة قطبية","لأن الأطراف (1) القطبية تتجه نحو الماء وتذوب فيه فتحمل القطرة معه","لأن الأطراف (1) غير القطبية تتجه نحو الماء فتطرده من القطرة","لأن الصابون يتفاعل مع الزيت فيحوله إلى جليسرول ذائب في الماء"]'::jsonb, 'فهم', 'تفسير من الشكل', 'متوسط', 'الكتاب ص 221 — التصبن والصابون'),
('mcq', 6, 'لماذا لا يكفي الماء وحده لإزالة بقع الزيوت والشحوم عن الملابس؟', null, null, '["لأن الزيوت أكثف من الماء فتبقى ملتصقة بالقماش","لأن الماء يتفاعل مع الزيوت ويكوّن صابونًا لا يذوب","لأن الزيوت غير قطبية والماء قطبي، فلا تذوب فيه","لأن الزيوت مركبات أيونية لا تتفكك في الماء"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 219، 221 — الليبيدات والصابون'),
('mcq', 7, 'أي المركبات الآتية يمكن أن يعمل صابونًا يزيل الأوساخ الدهنية بالماء؟', null, null, '["CH₃(CH₂)₁₆CH₃","CH₃COO⁻ Na⁺","HOCH₂CH(OH)CH₂OH","CH₃(CH₂)₁₆COO⁻ Na⁺"]'::jsonb, 'تحليل', 'تطبيق في موقف جديد', 'صعب', 'الكتاب ص 221 — الصابون'),
('essay', 1, 'يمثل الشكل الآتي جزيء صابون. اشرح كيف يجعل تركيب الصابون منه عاملًا منظفًا فعالًا.', null, '[{"src":"qimg/chem22/c6-l3a-soap.svg","alt":"صيغة هيكلية لجزيء: في اليسار ذرة كربون ترتبط برابطة ثنائية بذرة O (إلى أعلى) وبرابطة أحادية بذرة O⁻ يجاورها أيون Na⁺، ثم تمتد منها نحو اليمين سلسلة كربونية متعرجة طويلة (16 ذرة كربون في الجزيء كله). تحت الرسم قوسان: القوس (ص) تحت المجموعة –COO⁻ Na⁺ في الطرف الأيسر، والقوس (س) تحت السلسلة الهيدروكربونية الطويلة."}]'::jsonb, null, 'فهم', 'شرح', 'متوسط', 'الكتاب ص 221 (س59 ص 233)'),
('essay', 2, 'اكتب الصيغة المكثفة لصابون بالميتات الصوديوم (ملح الصوديوم لحمض البالمتيك CH₃(CH₂)₁₄COOH)، وحدد عليها الطرف القطبي والطرف غير القطبي، ثم بيّن دور كل طرف في أثناء التنظيف.', null, null, null, 'تطبيق', 'كتابة صيغة وتحديد أجزاء', 'صعب', 'الكتاب ص 221 (س63 ص 233)'),
('essay', 3, 'لديك ثلاث مواد: جليسريد ثلاثي (ثلاثي ستيارات الجليسريل)، والجليسرول CH₂OH–CHOH–CH₂OH، وستيارات الصوديوم CH₃(CH₂)₁₆COO⁻ Na⁺. (أ) صنّف كل مادة من حيث القطبية: قطبية كلها، أو غير قطبية كلها، أو لها طرف قطبي وجزء غير قطبي. (ب) فسّر لماذا تستطيع ستيارات الصوديوم وحدها من بين الثلاث إزالة الأوساخ الدهنية باستعمال الماء.', null, null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 219–221 — الليبيدات والصابون')
