from (values
('mcq', 1, 3, 'الصابون عبارة عن أملاح الصوديوم للأحماض الدهنية، ولجزيئه طرفان: طرف قطبي (أيوني)، وآخر غير قطبي.', '["الجليسريدات الثلاثية (الزيوت والدهون) هي المادة التي يُصنع منها الصابون، وليست الصابون نفسه.","الإستر المكوّن من حمض دهني وكحول طويل السلسلة هو الشمع لا الصابون.","الستيرويدات ليبيدات حلقية، وليس فيها طرف أيوني كالصابون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('mcq', 2, 1, 'جزيئات الزيت غير قطبية فترتبط بالطرف غير القطبي (السلسلة الهيدروكربونية) لجزيئات الصابون، في حين يبقى الطرف القطبي ذائبًا في الماء؛ فتنتشر قطيرات الزيت المحاطة بالصابون في الماء.', '["الصابون لا يتفاعل كيميائيًّا مع الزيت؛ فالجليسرول ينتج من تصبن الجليسريد الثلاثي بقاعدة قوية، لا من رجّ الزيت بالصابون.","","الأطراف القطبية للصابون تبقى في الماء ولا تذوب في الزيت، والزيت يبقى غير قطبي.","الصابون لا يرفع درجة حرارة الماء، والزيت غير القطبي لا يذوب في الماء بالتسخين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('mcq', 3, 2, 'الطرف –COO⁻ Na⁺ يتكون من أيون كربوكسيلات سالب وأيون صوديوم موجب، فهو طرف أيوني قطبي، والماء مذيب قطبي، فينجذب هذا الطرف إلى جزيئات الماء ويذوب فيه.', '["الرابطة C=O لا تتفاعل مع الماء، وسبب الذوبان هو الشحنات الأيونية في هذا الطرف.","الماء مذيب قطبي، والطرف –COO⁻ Na⁺ أيوني قطبي لا غير قطبي.","","الطرف –COO⁻ Na⁺ لا يحتوي على سلسلة هيدروكربونية؛ فالسلسلة هي الطرف غير القطبي الذي لا يذوب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('mcq', 4, 0, 'جزيئات الأوساخ والزيوت غير قطبية، فترتبط بالطرف غير القطبي لجزيء الصابون، وهو السلسلة الهيدروكربونية الطويلة (س)، أما الطرف (ص) –COO⁻ Na⁺ فقطبي يذوب في الماء.', '["","الجزء (س) غير قطبي ولا يذوب في الماء؛ والطرف القطبي هو (ص).","الطرف الأيوني القطبي (ص) ينجذب إلى الماء القطبي لا إلى الجزيئات غير القطبية.","الجزء (ص) هو مجموعة –COO⁻ Na⁺ القطبية، وليس السلسلة الطويلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('mcq', 5, 1, 'الأطراف غير القطبية (2) ترتبط بجزيئات الزيت غير القطبية، والأطراف القطبية (1) تبقى في الماء وتذوب فيه، فتُزال جزيئات الصابون المحملة بالزيت والأوساخ مع الماء.', '["الأطراف (2) هي السلاسل غير القطبية، وهي ترتبط بالزيت ولا تحوله إلى مادة قطبية.","","الأطراف (1) هي الرؤوس القطبية لا غير القطبية، وهي تذوب في الماء ولا تطرده.","الصابون لا يتفاعل كيميائيًّا مع الزيت في أثناء التنظيف، بل يرتبط به بطرفه غير القطبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('mcq', 6, 2, 'الزيوت والشحوم جزيئات غير قطبية، والماء قطبي، فلا تذوب فيه؛ لذلك يُحتاج إلى الصابون الذي له طرف غير قطبي يرتبط بالزيت وطرف قطبي يذوب في الماء.', '["الزيوت أقل كثافة من الماء لا أكثف، والسبب الحقيقي هو اختلاف القطبية.","الماء وحده لا يحول الزيوت إلى صابون؛ فالتصبن يحتاج إلى قاعدة قوية مثل NaOH.","","الزيوت جزيئات غير قطبية وليست مركبات أيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('mcq', 7, 3, 'الصابون يحتاج إلى طرف قطبي يذوب في الماء وسلسلة طويلة غير قطبية ترتبط بالأوساخ، و CH₃(CH₂)₁₆COO⁻ Na⁺ ملح صوديوم لحمض دهني (ستيارات الصوديوم) يجمع الطرفين.', '["هذا ألكان غير قطبي كليًّا، ليس له طرف قطبي يذوب في الماء.","له طرف قطبي أيوني، لكن سلسلته قصيرة جدًّا فلا يكفي جزؤه غير القطبي للارتباط بالأوساخ الدهنية.","هذا الجليسرول، وهو جزيء قطبي ليس له سلسلة طويلة غير قطبية ترتبط بالأوساخ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لجزيء الصابون طرفان: الطرف (ص) –COO⁻ Na⁺ قطبي (أيوني) يذوب في الماء، والطرف (س) سلسلة هيدروكربونية طويلة غير قطبية. جزيئات الأوساخ والزيوت غير قطبية فترتبط بالطرف غير القطبي (س)، في حين يبقى الطرف القطبي (ص) ذائبًا في الماء؛ وهكذا يمكن إزالة جزيئات الصابون المحملة بالأوساخ باستعمال الماء.', '["الطرف (ص) قطبي يذوب في الماء","الطرف (س) سلسلة هيدروكربونية غير قطبية","الأوساخ والزيوت غير القطبية ترتبط بالطرف غير القطبي","الطرف القطبي يذوب في الماء فتُزال جزيئات الصابون المحملة بالأوساخ بالماء"]'::jsonb, '[]'::jsonb, '[{"element":"الطرف (ص) قطبي يذوب في الماء","marks":1},{"element":"الطرف (س) سلسلة هيدروكربونية غير قطبية","marks":1},{"element":"الأوساخ والزيوت غير القطبية ترتبط بالطرف غير القطبي","marks":1},{"element":"الطرف القطبي يذوب في الماء فتُزال جزيئات الصابون المحملة بالأوساخ بالماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الطرف (ص) قطبي يذوب في الماء؛ الطرف (س) سلسلة هيدروكربونية غير قطبية؛ الأوساخ والزيوت غير القطبية ترتبط بالطرف غير القطبي؛ الطرف القطبي يذوب في الماء فتُزال جزيئات الصابون المحملة بالأوساخ بالماء"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الطرف القطبي هو الذي يرتبط بالأوساخ","القول إن الصابون يتفاعل كيميائيًّا مع الأوساخ","إغفال دور الماء في حمل الأوساخ بعيدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.843Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الصيغة: CH₃(CH₂)₁₄COO⁻ Na⁺. الطرف القطبي هو –COO⁻ Na⁺ (مجموعة الكربوكسيلات مع أيون الصوديوم)، والطرف غير القطبي هو السلسلة الهيدروكربونية CH₃(CH₂)₁₄–. في أثناء التنظيف يرتبط الطرف غير القطبي بجزيئات الأوساخ والزيوت غير القطبية، ويذوب الطرف القطبي في الماء، فيُزال الصابون المحمل بالأوساخ مع الماء.', '["الصيغة الصحيحة CH₃(CH₂)₁₄COO⁻ Na⁺","الطرف القطبي: –COO⁻ Na⁺","الطرف غير القطبي: السلسلة CH₃(CH₂)₁₄–","دور كل طرف: غير القطبي يرتبط بالأوساخ، والقطبي يذوب في الماء"]'::jsonb, '["استبدال ذرة H في مجموعة –COOH بأيون Na⁺ → –COO⁻ Na⁺.","بقية الصيغة كما هي: CH₃(CH₂)₁₄– (16 ذرة كربون في المجموع)."]'::jsonb, '[{"element":"الصيغة الصحيحة CH₃(CH₂)₁₄COO⁻ Na⁺","marks":2},{"element":"الطرف القطبي: –COO⁻ Na⁺","marks":1},{"element":"الطرف غير القطبي: السلسلة CH₃(CH₂)₁₄–","marks":1},{"element":"دور كل طرف: غير القطبي يرتبط بالأوساخ، والقطبي يذوب في الماء","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الصيغة الصحيحة CH₃(CH₂)₁₄COO⁻ Na⁺؛ الطرف القطبي: –COO⁻ Na⁺؛ الطرف غير القطبي: السلسلة CH₃(CH₂)₁₄–؛ دور كل طرف: غير القطبي يرتبط بالأوساخ، والقطبي يذوب في الماء"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة CH₃(CH₂)₁₄COONa دون إظهار الشحنتين ثم عدّها جزءًا غير قطبي","تحديد السلسلة الهيدروكربونية على أنها الطرف القطبي","تغيير عدد ذرات الكربون في الصيغة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.844Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الجليسريد الثلاثي: ثلاث سلاسل هيدروكربونية طويلة مرتبطة بالجليسرول بروابط إستر، فهو غير قطبي كله ولا يذوب في الماء. الجليسرول: جزيء صغير فيه ثلاث مجموعات –OH، فهو قطبي وليس فيه سلسلة طويلة غير قطبية. ستيارات الصوديوم: له طرف أيوني قطبي –COO⁻ Na⁺ وسلسلة هيدروكربونية طويلة غير قطبية CH₃(CH₂)₁₆–. (ب) الأوساخ والزيوت غير قطبية، فترتبط بالسلسلة غير القطبية لستيارات الصوديوم، في حين يذوب الطرف القطبي في الماء، فتُزال جزيئات الصابون المحملة بالأوساخ بالماء. أما الجليسريد الثلاثي فليس له طرف يذوب في الماء فلا يستطيع حمل الأوساخ إلى الماء، والجليسرول ليس فيه جزء غير قطبي يرتبط بالأوساخ.', '["الجليسريد الثلاثي غير قطبي كله، فلا يذوب في الماء","الجليسرول قطبي (ثلاث مجموعات –OH)، وليس فيه سلسلة طويلة غير قطبية","ستيارات الصوديوم له طرف أيوني قطبي وسلسلة طويلة غير قطبية","ستيارات الصوديوم: السلسلة غير القطبية ترتبط بالأوساخ الدهنية، والطرف القطبي يذوب في الماء فتُزال الأوساخ بالماء","الجليسريد الثلاثي لا طرف له يذوب في الماء، والجليسرول لا جزء فيه يرتبط بالأوساخ، فلا يصلح أي منهما منظفًا"]'::jsonb, '[]'::jsonb, '[{"element":"الجليسريد الثلاثي غير قطبي كله، فلا يذوب في الماء","marks":1},{"element":"الجليسرول قطبي (ثلاث مجموعات –OH)، وليس فيه سلسلة طويلة غير قطبية","marks":1},{"element":"ستيارات الصوديوم له طرف أيوني قطبي وسلسلة طويلة غير قطبية","marks":1},{"element":"ستيارات الصوديوم: السلسلة غير القطبية ترتبط بالأوساخ الدهنية، والطرف القطبي يذوب في الماء فتُزال الأوساخ بالماء","marks":2},{"element":"الجليسريد الثلاثي لا طرف له يذوب في الماء، والجليسرول لا جزء فيه يرتبط بالأوساخ، فلا يصلح أي منهما منظفًا","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: الجليسريد الثلاثي غير قطبي كله، فلا يذوب في الماء؛ الجليسرول قطبي (ثلاث مجموعات –OH)، وليس فيه سلسلة طويلة غير قطبية؛ ستيارات الصوديوم له طرف أيوني قطبي وسلسلة طويلة غير قطبية؛ ستيارات الصوديوم: السلسلة غير القطبية ترتبط بالأوساخ الدهنية، والطرف القطبي يذوب في الماء فتُزال الأوساخ بالماء؛ الجليسريد الثلاثي لا طرف له يذوب في الماء، والجليسرول لا جزء فيه يرتبط بالأوساخ، فلا يصلح أي منهما منظفًا"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجليسرول منظفًا لأنه يذوب في الماء","عدّ الجليسريد الثلاثي منظفًا لأنه يحتوي على سلاسل غير قطبية","القول إن الطرف القطبي للصابون هو الذي يرتبط بالأوساخ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.844Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
