insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'مما يتكون الجليسريد الثلاثي؟', null, null, '["ثلاثة أحماض أمينية ترتبط بروابط ببتيدية","ثلاث وحدات جلوكوز مرتبطة في سلسلة","ثلاثة أحماض دهنية ترتبط بجزيء جليسرول","حمض دهني واحد يرتبط بكحول طويل السلسلة"]'::jsonb, 'تذكر', 'تذكر تركيب', 'سهل', 'الكتاب ص 220 — الجليسريدات الثلاثية'),
('mcq', 2, 'ما نوع الرابطة التي تصل كل سلسلة هيدروكربونية بالهيكل CH₂–CH–CH₂ في الجزيء المبين في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c6-l3a-triglyceride.svg","alt":"صيغة بنائية مكثفة: ثلاث ذرات كربون مترابطة رأسيًّا: CH₂ في الأعلى، ثم CH، ثم CH₂ في الأسفل. ترتبط كل منها من اليمين بذرة أكسجين O برابطة أحادية، وترتبط ذرة الأكسجين هذه بذرة كربون C ترتبط من أعلى بذرة O برابطة ثنائية، ثم ترتبط ذرة الكربون هذه بالسلسلة (CH₂)₁₆–CH₃. أي إن كل سطر من السطور الثلاثة المتماثلة هو –O–C(=O)–(CH₂)₁₆–CH₃."}]'::jsonb, '["روابط ببتيدية","روابط هيدروجينية","روابط أيونية","روابط إستر"]'::jsonb, 'فهم', 'تحليل الشكل', 'سهل', 'الكتاب ص 220 — الشكل 6-14'),
('mcq', 3, 'ما الذي يميز جزيء الجليسرول الذي يدخل في تكوين الجليسريدات الثلاثية؟', null, null, '["يتكون من ثلاث ذرات كربون ترتبط كل منها بمجموعة هيدروكسيل","يتكون من ثلاث ذرات كربون ترتبط كل منها بمجموعة كربوكسيل","يتكون من سلسلة طويلة فيها 12–24 ذرة كربون","يتكون من أربع حلقات كربونية ملتحمة"]'::jsonb, 'تذكر', 'تذكر تركيب', 'متوسط', 'الكتاب ص 220 — الجليسريدات الثلاثية'),
('mcq', 4, 'كم جزيء ماء يتكوّن عند تكوين جزيء واحد من الجليسريد الثلاثي من الجليسرول والأحماض الدهنية؟', null, null, '["جزيء واحد","ثلاثة جزيئات","جزيئان","ستة جزيئات"]'::jsonb, 'تطبيق', 'استنتاج من معادلة', 'متوسط', 'الكتاب ص 220 — الشكل 6-14'),
('mcq', 5, 'أي المقارنات الآتية بين الزيوت والدهون صحيحة؟', null, null, '["الزيوت صلبة في درجة حرارة الغرفة، والدهون سائلة","الزيوت مصدرها حيواني غالبًا، والدهون مصدرها نباتي","الزيوت أغنى بالأحماض الدهنية المشبعة من الدهون","الزيوت سائلة في درجة حرارة الغرفة، والدهون صلبة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 220 — الشكل 6-15'),
('mcq', 6, 'أي الجليسريدين الثلاثيين درجة انصهاره أعلى: المأخوذ من دهن البقر أم المأخوذ من زيت الزيتون؟ ولماذا؟', null, null, '["زيت الزيتون؛ لأنه يحتوي على أحماض دهنية غير مشبعة أكثر","زيت الزيتون؛ لأن مصدره نباتي فجزيئاته أكبر حجمًا","دهن البقر؛ لأنه يحتوي على أحماض دهنية مشبعة أكثر","دهن البقر؛ لأن جزيئاته تحتوي على روابط ثنائية أكثر"]'::jsonb, 'تطبيق', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 220 (س58 ص 233)'),
('mcq', 7, 'يمثل الشكل الآتي جليسريدين ثلاثيين (1) و(2). أيهما يُتوقع أن يكون سائلًا (زيتًا) في درجة حرارة الغرفة؟ ولماذا؟', null, '[{"src":"qimg/chem22/c6-l3a-tg-pair.svg","alt":"صيغتان لجليسريدين ثلاثيين مرقمين (1) و(2). في كل منهما ثلاث مجموعات مترابطة رأسيًّا: CH₂ ثم CH ثم CH₂، ترتبط كل منها بذرة O، ثم بذرة كربون مرتبطة برابطة ثنائية بذرة O، ثم تمتد منها سلسلة كربونية هيكلية متعرجة (18 ذرة كربون مع ذرة الكربونيل). في (1): السلاسل الثلاث مستقيمة متوازية وجميع روابطها بين ذرات الكربون أحادية. في (2): في كل سلسلة رابطة ثنائية C=C بين ذرتي الكربون 9 و10 بترتيب سيس، فتنثني السلاسل الثلاث عندها نحو الأسفل."}]'::jsonb, '["(2)؛ لأن انثناء سلاسله عند الروابط الثنائية يمنع تراص جزيئاته","(1)؛ لأن سلاسله المستقيمة تمنع تجاذب جزيئاته","(1)؛ لأنه لا يحتوي على روابط إستر","(2)؛ لأن روابطه الثنائية تزيد قوى التجاذب بين جزيئاته"]'::jsonb, 'تحليل', 'تنبؤ من الشكل', 'صعب', 'الكتاب ص 220 — الشكل 6-15'),
('essay', 1, 'صف تكوين الجليسريد الثلاثي: ما المواد المتفاعلة؟ وما المجموعات الوظيفية التي تتحد؟ وما نوع الرابطة الناتجة؟ وما الناتج الثانوي وعدد جزيئاته؟', null, null, null, 'فهم', 'وصف', 'سهل', 'الكتاب ص 220 — الشكل 6-14'),
('essay', 2, 'قارن بين الزيوت والدهون من حيث: الحالة الفيزيائية في درجة حرارة الغرفة، والمصدر الغالب، ونوع الأحماض الدهنية الغالبة فيها، ثم فسّر اختلاف حالتيهما الفيزيائيتين.', null, null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 220 — الشكل 6-15 (س58 ص 233)'),
('essay', 3, 'يتكون جليسريد ثلاثي من تفاعل جزيء جليسرول C₃H₈O₃ مع ثلاثة جزيئات من حمض الستيريك C₁₈H₃₆O₂. (أ) كم جزيء ماء ينتج؟ (ب) استنتج الصيغة الجزيئية للجليسريد الثلاثي. (ج) احسب كتلته المولية علمًا بأن الكتل المولية: C = 12.01 g/mol، H = 1.008 g/mol، O = 16.00 g/mol.', null, null, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 220 — الشكل 6-14')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
