from (values
('mcq', 1, 2, 'يتكون الجليسريد الثلاثي عندما ترتبط ثلاثة أحماض دهنية بجزيء جليسرول (جزيء من ثلاث ذرات كربون ترتبط كل منها بمجموعة هيدروكسيل).', '["الأحماض الأمينية المرتبطة بروابط ببتيدية تكوّن الببتيدات والبروتينات.","وحدات الجلوكوز تكوّن الكربوهيدرات كالنشا، ولا تدخل في تكوين الجليسريد الثلاثي.","","اتحاد حمض دهني مع كحول طويل السلسلة يكوّن الشمع لا الجليسريد الثلاثي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.844Z"}'::jsonb),
('mcq', 2, 3, 'في الشكل ترتبط كل سلسلة حمض دهني بالجليسرول عبر المجموعة –O–C(=O)–، وهي رابطة الإستر التي تتكون عندما تتحد مجموعات الهيدروكسيل في الجليسرول بمجموعات الكربوكسيل في الأحماض الدهنية.', '["الرابطة الببتيدية –CO–NH– تربط الأحماض الأمينية، ولا توجد ذرات نيتروجين في الشكل.","الروابط الهيدروجينية قوى بين الجزيئات، والأحماض الدهنية هنا مرتبطة تساهميًّا بالجليسرول.","لا توجد أيونات في الجزيء؛ فالروابط فيه تساهمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.844Z"}'::jsonb),
('mcq', 3, 0, 'الجليسرول جزيء من ثلاث ذرات كربون، ترتبط كل منها بمجموعة هيدروكسيل –OH (CH₂OH–CHOH–CH₂OH).', '["","مجموعات الكربوكسيل توجد في الأحماض الدهنية، أما الجليسرول فيحتوي على مجموعات هيدروكسيل.","السلسلة الطويلة ذات 12–24 ذرة كربون صفة الأحماض الدهنية لا الجليسرول.","الحلقات الأربع الملتحمة تميز الستيرويدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-15T02:47:48.844Z"}'::jsonb),
('mcq', 4, 1, 'كل رابطة إستر تتكون باتحاد مجموعة –OH من الجليسرول مع مجموعة –COOH من حمض دهني ويتحرر جزيء ماء واحد، وفي الجليسريد الثلاثي ثلاث روابط إستر؛ فيتكون 3H₂O.', '["هذا يقابل تكوين رابطة إستر واحدة فقط، والجليسريد الثلاثي فيه ثلاث روابط.","","الجليسرول فيه ثلاث مجموعات –OH كلها ترتبط بأحماض دهنية، لا اثنتان.","عُدّ كل من الجليسرول والحمض كأنه يطلق جزيء ماء مستقلًّا، والصحيح جزيء ماء واحد لكل رابطة إستر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb),
('mcq', 5, 3, 'الجليسريدات الثلاثية السائلة في درجة حرارة الغرفة تسمى زيوتًا، والصلبة تسمى دهونًا. ومعظم الزيوت نباتية غنية بالأحماض الدهنية غير المشبعة، والدهون حيوانية أغنى بالأحماض المشبعة.', '["هذا عكس الصحيح؛ فالزيوت سائلة والدهون صلبة في درجة حرارة الغرفة.","هذا عكس الصحيح؛ فمعظم الزيوت نباتية، والدهون حيوانية.","هذا عكس الصحيح؛ فالدهون تحتوي على كمية أكبر من الأحماض الدهنية المشبعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb),
('mcq', 6, 2, 'دهن البقر دهن حيواني يحتوي على كمية أكبر من الأحماض الدهنية المشبعة ذات السلاسل المستقيمة التي تتراص وتتجاذب جزيئاتها؛ فدرجة انصهاره أعلى، ولذا يكون صلبًا في درجة حرارة الغرفة.', '["الأحماض غير المشبعة (سيس) تخفض درجة الانصهار لأنها تمنع التراص، فزيت الزيتون أقل انصهارًا.","المصدر النباتي لا يعني جزيئات أكبر، وزيت الزيتون سائل في درجة حرارة الغرفة فدرجة انصهاره أقل.","","الدهون الحيوانية أغنى بالأحماض المشبعة، أي فيها روابط ثنائية أقل لا أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb),
('mcq', 7, 0, 'سلاسل (2) غير مشبعة وفيها روابط ثنائية سيس تسبب انثناءها، فلا تتراص جزيئاته وتكون قوى التجاذب بينها أقل؛ فدرجة انصهاره منخفضة ويكون سائلًا (زيتًا). أما (1) فسلاسله المشبعة المستقيمة تتراص، فيكون صلبًا (دهنًا).', '["","السلاسل المستقيمة تسمح بالتراص وتزيد التجاذب، فيكون (1) صلبًا لا سائلًا.","كلا الجليسريدين فيه ثلاث روابط إستر، ووجودها لا يحدد الحالة الفيزيائية.","الاختيار صحيح لكن التعليل خطأ؛ فالروابط الثنائية سيس تقلل قوى التجاذب ولا تزيدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتكون الجليسريد الثلاثي من تفاعل جزيء جليسرول مع ثلاثة أحماض دهنية؛ إذ تتحد مجموعات الهيدروكسيل (–OH) الثلاث في الجليسرول بمجموعات الكربوكسيل (–COOH) في الأحماض الدهنية، فتتكون ثلاث روابط إستر، وينتج ثلاثة جزيئات ماء (3H₂O) ناتجًا ثانويًّا.', '["المتفاعلات: جليسرول وثلاثة أحماض دهنية","اتحاد مجموعات –OH في الجليسرول بمجموعات –COOH في الأحماض الدهنية","الرابطة الناتجة: رابطة إستر (ثلاث روابط)","الناتج الثانوي: 3H₂O"]'::jsonb, '[]'::jsonb, '[{"element":"المتفاعلات: جليسرول وثلاثة أحماض دهنية","marks":1},{"element":"اتحاد مجموعات –OH في الجليسرول بمجموعات –COOH في الأحماض الدهنية","marks":1},{"element":"الرابطة الناتجة: رابطة إستر (ثلاث روابط)","marks":1},{"element":"الناتج الثانوي: 3H₂O","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: المتفاعلات: جليسرول وثلاثة أحماض دهنية؛ اتحاد مجموعات –OH في الجليسرول بمجموعات –COOH في الأحماض الدهنية؛ الرابطة الناتجة: رابطة إستر (ثلاث روابط)؛ الناتج الثانوي: 3H₂O"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرابطة الناتجة رابطة ببتيدية","كتابة جزيء ماء واحد بدل ثلاثة","عكس المجموعات: نسبة الكربوكسيل إلى الجليسرول والهيدروكسيل إلى الأحماض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الزيوت: جليسريدات ثلاثية سائلة في درجة حرارة الغرفة، مصدرها غالبًا نباتي، وتحتوي على أحماض دهنية غير مشبعة. الدهون: جليسريدات ثلاثية صلبة في درجة حرارة الغرفة، مصدرها غالبًا حيواني، وتحتوي على كمية أكبر من الأحماض الدهنية المشبعة. التفسير: الروابط الثنائية في الأحماض غير المشبعة بالشكل سيس تسبب انثناء السلاسل فلا تتراص الجزيئات، وتقل قوى التجاذب بينها، فتنخفض درجة الانصهار وتكون الزيوت سائلة؛ أما السلاسل المشبعة المستقيمة فتتراص وتزداد قوى التجاذب، فتكون الدهون صلبة.', '["الحالة: الزيوت سائلة والدهون صلبة في درجة حرارة الغرفة","المصدر: الزيوت نباتية غالبًا والدهون حيوانية غالبًا","الأحماض: الزيوت غير مشبعة والدهون أغنى بالمشبعة","التفسير: انثناء السلاسل غير المشبعة (سيس) يمنع التراص فتقل قوى التجاذب","السلاسل المشبعة المستقيمة تتراص فتزداد قوى التجاذب ودرجة الانصهار"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة: الزيوت سائلة والدهون صلبة في درجة حرارة الغرفة","marks":1},{"element":"المصدر: الزيوت نباتية غالبًا والدهون حيوانية غالبًا","marks":1},{"element":"الأحماض: الزيوت غير مشبعة والدهون أغنى بالمشبعة","marks":1},{"element":"التفسير: انثناء السلاسل غير المشبعة (سيس) يمنع التراص فتقل قوى التجاذب","marks":1},{"element":"السلاسل المشبعة المستقيمة تتراص فتزداد قوى التجاذب ودرجة الانصهار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الحالة: الزيوت سائلة والدهون صلبة في درجة حرارة الغرفة؛ المصدر: الزيوت نباتية غالبًا والدهون حيوانية غالبًا؛ الأحماض: الزيوت غير مشبعة والدهون أغنى بالمشبعة؛ التفسير: انثناء السلاسل غير المشبعة (سيس) يمنع التراص فتقل قوى التجاذب؛ السلاسل المشبعة المستقيمة تتراص فتزداد قوى التجاذب ودرجة الانصهار"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الحالة الفيزيائية للزيوت والدهون","القول إن الروابط الثنائية تزيد قوى التجاذب","التفسير بالمصدر النباتي أو الحيواني وحده دون التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تتكون ثلاث روابط إستر فينتج 3 جزيئات ماء. (ب) C₃H₈O₃ + 3C₁₈H₃₆O₂ → C₅₇H₁₁₀O₆ + 3H₂O؛ فالصيغة الجزيئية C₅₇H₁₁₀O₆. (ج) الكتلة المولية = 57 × 12.01 + 110 × 1.008 + 6 × 16.00 = 891.5 g/mol.', '["عدد جزيئات الماء: 3","الصيغة الجزيئية C₅₇H₁₁₀O₆","التعويض الصحيح في حساب الكتلة المولية","الكتلة المولية 891.5 g/mol"]'::jsonb, '["كل رابطة إستر تطلق جزيء H₂O واحدًا، وعدد الروابط 3 → 3H₂O.","مجموع ذرات المتفاعلات: C = 3 + 3 × 18 = 57، H = 8 + 3 × 36 = 116، O = 3 + 3 × 2 = 9.","طرح 3H₂O (H = 6، O = 3): C₅₇H₁₁₀O₆.","الكتلة المولية = 57 × 12.01 + 110 × 1.008 + 6 × 16.00 = 684.57 + 110.88 + 96.00 = 891.45 ≈ 891.5 g/mol."]'::jsonb, '[{"element":"عدد جزيئات الماء: 3","marks":1},{"element":"الصيغة الجزيئية C₅₇H₁₁₀O₆","marks":2},{"element":"التعويض الصحيح في حساب الكتلة المولية","marks":1},{"element":"الكتلة المولية 891.5 g/mol","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: عدد جزيئات الماء: 3؛ الصيغة الجزيئية C₅₇H₁₁₀O₆؛ التعويض الصحيح في حساب الكتلة المولية؛ الكتلة المولية 891.5 g/mol"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان طرح جزيئات الماء فتكون الصيغة C₅₇H₁₁₆O₉","طرح جزيء ماء واحد فقط","استعمال الكتلة المولية للهيدروجين 1 g/mol أو أخطاء في الضرب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.845Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
