from (values
('mcq', 1, 'ما المقصود بالتصبن؟', null, null, '["إضافة الهيدروجين إلى الروابط الثنائية في سلاسل الأحماض الدهنية غير المشبعة","اتحاد الجليسرول بثلاثة أحماض دهنية بروابط إستر مع تحرر جزيئات الماء","تميّه الجليسريد الثلاثي بمحلول مائي لقاعدة قوية لتكوين أملاح الكربوكسيلات والجليسرول","اتحاد حمض دهني مع كحول طويل السلسلة لتكوين مادة صلبة طرية"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('mcq', 2, 'ما الصيغة التي تمثل الناتج المجهول (علامة الاستفهام) في معادلة التصبن الآتية؟', null, '[{"src":"qimg/chem22/c6-l3b-sapon-blank.svg","alt":"معادلة كيميائية. في اليسار جليسريد ثلاثي بصيغة مكثفة: CH₂ ثم CH ثم CH₂ مترابطة رأسيًّا، ترتبط كل منها بالمجموعة –O–C(=O)–(CH₂)₁₀CH₃، ثم إشارة + و3NaOH، ثم سهم يتجه نحو اليمين. بعد السهم: CH₂OH ثم CHOH ثم CH₂OH مترابطة رأسيًّا، ثم إشارة + والعدد 3، ثم مربع منقط بداخله علامة استفهام تمثل ناتجًا مجهولًا."}]'::jsonb, '["CH₃(CH₂)₁₀COO⁻Na⁺","CH₃(CH₂)₁₀COOH","(CH₃(CH₂)₁₀COO)₃Na","CH₃(CH₂)₁₂COO⁻Na⁺"]'::jsonb, 'تطبيق', 'إكمال معادلة', 'متوسط', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('mcq', 3, 'ما كتلة هيدروكسيد الصوديوم NaOH (الكتلة المولية 40.00 g/mol) اللازمة لتصبن 0.25 mol من جليسريد ثلاثي تصبنًا تامًّا؟', null, null, '["10 g","3.3 g","120 g","30 g"]'::jsonb, 'تطبيق', 'حساب كمية متفاعل', 'متوسط', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('mcq', 4, 'ما عدد الروابط التي تتحلل في جزيء الجليسريد الثلاثي عند تصبنه تصبنًا تامًّا؟ وما نوعها؟', null, null, '["ثلاث روابط ثنائية بين ذرات الكربون","ثلاث روابط إستر","رابطة إستر واحدة","ثلاث روابط ببتيدية"]'::jsonb, 'فهم', 'تحديد نوع الرابطة', 'سهل', 'الكتاب ص 221 — تجربة تفاعل التصبن'),
('mcq', 5, 'يُصبَّن الجليسريد الثلاثي المبين في الشكل الآتي بمحلول هيدروكسيد الصوديوم NaOH. ما نواتج التفاعل؟', null, '[{"src":"qimg/chem22/c6-l3b-mixed-tg.svg","alt":"صيغة مكثفة لجليسريد ثلاثي: ثلاث مجموعات مترابطة رأسيًّا هي CH₂ ثم CH ثم CH₂، ترتبط كل منها بذرة O، ثم بذرة C مرتبطة برابطة ثنائية بذرة O أخرى، ثم بسلسلة هيدروكربونية. السلسلة العليا (CH₂)₁₄CH₃، والسلسلة الوسطى (CH₂)₇CH=CH(CH₂)₇CH₃ وفيها رابطة ثنائية واحدة بين ذرتي كربون، والسلسلة السفلى (CH₂)₁₆CH₃."}]'::jsonb, '["الجليسرول وثلاثة جزيئات من ملح صوديوم واحد","الجليسرول وثلاثة أحماض دهنية حرة مختلفة","الجليسرول وثلاثة أملاح صوديوم مختلفة، أحدها غير مشبع","الجليسرول وثلاثة أملاح صوديوم مشبعة جميعها"]'::jsonb, 'تطبيق', 'توقع النواتج', 'صعب', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('mcq', 6, 'في تجربة تحضير الصابون، أُضيف محلول NaCl المشبع إلى خليط التصبن بعد تبريده، فظهرت كتل صغيرة صلبة. ما تفسير ذلك؟', null, null, '["الصابون ليس شديد الذوبان في الماء المالح، فينفصل في صورة كتل صلبة","يتفاعل NaCl مع الجليسرول فيكوّن راسبًا صلبًا من كلوريد الجليسرول","يعمل NaCl عاملًا محفزًا يسرّع تحلل روابط الإستر فيتكوّن الصابون","يتفاعل NaCl مع NaOH الزائد فيتكوّن ملح صلب يترسب في الكأس"]'::jsonb, 'فهم', 'تفسير خطوة عملية', 'متوسط', 'الكتاب ص 221 — تجربة تفاعل التصبن'),
('mcq', 7, 'سخّن طالب زيتًا نباتيًّا مع ماء نقي مدة طويلة دون إضافة أي قاعدة، فلم يحصل على صابون. ما سبب ذلك؟', null, null, '["لأن الزيت النباتي لا يحتوي على روابط إستر قابلة للتحلل","لأن التسخين يهدرج الروابط الثنائية فيمنع حدوث التصبن","لأن الماء يذيب الجليسريد الثلاثي فيمنع تفكك جزيئاته","لأن التصبن يحتاج إلى قاعدة قوية تحوّل الأحماض الدهنية إلى أملاح"]'::jsonb, 'تحليل', 'تفسير ملاحظة', 'صعب', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('essay', 1, 'عرّف التصبن، ثم اكتب معادلة تصبن الجليسريد الثلاثي المبين في الشكل الآتي بهيدروكسيد الصوديوم NaOH، وحدد النواتج التي تُعدّ صابونًا.', null, '[{"src":"qimg/chem22/c6-l3b-mixed-tg.svg","alt":"صيغة مكثفة لجليسريد ثلاثي: ثلاث مجموعات مترابطة رأسيًّا هي CH₂ ثم CH ثم CH₂، ترتبط كل منها بذرة O، ثم بذرة C مرتبطة برابطة ثنائية بذرة O أخرى، ثم بسلسلة هيدروكربونية. السلسلة العليا (CH₂)₁₄CH₃، والسلسلة الوسطى (CH₂)₇CH=CH(CH₂)₇CH₃ وفيها رابطة ثنائية واحدة بين ذرتي كربون، والسلسلة السفلى (CH₂)₁₆CH₃."}]'::jsonb, null, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('essay', 2, 'صُبِّنت عينة كتلتها 80.7 g من الجليسريد الثلاثي ثلاثي بالميتات الجليسريل C₅₁H₉₈O₆ (المكوَّن من الجليسرول وثلاثة أحماض بالمتيك) تصبنًا تامًّا بهيدروكسيد الصوديوم. علمًا بأن الكتل المولية: C₅₁H₉₈O₆ = 807.3 g/mol، وNaOH = 40.00 g/mol، والجليسرول C₃H₈O₃ = 92.09 g/mol، وبالميتات الصوديوم CH₃(CH₂)₁₄COO⁻Na⁺ = 278.4 g/mol. (أ) اكتب المعادلة الموزونة بالصيغ المكثفة. (ب) احسب كتلة NaOH اللازمة. (ج) احسب كتلتي الجليسرول والصابون الناتجين، وتحقق من حفظ الكتلة.', null, null, null, 'تطبيق', 'حساب كميات', 'صعب', 'الكتاب ص 221 — التصبن (الشكل 6-16)'),
('essay', 3, 'في تجربة لتحضير الصابون، سُخّن 25 g من السمن النباتي مع 12 mL من الإيثانول و5 mL من محلول NaOH تركيزه 6.0 M مدة 15 دقيقة مع التحريك. (أ) اكتب معادلة لفظية للتفاعل الحادث. (ب) احسب عدد مولات NaOH المضافة. (ج) ما أكبر عدد من مولات الجليسريد الثلاثي يمكن أن تُصبِّنه هذه الكمية من NaOH تصبينًا تامًّا؟ (د) لماذا يجب لبس القفازين في هذه التجربة؟', null, null, null, 'تطبيق', 'حساب وتفسير خطوات عملية', 'متوسط', 'الكتاب ص 221 — تجربة تفاعل التصبن')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L3-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'التصبن هو تميّه (تحلل) الجليسريد الثلاثي بوجود محلول مائي لقاعدة قوية مثل NaOH، فتتكون أملاح الكربوكسيلات (الصابون) والجليسرول.', '["هذا وصف الهدرجة، وهي تفاعل إضافة لا يتحلل فيه الجليسريد الثلاثي.","هذا وصف تكوين الجليسريد الثلاثي (تفاعل تكاثف)، وهو عكس اتجاه التصبن تقريبًا.","","هذا وصف تكوين الشموع، ولا تدخل فيه قاعدة قوية ولا ينتج جليسرول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('mcq', 2, 0, 'تتحلل كل رابطة إستر بجزيء NaOH، فتتحول كل سلسلة –C(=O)–(CH₂)₁₀CH₃ إلى أيون كربوكسيلات مع أيون Na⁺، فيكون الناتج ثلاثة جزيئات من CH₃(CH₂)₁₀COO⁻Na⁺ إلى جانب الجليسرول.', '["","الحمض الدهني الحر لا يتكون في وسط قاعدي قوي؛ فالقاعدة تحوّل مجموعة الكربوكسيل إلى ملح صوديوم.","كل أيون كربوكسيلات يرتبط بأيون Na⁺ واحد، والمعادلة تحتوي على 3NaOH لثلاثة أيونات كربوكسيلات.","عدد ذرات الكربون خاطئ: الملح الناتج فيه 12 ذرة كربون (CH₃ وعشر مجموعات CH₂ وCOO⁻)، أما (CH₂)₁₂ فتعطي 14 ذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('mcq', 3, 3, 'يحتوي الجليسريد الثلاثي على ثلاث روابط إستر، فيلزم 3 mol من NaOH لكل 1 mol منه: عدد مولات NaOH = 3 × 0.25 = 0.75 mol، وكتلته = 0.75 mol × 40.00 g/mol = 30 g.', '["استعمل نسبة 1 : 1 بين NaOH والجليسريد الثلاثي (0.25 × 40.00)، ونسي أن في الجزيء ثلاث روابط إستر.","قسم على 3 بدل الضرب فيه (0.25 ÷ 3 × 40.00)، فعكس النسبة المولية.","ضرب 3 × 40.00 أي حسب الكتلة لـ 1 mol من الجليسريد الثلاثي، ونسي أن الكمية 0.25 mol فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('mcq', 4, 1, 'يرتبط الجليسرول بالأحماض الدهنية الثلاثة بثلاث روابط إستر، وفي التصبن تتحلل الروابط الثلاث فيتحرر الجليسرول وتتكون ثلاثة أملاح كربوكسيلات.', '["الروابط الثنائية C=C (إن وُجدت) لا تتأثر بالتصبن؛ فهي تتشبع بالهدرجة لا بالقاعدة.","","في الجليسريد الثلاثي ثلاث روابط إستر، وتحلل رابطة واحدة لا يحرر الجليسرول ولا يعطي ثلاثة أملاح.","الروابط الببتيدية توجد في البروتينات، لا في الجليسريدات الثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('mcq', 5, 2, 'السلاسل الثلاث مختلفة: (CH₂)₁₄CH₃ و(CH₂)₇CH=CH(CH₂)₇CH₃ و(CH₂)₁₆CH₃، فيعطي التصبن الجليسرول وثلاثة أملاح صوديوم مختلفة: CH₃(CH₂)₁₄COO⁻Na⁺ وCH₃(CH₂)₇CH=CH(CH₂)₇COO⁻Na⁺ وCH₃(CH₂)₁₆COO⁻Na⁺، والملح الأوسط غير مشبع لأن التصبن لا يغير الرابطة الثنائية.', '["يصح هذا لو كانت السلاسل الثلاث متماثلة، أما هنا فكل سلسلة تعطي ملحًا مختلفًا.","في وسط NaOH تتحول الأحماض الدهنية إلى أملاح صوديوم، لا تبقى أحماضًا حرة.","","التصبن لا يضيف الهيدروجين إلى الرابطة الثنائية، فيبقى الملح الناتج من السلسلة الوسطى غير مشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('mcq', 6, 0, 'الصابون (أملاح الصوديوم للأحماض الدهنية) ليس شديد الذوبان في الماء المالح، فعند إضافة محلول NaCl المشبع ينفصل الصابون ويبدو في صورة كتل صغيرة يمكن جمعها.', '["","الجليسرول لا يتفاعل مع NaCl، ويبقى ذائبًا في الخليط.","التصبن يكون قد حدث بالتسخين مع NaOH قبل إضافة NaCl، ودور NaCl فصل الصابون لا تحفيز التفاعل.","NaCl وNaOH كلاهما مركب صوديوم ولا يتفاعلان معًا لتكوين ملح جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('mcq', 7, 3, 'الصابون أملاح صوديوم للأحماض الدهنية، ولا يتكون إلا بتميّه الجليسريد الثلاثي بوجود محلول مائي لقاعدة قوية مثل NaOH؛ فالماء وحده لا يكوّن أملاح الكربوكسيلات، ولذلك لم يتكون صابون.', '["الزيوت النباتية جليسريدات ثلاثية، فهي تحتوي على ثلاث روابط إستر في كل جزيء.","الهدرجة تحتاج إلى غاز الهيدروجين وعامل محفز، ولا تحدث بالتسخين مع الماء.","الجليسريدات الثلاثية غير قطبية لا تذوب في الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.846Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التصبن: تميّه الجليسريد الثلاثي بوجود محلول مائي لقاعدة قوية لتكوين أملاح الكربوكسيلات والجليسرول. المعادلة: الجليسريد الثلاثي + 3NaOH → CH₂OH–CHOH–CH₂OH (الجليسرول) + CH₃(CH₂)₁₄COO⁻Na⁺ + CH₃(CH₂)₇CH=CH(CH₂)₇COO⁻Na⁺ + CH₃(CH₂)₁₆COO⁻Na⁺. الصابون هو أملاح الصوديوم الثلاثة للأحماض الدهنية، أما الجليسرول فليس صابونًا.', '["تعريف التصبن: تميّه الجليسريد الثلاثي بمحلول قاعدة قوية لتكوين أملاح الكربوكسيلات والجليسرول","المتفاعلات: الجليسريد الثلاثي و3NaOH","الجليسرول CH₂OH–CHOH–CH₂OH ناتجًا","أملاح الصوديوم الثلاثة بصيغها الصحيحة (مع بقاء الرابطة الثنائية في الملح الأوسط)","تحديد أملاح الصوديوم للأحماض الدهنية على أنها الصابون"]'::jsonb, '["كل رابطة إستر تتحلل بجزيء NaOH واحد → 3NaOH.","يتحرر الجليسرول CH₂OH–CHOH–CH₂OH.","كل سلسلة –C(=O)–R تصبح R–COO⁻Na⁺: CH₃(CH₂)₁₄COO⁻Na⁺ وCH₃(CH₂)₇CH=CH(CH₂)₇COO⁻Na⁺ وCH₃(CH₂)₁₆COO⁻Na⁺."]'::jsonb, '[{"element":"تعريف التصبن: تميّه الجليسريد الثلاثي بمحلول قاعدة قوية لتكوين أملاح الكربوكسيلات والجليسرول","marks":1},{"element":"المتفاعلات: الجليسريد الثلاثي و3NaOH","marks":1},{"element":"الجليسرول CH₂OH–CHOH–CH₂OH ناتجًا","marks":1},{"element":"أملاح الصوديوم الثلاثة بصيغها الصحيحة (مع بقاء الرابطة الثنائية في الملح الأوسط)","marks":2},{"element":"تحديد أملاح الصوديوم للأحماض الدهنية على أنها الصابون","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف التصبن: تميّه الجليسريد الثلاثي بمحلول قاعدة قوية لتكوين أملاح الكربوكسيلات والجليسرول؛ المتفاعلات: الجليسريد الثلاثي و3NaOH؛ الجليسرول CH₂OH–CHOH–CH₂OH ناتجًا؛ أملاح الصوديوم الثلاثة بصيغها الصحيحة (مع بقاء الرابطة الثنائية في الملح الأوسط)؛ تحديد أملاح الصوديوم للأحماض الدهنية على أنها الصابون"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ثلاثة جزيئات من ملح واحد مع أن السلاسل مختلفة","تشبيع الرابطة الثنائية في الناتج كأنه هدرجة","كتابة الأحماض الدهنية –COOH بدل أملاحها","عدّ الجليسرول هو الصابون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-15T02:47:48.847Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CH₂(OCO(CH₂)₁₄CH₃)–CH(OCO(CH₂)₁₄CH₃)–CH₂(OCO(CH₂)₁₄CH₃) + 3NaOH → CH₂OH–CHOH–CH₂OH + 3CH₃(CH₂)₁₄COO⁻Na⁺. (ب) عدد مولات الجليسريد = 80.7 g ÷ 807.3 g/mol = 0.100 mol؛ مولات NaOH = 3 × 0.100 = 0.300 mol؛ كتلة NaOH = 0.300 mol × 40.00 g/mol = 12.0 g. (ج) الجليسرول 0.100 mol × 92.09 g/mol = 9.21 g؛ الصابون 0.300 mol × 278.4 g/mol = 83.5 g. التحقق: كتلة المتفاعلات 80.7 + 12.0 = 92.7 g، وكتلة النواتج 9.21 + 83.5 = 92.7 g، فالكتلة محفوظة.', '["المعادلة الموزونة بنسبة 1 : 3 → 1 : 3","عدد مولات الجليسريد الثلاثي 0.100 mol","كتلة NaOH = 12.0 g","كتلة الجليسرول = 9.21 g","كتلة الصابون = 83.5 g","التحقق من حفظ الكتلة (92.7 g للطرفين)"]'::jsonb, '["n(الجليسريد) = 80.7 ÷ 807.3 = 0.100 mol","n(NaOH) = 3 × 0.100 = 0.300 mol ← m = 0.300 × 40.00 = 12.0 g","n(الجليسرول) = 0.100 mol ← m = 0.100 × 92.09 = 9.21 g","n(الصابون) = 3 × 0.100 = 0.300 mol ← m = 0.300 × 278.4 = 83.5 g","80.7 + 12.0 = 92.7 g = 9.21 + 83.5"]'::jsonb, '[{"element":"المعادلة الموزونة بنسبة 1 : 3 → 1 : 3","marks":2},{"element":"عدد مولات الجليسريد الثلاثي 0.100 mol","marks":1},{"element":"كتلة NaOH = 12.0 g","marks":1},{"element":"كتلة الجليسرول = 9.21 g","marks":1},{"element":"كتلة الصابون = 83.5 g","marks":1},{"element":"التحقق من حفظ الكتلة (92.7 g للطرفين)","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"إجابة كاملة صحيحة تشمل: المعادلة الموزونة بنسبة 1 : 3 → 1 : 3؛ عدد مولات الجليسريد الثلاثي 0.100 mol؛ كتلة NaOH = 12.0 g؛ كتلة الجليسرول = 9.21 g؛ كتلة الصابون = 83.5 g؛ التحقق من حفظ الكتلة (92.7 g للطرفين)"},{"level":"1–6 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال نسبة 1 : 1 بين NaOH والجليسريد فتخرج كتلة NaOH 4.00 g","نسيان ضرب مولات الصابون في 3","عدّ الماء ناتجًا في التصبن","تقريب الكتل المولية بأرقام معنوية أقل من المعطاة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.847Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) جليسريد ثلاثي + هيدروكسيد الصوديوم → جليسرول + أملاح الصوديوم للأحماض الدهنية (الصابون). (ب) حجم المحلول 5 mL = 0.005 L؛ عدد مولات NaOH = 0.005 L × 6.0 mol/L = 0.030 mol. (ج) يلزم 3 mol من NaOH لكل 1 mol من الجليسريد الثلاثي (ثلاث روابط إستر)، فأكبر كمية = 0.030 mol ÷ 3 = 0.010 mol. (د) لأن NaOH قاعدة قوية تسبب حروقًا للجلد.', '["المعادلة اللفظية: جليسريد ثلاثي + هيدروكسيد الصوديوم → جليسرول + أملاح الصوديوم للأحماض الدهنية (صابون)","n(NaOH) = 0.005 L × 6.0 mol/L = 0.030 mol","أقصى كمية من الجليسريد الثلاثي = 0.030 ÷ 3 = 0.010 mol (لأن النسبة 3 : 1)","لبس القفازين لأن NaOH قاعدة قوية تسبب حروقًا للجلد"]'::jsonb, '["V = 5 mL = 0.005 L","n(NaOH) = M × V = 6.0 × 0.005 = 0.030 mol","n(الجليسريد) = 0.030 ÷ 3 = 0.010 mol"]'::jsonb, '[{"element":"المعادلة اللفظية: جليسريد ثلاثي + هيدروكسيد الصوديوم → جليسرول + أملاح الصوديوم للأحماض الدهنية (صابون)","marks":1},{"element":"n(NaOH) = 0.005 L × 6.0 mol/L = 0.030 mol","marks":1},{"element":"أقصى كمية من الجليسريد الثلاثي = 0.030 ÷ 3 = 0.010 mol (لأن النسبة 3 : 1)","marks":1},{"element":"لبس القفازين لأن NaOH قاعدة قوية تسبب حروقًا للجلد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: المعادلة اللفظية: جليسريد ثلاثي + هيدروكسيد الصوديوم → جليسرول + أملاح الصوديوم للأحماض الدهنية (صابون)؛ n(NaOH) = 0.005 L × 6.0 mol/L = 0.030 mol؛ أقصى كمية من الجليسريد الثلاثي = 0.030 ÷ 3 = 0.010 mol (لأن النسبة 3 : 1)؛ لبس القفازين لأن NaOH قاعدة قوية تسبب حروقًا للجلد"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل الحجم من mL إلى L","استعمال نسبة 1 : 1 بين NaOH والجليسريد الثلاثي فيكون الناتج 0.030 mol","كتابة الماء ناتجًا في معادلة التصبن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.847Z"}'::jsonb)
