('mcq', 1, 'مِمَّ يتكون جزيء الليبيد الفوسفوري؟', null, null, '["جليسرول مرتبط بثلاثة أحماض دهنية بروابط إستر","جليسرول مرتبط بحمضين دهنيين وبمجموعة فوسفات","حمض دهني واحد مرتبط بكحول ذي سلسلة طويلة","أربع حلقات كربونية ملتحمة دون سلاسل أحماض دهنية"]'::jsonb, 'تذكر', 'تعرف تركيب', 'سهل', 'الكتاب ص 222 — الليبيدات الفوسفورية (الشكل 6-17)'),
('mcq', 2, 'في جزيء الليبيد الفوسفوري المبين في الشكل الآتي، أي الجزأين قطبي؟ وإلى أين يتجه عندما تترتب الجزيئات في الغشاء الخلوي؟', null, '[{"src":"qimg/chem22/c6-l3b-phospholipid.svg","alt":"صيغة جزيء ليبيدي. في اليسار ذرة P مرتبطة برابطة ثنائية بذرة O من أعلى، وبذرتي أكسجين سالبتين O⁻ إحداهما يسارًا والأخرى أسفل، وبذرة O رابعة يمينًا ترتبط بمجموعة CH₂. تحت CH₂ مجموعة CH ثم مجموعة CH₂ مترابطة رأسيًّا. ترتبط كل من CH وCH₂ السفلى بذرة O ثم بذرة C عليها رابطة ثنائية مع ذرة O، ويخرج من كل منهما نحو اليمين سلسلة هيدروكربونية طويلة متعرجة (صيغة هيكلية) من 15 ذرة كربون. تحت الشكل قوسان: القوس (س) تحت مجموعة الفوسفور والأكسجين في اليسار، والقوس (ص) تحت السلسلتين الهيدروكربونيتين الطويلتين في اليمين."}]'::jsonb, '["الجزء (ص)، ويتجه نحو داخل الطبقة الثنائية","الجزء (س)، ويتجه نحو داخل الطبقة الثنائية","الجزء (ص)، ويتجه نحو الوسط المائي خارج الطبقة","الجزء (س)، ويتجه نحو الوسط المائي خارج الطبقة"]'::jsonb, 'فهم', 'تفسير تركيب', 'سهل', 'الكتاب ص 222 — الليبيدات الفوسفورية (الشكل 6-17)'),
('mcq', 3, 'يمثل الشكل الآتي مقطعًا في غشاء خلوي. ماذا تمثل المنطقة 3؟ ولماذا توجد في هذا الموقع؟', null, '[{"src":"qimg/chem22/c6-l3b-membrane-regions.svg","alt":"مقطع في غشاء خلوي. يتكون الغشاء من صفين من الدوائر الزرقاء، صف في الأعلى وصف في الأسفل، ومن كل دائرة يخرج خطان متعرجان نحو وسط الغشاء، فتلتقي خطوط الصفين في المنتصف. فوق الغشاء منطقة مظللة كُتب فيها «خارج الخلية (وسط مائي)»، وتحته منطقة مظللة كُتب فيها «داخل الخلية (وسط مائي)». على اليمين أرقام تشير إلى أربع مناطق: الرقم 1 يشير إلى المنطقة المظللة خارج الخلية، والرقم 2 إلى صف الدوائر العلوي، والرقم 3 إلى منطقة الخطوط المتعرجة في وسط الغشاء، والرقم 4 إلى صف الدوائر السفلي."}]'::jsonb, '["الذيول غير القطبية، وتتجمع في الوسط بعيدًا عن الماء","الرؤوس القطبية، وتتجمع في الوسط بعيدًا عن الماء","الذيول غير القطبية، وتتجه نحو الماء لتذوب فيه","مجموعات الفوسفات، وترتبط ببعضها بروابط إستر"]'::jsonb, 'تحليل', 'تحليل شكل', 'متوسط', 'الكتاب ص 222 — الليبيدات الفوسفورية (الشكل 6-17)'),
('mcq', 4, 'لماذا لا تستطيع جزيئات الجليسريدات الثلاثية أن تكوّن طبقة ثنائية كالتي تكوّنها الليبيدات الفوسفورية في الأغشية الخلوية؟', null, null, '["لأن سلاسلها الهيدروكربونية أقصر من أن تكوّن طبقة","لأنها تذوب في الماء فلا تبقى في طبقة منفصلة","لأنها غير قطبية كلها، فليس لها رأس قطبي يتجه نحو الماء","لأنها تحتوي على مجموعة فوسفات تتنافر مع الماء"]'::jsonb, 'تحليل', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 233 — س57 وس60 وس64'),
('mcq', 5, 'يشترك جزيء الصابون وجزيء الليبيد الفوسفوري في خاصية تركيبية تفسّر سلوكهما في الماء. ما هذه الخاصية؟', null, null, '["كلاهما يحتوي على ثلاث سلاسل أحماض دهنية","لكل منهما طرف قطبي وجزء غير قطبي","كلاهما يحتوي على مجموعة فوسفات","كلاهما بوليمر ذو وحدات بنائية متكررة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 221–222 — الصابون والليبيدات الفوسفورية'),
('mcq', 6, 'تعبر بعض المواد غير القطبية الصغيرة الغشاء الخلوي بسهولة أكبر من المواد القطبية. أي العبارات الآتية تفسّر ذلك اعتمادًا على تركيب الغشاء؟', null, null, '["لأن رؤوس الفوسفات القطبية تجذب المواد غير القطبية إليها","لأن الغشاء طبقة واحدة رقيقة من الجليسريدات الثلاثية","لأن الماء داخل الخلية وخارجها غير قطبي فيجذب هذه المواد","لأن وسط الطبقة الثنائية ذيول غير قطبية تمتزج بها المواد غير القطبية"]'::jsonb, 'تحليل', 'ربط التركيب بالوظيفة', 'صعب', 'الكتاب ص 222 — الليبيدات الفوسفورية (الشكل 6-17)'),
('mcq', 7, 'يحتوي سم بعض الأفاعي على إنزيم يفكك (يميّه) رابطة الإستر التي تربط الحمض الدهني بذرة الكربون الوسطى في جزيء الليبيد الفوسفوري. ما التغير الذي يحدث في تركيب الجزيء؟', null, null, '["ينفصل الحمض الدهني عن الجليسرول، فيبقى الجزيء برأس قطبي وذيل واحد فقط","تتشبع الروابط الثنائية في ذيليه بإضافة الهيدروجين إليها","تتحول مجموعة الفوسفات القطبية إلى سلسلة هيدروكربونية غير قطبية","يرتبط بالجليسرول حمض دهني ثالث فيصبح جليسريدًا ثلاثيًّا"]'::jsonb, 'تحليل', 'ربط التركيب بالوظيفة', 'صعب', 'الكتاب ص 222 — الربط مع علم الأحياء'),
('essay', 1, 'يمثل الشكل الآتي جزيء ليبيد فوسفوري. (أ) حدد الجزء القطبي والجزء غير القطبي، مستعينًا بالرمزين (س) و(ص). (ب) قارن بين تركيب هذا الجزيء وتركيب الجليسريد الثلاثي من حيث أوجه الشبه والاختلاف.', null, '[{"src":"qimg/chem22/c6-l3b-phospholipid.svg","alt":"صيغة جزيء ليبيدي. في اليسار ذرة P مرتبطة برابطة ثنائية بذرة O من أعلى، وبذرتي أكسجين سالبتين O⁻ إحداهما يسارًا والأخرى أسفل، وبذرة O رابعة يمينًا ترتبط بمجموعة CH₂. تحت CH₂ مجموعة CH ثم مجموعة CH₂ مترابطة رأسيًّا. ترتبط كل من CH وCH₂ السفلى بذرة O ثم بذرة C عليها رابطة ثنائية مع ذرة O، ويخرج من كل منهما نحو اليمين سلسلة هيدروكربونية طويلة متعرجة (صيغة هيكلية) من 15 ذرة كربون. تحت الشكل قوسان: القوس (س) تحت مجموعة الفوسفور والأكسجين في اليسار، والقوس (ص) تحت السلسلتين الهيدروكربونيتين الطويلتين في اليمين."}]'::jsonb, null, 'تحليل', 'تحليل تركيب ومقارنة', 'سهل', 'الكتاب ص 233 — س57 وس60 وس64'),
('essay', 2, 'يمثل الشكل الآتي مقطعًا في غشاء خلوي. (أ) صنّف المناطق 1 و2 و3 و4 إلى قطبية وغير قطبية، مع ذكر ما تمثله كل منطقة. (ب) فسّر لماذا تتجه دوائر المنطقة 4 نحو داخل الخلية وليس نحو وسط الغشاء. (ج) استنتج لماذا تترتب الليبيدات الفوسفورية في طبقتين لا في طبقة واحدة.', null, '[{"src":"qimg/chem22/c6-l3b-membrane-regions.svg","alt":"مقطع في غشاء خلوي. يتكون الغشاء من صفين من الدوائر الزرقاء، صف في الأعلى وصف في الأسفل، ومن كل دائرة يخرج خطان متعرجان نحو وسط الغشاء، فتلتقي خطوط الصفين في المنتصف. فوق الغشاء منطقة مظللة كُتب فيها «خارج الخلية (وسط مائي)»، وتحته منطقة مظللة كُتب فيها «داخل الخلية (وسط مائي)». على اليمين أرقام تشير إلى أربع مناطق: الرقم 1 يشير إلى المنطقة المظللة خارج الخلية، والرقم 2 إلى صف الدوائر العلوي، والرقم 3 إلى منطقة الخطوط المتعرجة في وسط الغشاء، والرقم 4 إلى صف الدوائر السفلي."}]'::jsonb, null, 'تحليل', 'تحليل شكل وتفسير', 'متوسط', 'الكتاب ص 222 — الليبيدات الفوسفورية (الشكل 6-17)'),
('essay', 3, 'قارن بين جزيء الصابون وجزيء الليبيد الفوسفوري من حيث: (أ) الجزء القطبي، (ب) عدد السلاسل غير القطبية، (ج) طريقة ترتب الجزيئات وعملها. ثم بيّن الخاصية المشتركة التي تجعل لكل منهما سلوكًا مميزًا في الماء.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 221–222 — الصابون والليبيدات الفوسفورية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
