select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الليبيد الفوسفوري جليسريد ثلاثي استُبدل فيه أحد الأحماض الدهنية بمجموعة فوسفات قطبية، فيبقى الجليسرول مرتبطًا بحمضين دهنيين وبمجموعة فوسفات.', '["هذا تركيب الجليسريد الثلاثي، وليس فيه مجموعة فوسفات.","","هذا تركيب الشموع.","هذا التركيب الأساسي للستيرويدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.847Z"}'::jsonb),
('mcq', 2, 3, 'الجزء (س) مجموعة الفوسفات التي تحمل شحنات سالبة، فهو الرأس القطبي، ويتجه في الطبقة الثنائية نحو المحيط المائي الخارجي (داخل الخلية وخارجها)، أما الجزء (ص) فسلسلتا الحمضين الدهنيين غير القطبيتين وتتجهان نحو الداخل.', '["الجزء (ص) سلسلتان هيدروكربونيتان غير قطبيتين، وهما اللتان تتجهان نحو الداخل فعلًا لكنهما ليستا الجزء القطبي.","الجزء (س) قطبي فعلًا، لكن الرؤوس القطبية تتجه نحو الماء لا نحو داخل الطبقة.","الجزء (ص) غير قطبي، ولذلك يبتعد عن الوسط المائي ولا يتجه نحوه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('mcq', 3, 0, 'المنطقة 3 هي الخطوط المتعرجة في وسط الغشاء، أي ذيول الأحماض الدهنية غير القطبية لطبقتي الليبيد الفوسفوري، وهي تتجه نحو الداخل لأنها لا تنجذب إلى الماء الموجود داخل الخلية وخارجها، في حين تتجه الرؤوس القطبية (2 و4) نحو الماء.', '["","الرؤوس القطبية هي الدوائر في المنطقتين 2 و4 على سطحي الغشاء، لا في وسطه.","الذيول غير قطبية فلا تذوب في الماء، ولذلك تبتعد عنه نحو الداخل.","مجموعات الفوسفات جزء من الرؤوس القطبية على السطحين، وليست في وسط الغشاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('mcq', 4, 2, 'ترتيب الطبقة الثنائية يعتمد على أن لكل جزيء رأسًا قطبيًّا يتجه نحو الماء وذيولًا غير قطبية تتجه نحو الداخل. والجليسريد الثلاثي ترتبط فيه ثلاثة أحماض دهنية غير قطبية بالجليسرول، وليس فيه مجموعة فوسفات قطبية، فلا يوجد جزء منه يتجه نحو الماء.', '["سلاسل الأحماض الدهنية في الجليسريدات الثلاثية طويلة كسلاسل الليبيدات الفوسفورية (12–24 ذرة كربون عادة).","الجليسريدات الثلاثية غير قطبية فلا تذوب في الماء.","","مجموعة الفوسفات توجد في الليبيدات الفوسفورية لا في الجليسريدات الثلاثية، وهي قطبية تنجذب إلى الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('mcq', 5, 1, 'جزيء الصابون له طرف قطبي (–COO⁻Na⁺) وسلسلة غير قطبية، والليبيد الفوسفوري له رأس فوسفات قطبي وذيلان غير قطبيين؛ فالجزء القطبي في كل منهما يتجه نحو الماء والجزء غير القطبي يبتعد عنه.', '["الصابون فيه سلسلة حمض دهني واحدة، والليبيد الفوسفوري فيه سلسلتان.","","الطرف القطبي في الصابون مجموعة كربوكسيلات لا فوسفات.","الليبيدات ليست بوليمرات ذات وحدات بنائية متكررة، والصابون كذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('mcq', 6, 3, 'وسط الطبقة الثنائية مكوّن من ذيول الأحماض الدهنية غير القطبية، فالمواد غير القطبية تنجذب إليها وتمر خلالها، أما المواد القطبية فلا تنجذب إلى هذا الوسط غير القطبي، فيعمل الغشاء حاجزًا ينظم ما يدخل الخلية ويخرج منها.', '["الرؤوس القطبية تنجذب إلى المواد القطبية كالماء، لا إلى المواد غير القطبية.","الغشاء طبقة ثنائية من الليبيدات الفوسفورية، لا طبقة واحدة من الجليسريدات الثلاثية.","الماء مذيب قطبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('mcq', 7, 0, 'رابطة الإستر هي التي تربط كل حمض دهني بالجليسرول، فإذا تفككت الرابطة عند ذرة الكربون الوسطى انفصل الحمض الدهني المرتبط بها، فيبقى من الليبيد الفوسفوري الجليسرول مرتبطًا بمجموعة الفوسفات القطبية (الرأس) وبحمض دهني واحد (ذيل واحد)، فيتغير التركيب الذي يسمح للجزيئات بالترتب في الطبقة الثنائية.', '["","إضافة الهيدروجين إلى الروابط الثنائية هدرجة، أما الإنزيم فيفكك رابطة الإستر بالماء.","تفكك رابطة الإستر عند الكربون الأوسط لا يمس مجموعة الفوسفات، فيبقى الرأس قطبيًّا.","التميّه يفصل حمضًا دهنيًّا ولا يضيف حمضًا جديدًا، والجليسريد الثلاثي ليس فيه مجموعة فوسفات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الجزء (س) مجموعة الفوسفات وهي الرأس القطبي، والجزء (ص) سلسلتا الحمضين الدهنيين وهما الذيلان غير القطبيين. (ب) الشبه: كلاهما مبني على الجليسرول ترتبط به أحماض دهنية بروابط إستر. الاختلاف: يرتبط الجليسرول في الجليسريد الثلاثي بثلاثة أحماض دهنية فيكون الجزيء غير قطبي كله، أما في الليبيد الفوسفوري فيرتبط بحمضين دهنيين فقط ويُستبدل الثالث بمجموعة فوسفات قطبية.', '["الجزء (س) فوسفات قطبي","الجزء (ص) ذيلان غير قطبيين","الشبه: الجليسرول والأحماض الدهنية المرتبطة بروابط إستر","الاختلاف: ثلاثة أحماض دهنية في الجليسريد الثلاثي مقابل حمضين ومجموعة فوسفات في الليبيد الفوسفوري"]'::jsonb, '[]'::jsonb, '[{"element":"الجزء (س) فوسفات قطبي","marks":1},{"element":"الجزء (ص) ذيلان غير قطبيين","marks":1},{"element":"الشبه: الجليسرول والأحماض الدهنية المرتبطة بروابط إستر","marks":1},{"element":"الاختلاف: ثلاثة أحماض دهنية في الجليسريد الثلاثي مقابل حمضين ومجموعة فوسفات في الليبيد الفوسفوري","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الجزء (س) فوسفات قطبي؛ الجزء (ص) ذيلان غير قطبيين؛ الشبه: الجليسرول والأحماض الدهنية المرتبطة بروابط إستر؛ الاختلاف: ثلاثة أحماض دهنية في الجليسريد الثلاثي مقابل حمضين ومجموعة فوسفات في الليبيد الفوسفوري"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ السلاسل الهيدروكربونية هي الجزء القطبي","القول إن الليبيد الفوسفوري لا يحتوي على الجليسرول","عدّ الجليسريد الثلاثي ذا رأس قطبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.848Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المنطقة 1 وسط مائي (قطبي) خارج الخلية؛ المنطقة 2 الرؤوس القطبية (الفوسفات) للطبقة الخارجية؛ المنطقة 3 الذيول غير القطبية للطبقتين؛ المنطقة 4 الرؤوس القطبية للطبقة الداخلية. (ب) لأن داخل الخلية وسط مائي قطبي أيضًا، والرؤوس القطبية تنجذب إلى الماء، فتتجه نحوه، في حين تبتعد الذيول غير القطبية عن الماء نحو وسط الغشاء. (ج) لأن الخلية محاطة بالماء من الجهتين؛ فلو كانت طبقة واحدة لتعرضت ذيولها غير القطبية للماء في إحدى الجهتين، أما في الطبقتين فتتجه الرؤوس القطبية نحو الماء في الجهتين وتختبئ الذيول غير القطبية في الداخل، فيتكون حاجز ثابت ينظم دخول المواد وخروجها.', '["المناطق 1 و2 و4 قطبية: الوسط المائي والرؤوس القطبية","المنطقة 3 غير قطبية: الذيول","الرؤوس القطبية تنجذب إلى الماء داخل الخلية","الماء على جانبي الغشاء، فالطبقة الواحدة تعرّض الذيول للماء","الطبقتان تجعلان الرؤوس نحو الماء في الجهتين والذيول في الداخل فتكوّنان حاجزًا"]'::jsonb, '[]'::jsonb, '[{"element":"المناطق 1 و2 و4 قطبية: الوسط المائي والرؤوس القطبية","marks":1},{"element":"المنطقة 3 غير قطبية: الذيول","marks":1},{"element":"الرؤوس القطبية تنجذب إلى الماء داخل الخلية","marks":1},{"element":"الماء على جانبي الغشاء، فالطبقة الواحدة تعرّض الذيول للماء","marks":1},{"element":"الطبقتان تجعلان الرؤوس نحو الماء في الجهتين والذيول في الداخل فتكوّنان حاجزًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: المناطق 1 و2 و4 قطبية: الوسط المائي والرؤوس القطبية؛ المنطقة 3 غير قطبية: الذيول؛ الرؤوس القطبية تنجذب إلى الماء داخل الخلية؛ الماء على جانبي الغشاء، فالطبقة الواحدة تعرّض الذيول للماء؛ الطبقتان تجعلان الرؤوس نحو الماء في الجهتين والذيول في الداخل فتكوّنان حاجزًا"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ منطقة الذيول قطبية","إغفال أن داخل الخلية وسط مائي","القول إن الرؤوس تتجه للداخل لترتبط بالذيول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.849Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الجزء القطبي في الصابون مجموعة الكربوكسيلات –COO⁻Na⁺، وفي الليبيد الفوسفوري مجموعة الفوسفات. (ب) للصابون سلسلة هيدروكربونية واحدة، ولليبيد الفوسفوري سلسلتان (ذيلان). (ج) جزيئات الصابون تحيط بقطرات الزيت أو الأوساخ: ترتبط أطرافها غير القطبية بالأوساخ وتبقى أطرافها القطبية في الماء فتُزال الأوساخ بالماء؛ أما الليبيدات الفوسفورية فتترتب في طبقة ثنائية رؤوسها القطبية نحو الماء خارج الخلية وداخلها وذيولها غير القطبية في الداخل، فتكوّن غشاءً يعمل حاجزًا ينظم دخول المواد وخروجها. الخاصية المشتركة: لكل منهما طرف قطبي ينجذب إلى الماء وجزء غير قطبي يبتعد عنه.', '["الجزء القطبي: كربوكسيلات في الصابون وفوسفات في الليبيد الفوسفوري","سلسلة واحدة في الصابون وسلسلتان في الليبيد الفوسفوري","الصابون يحيط بالأوساخ وطرفه القطبي في الماء فيزيلها","الليبيد الفوسفوري يكوّن طبقة ثنائية: رؤوس نحو الماء وذيول للداخل، تعمل حاجزًا","الخاصية المشتركة: طرف قطبي وجزء غير قطبي"]'::jsonb, '[]'::jsonb, '[{"element":"الجزء القطبي: كربوكسيلات في الصابون وفوسفات في الليبيد الفوسفوري","marks":1},{"element":"سلسلة واحدة في الصابون وسلسلتان في الليبيد الفوسفوري","marks":1},{"element":"الصابون يحيط بالأوساخ وطرفه القطبي في الماء فيزيلها","marks":1},{"element":"الليبيد الفوسفوري يكوّن طبقة ثنائية: رؤوس نحو الماء وذيول للداخل، تعمل حاجزًا","marks":2},{"element":"الخاصية المشتركة: طرف قطبي وجزء غير قطبي","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: الجزء القطبي: كربوكسيلات في الصابون وفوسفات في الليبيد الفوسفوري؛ سلسلة واحدة في الصابون وسلسلتان في الليبيد الفوسفوري؛ الصابون يحيط بالأوساخ وطرفه القطبي في الماء فيزيلها؛ الليبيد الفوسفوري يكوّن طبقة ثنائية: رؤوس نحو الماء وذيول للداخل، تعمل حاجزًا؛ الخاصية المشتركة: طرف قطبي وجزء غير قطبي"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الصابون يحتوي على فوسفات","القول إن الليبيد الفوسفوري يذوب في الماء كله","إغفال وظيفة الغشاء حاجزًا ينظم مرور المواد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.849Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
