insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L3-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'مِمَّ تتكون الشموع؟', null, null, '["جليسرول مرتبط بثلاثة أحماض دهنية","أربع حلقات كربونية ملتحمة","جليسرول وحمضين دهنيين ومجموعة فوسفات","حمض دهني متحد مع كحول ذي سلسلة طويلة"]'::jsonb, 'تذكر', 'تعرف تركيب', 'سهل', 'الكتاب ص 222 — الشموع'),
('mcq', 2, 'يمثل الشكل الآتي المكوّن الرئيس لشمع النحل. ما مصدر كل من الجزأين (س) و(ص)؟', null, '[{"src":"qimg/chem22/c6-l3b-beeswax.svg","alt":"صيغة مكثفة: CH₃(CH₂)₁₄ مرتبطة بذرة C عليها رابطة ثنائية مع ذرة O، وترتبط ذرة C هذه بذرة O ثانية ترتبط بالمجموعة (CH₂)₂₉CH₃. تحت الصيغة قوسان: القوس (س) تحت الجزء CH₃(CH₂)₁₄–C(=O) في اليسار، والقوس (ص) تحت الجزء –O–(CH₂)₂₉CH₃ في اليمين."}]'::jsonb, '["(س) من كحول ذي 16 ذرة كربون، و(ص) من حمض دهني ذي 30 ذرة كربون","(س) من حمض دهني ذي 16 ذرة كربون، و(ص) من كحول ذي 30 ذرة كربون","(س) من حمض دهني ذي 15 ذرة كربون، و(ص) من كحول ذي 29 ذرة كربون","(س) من حمض دهني ذي 16 ذرة كربون، و(ص) من الجليسرول"]'::jsonb, 'فهم', 'تحليل صيغة', 'متوسط', 'الكتاب ص 222 — الشموع'),
('mcq', 3, 'أي المركبات الآتية من الستيرويدات؟', null, null, '["شمع النحل","حمض الستيريك","فيتامين (د)","الجليسرول"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 223 — الستيرويدات'),
('mcq', 4, 'يمثل الشكل الآتي جزيء الكولسترول. أي العبارات الآتية تصف تركيبه ووظيفته وصفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c6-l3b-cholesterol.svg","alt":"صيغة هيكلية لجزيء فيه أربع حلقات ملتحمة: ثلاث حلقات سداسية متجاورة، وحلقة خماسية في الطرف الأيمن. على الحلقة السداسية اليسرى مجموعة HO، وفي الحلقة السداسية الثانية رابطة ثنائية واحدة بين ذرتي كربون. تتفرع مجموعتا ميثيل نحو الأعلى من ذرتي كربون عند التحام الحلقات، ومن الحلقة الخماسية تخرج سلسلة هيدروكربونية متفرعة فيها ثماني ذرات كربون. لا يحتوي الجزيء على مجموعة كربوكسيل."}]'::jsonb, '["ستيرويد يحتوي على أربع حلقات ملتحمة، ومكوّن بنائي مهم للأغشية الخلوية","حمض دهني غير مشبع، ومصدر رئيس لتخزين الطاقة في الخلايا الدهنية","ستيرويد يحتوي على ثلاث سلاسل أحماض دهنية، ويكوّن طبقة الشمع","شمع يحتوي على رابطة إستر، ويغطي أوراق النباتات فيمنع فقد الماء"]'::jsonb, 'فهم', 'وصف تركيب ووظيفة', 'متوسط', 'الكتاب ص 223 — الستيرويدات'),
('mcq', 5, 'يتكون المكوّن الرئيس لشمع النحل من اتحاد حمض البالمتيك C₁₆H₃₂O₂ مع كحول صيغته C₃₀H₆₂O، ويتحرر جزيء ماء. ما الصيغة الجزيئية للشمع الناتج؟', null, null, '["C₄₆H₉₄O₃","C₄₆H₉₄O₂","C₄₆H₉₂O₃","C₄₆H₉₂O₂"]'::jsonb, 'تطبيق', 'استنتاج صيغة', 'صعب', 'الكتاب ص 222 — الشموع'),
('mcq', 6, 'لماذا تُصنع بعض الشموع المستعملة للإضاءة من شمع العسل؟', null, null, '["لأنه يذوب في الماء بسهولة","لأنه سائل في درجة حرارة الغرفة","لأنه يحترق ببطء وهدوء","لأنه يحتوي على أربع حلقات ملتحمة"]'::jsonb, 'تذكر', 'تعليل استعمال', 'سهل', 'الكتاب ص 222 — الشموع'),
('mcq', 7, 'تتجمع قطرات المطر على أوراق كثير من النباتات في صورة كرات صغيرة كالخرز بدل أن تنتشر على سطحها. ما الذي يدل عليه ذلك؟', null, null, '["وجود طبقة من الليبيدات الفوسفورية تمتص الماء","وجود طبقة شمعية غير قطبية تغطي الورقة","وجود ستيرويدات تفرزها الورقة آلية دفاعية","وجود سكريات على سطح الورقة تجذب الماء"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 222 — الشموع'),
('essay', 1, 'قارن بين الشموع والستيرويدات من حيث: (أ) التركيب، (ب) احتواء التركيب على سلاسل أحماض دهنية، (ج) مثالين على كل منهما مع وظيفة كل مثال.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 222–223 — الشموع والستيرويدات'),
('essay', 2, 'يتكوّن المكوّن الرئيس لشمع النحل من اتحاد حمض البالمتيك CH₃(CH₂)₁₄COOH مع كحول صيغته CH₃(CH₂)₂₉OH. (أ) اكتب معادلة التكوين بالصيغ المكثفة. (ب) ما نوع الرابطة المتكونة؟ (ج) فسّر لماذا لا يذوب الشمع في الماء، وكيف يناسب ذلك وظيفته على أوراق النباتات.', null, null, null, 'تطبيق', 'كتابة معادلة وتفسير', 'صعب', 'الكتاب ص 222 — الشموع'),
('essay', 3, 'يمثل الشكل الآتي جزيء الكولسترول. (أ) صف التركيب الأساسي الذي يشترك فيه الكولسترول مع سائر الستيرويدات. (ب) قارن بين تركيب الكولسترول وتركيب حمض الستيريك CH₃(CH₂)₁₆COOH من حيث شكل الهيكل الكربوني والمجموعة الوظيفية. (ج) هل يمكن أن يحدث للكولسترول تفاعل تصبن عند تسخينه مع محلول NaOH؟ فسّر إجابتك.', null, '[{"src":"qimg/chem22/c6-l3b-cholesterol.svg","alt":"صيغة هيكلية لجزيء فيه أربع حلقات ملتحمة: ثلاث حلقات سداسية متجاورة، وحلقة خماسية في الطرف الأيمن. على الحلقة السداسية اليسرى مجموعة HO، وفي الحلقة السداسية الثانية رابطة ثنائية واحدة بين ذرتي كربون. تتفرع مجموعتا ميثيل نحو الأعلى من ذرتي كربون عند التحام الحلقات، ومن الحلقة الخماسية تخرج سلسلة هيدروكربونية متفرعة فيها ثماني ذرات كربون. لا يحتوي الجزيء على مجموعة كربوكسيل."}]'::jsonb, null, 'تحليل', 'تحليل تركيب ومقارنة', 'صعب', 'الكتاب ص 219–223 — الستيرويدات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
