('mcq', 1, 3, 'الشموع ليبيدات تتكون من اتحاد حمض دهني مع كحول ذي سلسلة طويلة، فترتبط السلسلتان برابطة إستر واحدة.', '["هذا تركيب الجليسريد الثلاثي.","هذا التركيب الأساسي للستيرويدات.","هذا تركيب الليبيد الفوسفوري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.849Z"}'::jsonb),
('mcq', 2, 1, 'الجزء (س) يحتوي على مجموعة الكربونيل C=O، فهو من الحمض الدهني، وعدد ذرات الكربون فيه 1 + 14 + 1 = 16 (حمض البالمتيك). والجزء (ص) يبدأ بذرة الأكسجين المرتبطة بسلسلة (CH₂)₂₉CH₃، فهو من الكحول، وعدد ذرات الكربون فيه 29 + 1 = 30.', '["عكس المصدرين: ذرة كربون الكربونيل C=O في الجزء (س) تدل على الحمض لا على الكحول.","","لم يحسب ذرة كربون الكربونيل في (س) ولا مجموعة CH₃ الطرفية في (ص).","الجزء (ص) سلسلة طويلة واحدة من 30 ذرة كربون، أما الجليسرول ففيه 3 ذرات كربون فقط ولا يوجد في الشموع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.849Z"}'::jsonb),
('mcq', 3, 2, 'فيتامين (د) يحتوي على تركيب الستيرويد ذي الحلقات الأربع، ويؤدي دورًا في تكوين العظام، فهو من الستيرويدات.', '["شمع النحل من الشموع: حمض دهني متحد مع كحول طويل السلسلة.","حمض الستيريك حمض دهني مشبع، وتشابه اسمه مع «ستيرويد» لا يجعله منها.","","الجليسرول كحول ذو ثلاث ذرات كربون، وليس ليبيدًا حلقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.849Z"}'::jsonb),
('mcq', 4, 0, 'الكولسترول ستيرويد مبني على التركيب ذي الحلقات الأربع الملتحمة (ثلاث سداسية وواحدة خماسية)، ويُعدّ مكوّنًا بنائيًّا مهمًّا للأغشية الخلوية.', '["","ليس في الجزيء مجموعة كربوكسيل، فليس حمضًا دهنيًّا، وتخزين الطاقة وظيفة الجليسريدات الثلاثية.","الستيرويدات لا تحتوي على سلاسل أحماض دهنية، بل على حلقات متعددة.","ليس في الجزيء رابطة إستر، والشموع لا تحتوي على حلقات ملتحمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.849Z"}'::jsonb),
('mcq', 5, 3, 'C₁₆H₃₂O₂ + C₃₀H₆₂O → الشمع + H₂O. ذرات الكربون: 16 + 30 = 46، والهيدروجين: 32 + 62 − 2 = 92، والأكسجين: 2 + 1 − 1 = 2، فالصيغة C₄₆H₉₂O₂.', '["جمع صيغتي المتفاعلين دون طرح جزيء الماء المتحرر.","طرح ذرة أكسجين فقط ولم يطرح ذرتي الهيدروجين في جزيء الماء.","طرح ذرتي الهيدروجين فقط ولم يطرح ذرة الأكسجين في جزيء الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.850Z"}'::jsonb),
('mcq', 6, 2, 'شمع العسل يميل إلى الاحتراق ببطء وهدوء، ولذلك تُصنع منه بعض الشموع.', '["الشموع ليبيدات غير قطبية لا تذوب في الماء.","الشموع مواد صلبة طرية في درجة حرارة الغرفة.","","الحلقات الأربع الملتحمة صفة الستيرويدات، لا الشموع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.850Z"}'::jsonb),
('mcq', 7, 1, 'تكوّن قطرات الماء كرات كالخرز على أوراق النبات يشير إلى وجود طبقة شمعية؛ فالشمع غير قطبي لا ينجذب إليه الماء، وهذه الطبقة تمنع فقدان الماء من الورقة.', '["الليبيدات الفوسفورية تكوّن الأغشية الخلوية، ولا تغطي سطح الورقة طبقةً تمتص الماء.","","الستيرويد الدفاعي مثال للعلجوم البحري (البوفوتوكسين)، ولا علاقة له بتكوّن قطرات الماء على الأوراق.","المواد التي تجذب الماء تجعله ينتشر على السطح لا أن يتجمع في كرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.850Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الشموع: حمض دهني متحد مع كحول ذي سلسلة طويلة (رابطة إستر)، وصيغتها العامة CH₃(CH₂)ₓCOO(CH₂)ᵧCH₃؛ الستيرويدات: ليبيدات مبنية على تركيب أساسي من أربع حلقات ملتحمة. (ب) الشموع تحتوي على سلسلة حمض دهني، أما الستيرويدات فلا تحتوي على سلاسل أحماض دهنية. (ج) أمثلة الشموع: الشمع الذي يغطي أوراق النباتات ويمنع فقد الماء، وشمع النحل الذي تُبنى منه أقراص العسل. أمثلة الستيرويدات: الكولسترول مكوّن بنائي للأغشية الخلوية، وفيتامين (د) يؤدي دورًا في تكوين العظام، والهرمونات الجنسية تنظم عمليات الأيض.', '["تركيب الشموع: حمض دهني + كحول طويل السلسلة","تركيب الستيرويدات: أربع حلقات ملتحمة","الشموع فيها سلسلة حمض دهني والستيرويدات لا","مثالان صحيحان على الشموع مع الوظيفة","مثالان صحيحان على الستيرويدات مع الوظيفة"]'::jsonb, '[]'::jsonb, '[{"element":"تركيب الشموع: حمض دهني + كحول طويل السلسلة","marks":1},{"element":"تركيب الستيرويدات: أربع حلقات ملتحمة","marks":1},{"element":"الشموع فيها سلسلة حمض دهني والستيرويدات لا","marks":1},{"element":"مثالان صحيحان على الشموع مع الوظيفة","marks":1},{"element":"مثالان صحيحان على الستيرويدات مع الوظيفة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تركيب الشموع: حمض دهني + كحول طويل السلسلة؛ تركيب الستيرويدات: أربع حلقات ملتحمة؛ الشموع فيها سلسلة حمض دهني والستيرويدات لا؛ مثالان صحيحان على الشموع مع الوظيفة؛ مثالان صحيحان على الستيرويدات مع الوظيفة"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجليسرول جزءًا من الشموع","القول إن الستيرويدات تحتوي على أحماض دهنية","عدّ حمض الستيريك من الستيرويدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.850Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CH₃(CH₂)₁₄COOH + CH₃(CH₂)₂₉OH → CH₃(CH₂)₁₄COO(CH₂)₂₉CH₃ + H₂O. (ب) رابطة إستر (–COO–) بين مجموعة الكربوكسيل في الحمض ومجموعة الهيدروكسيل في الكحول. (ج) يتكون الجزيء من سلسلتين هيدروكربونيتين طويلتين غير قطبيتين، فالجزيء غير قطبي لا ينجذب إلى الماء القطبي ولا يذوب فيه؛ ولذلك تكوّن الشموع طبقة على أوراق النبات تمنع فقدان الماء.', '["المتفاعلات الصحيحة","الناتج CH₃(CH₂)₁₄COO(CH₂)₂₉CH₃ + H₂O","رابطة إستر","الجزيء غير قطبي بسلسلتين طويلتين فلا يذوب في الماء","الطبقة الشمعية تمنع فقد الماء من الورقة"]'::jsonb, '["مجموعة OH من الحمض وذرة H من الكحول تكوّنان جزيء ماء.","ترتبط ذرة كربون الكربونيل بذرة أكسجين الكحول: CH₃(CH₂)₁₄COO(CH₂)₂₉CH₃."]'::jsonb, '[{"element":"المتفاعلات الصحيحة","marks":1},{"element":"الناتج CH₃(CH₂)₁₄COO(CH₂)₂₉CH₃ + H₂O","marks":2},{"element":"رابطة إستر","marks":1},{"element":"الجزيء غير قطبي بسلسلتين طويلتين فلا يذوب في الماء","marks":1},{"element":"الطبقة الشمعية تمنع فقد الماء من الورقة","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: المتفاعلات الصحيحة؛ الناتج CH₃(CH₂)₁₄COO(CH₂)₂₉CH₃ + H₂O؛ رابطة إستر؛ الجزيء غير قطبي بسلسلتين طويلتين فلا يذوب في الماء؛ الطبقة الشمعية تمنع فقد الماء من الورقة"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان جزيء الماء الناتج","كتابة الشمع بثلاث سلاسل كالجليسريد الثلاثي","عدّ الرابطة المتكونة رابطة ببتيدية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.850Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يشترك الكولسترول مع سائر الستيرويدات في التركيب الأساسي المكوّن من أربع حلقات كربونية ملتحمة: ثلاث حلقات سداسية وحلقة خماسية. (ب) الهيكل الكربوني للكولسترول حلقات ملتحمة تتصل بها سلسلة جانبية متفرعة، أما حمض الستيريك فسلسلة كربونية مستقيمة من 18 ذرة كربون. والكولسترول يحتوي على مجموعة هيدروكسيل –OH ولا يحتوي على مجموعة كربوكسيل، أما حمض الستيريك فيحتوي على مجموعة كربوكسيل –COOH. (ج) لا؛ لأن التصبن تميّه الجليسريد الثلاثي بقاعدة قوية بتفكك روابط الإستر فيه، والكولسترول ليس جليسريدًا ثلاثيًّا ولا يحتوي على روابط إستر.', '["التركيب الأساسي المشترك: أربع حلقات ملتحمة (ثلاث سداسية وواحدة خماسية)","الكولسترول حلقات ملتحمة، والستيريك سلسلة مستقيمة من 18 ذرة كربون","الكولسترول فيه مجموعة –OH ولا كربوكسيل، والستيريك فيه مجموعة كربوكسيل –COOH","لا يتصبن الكولسترول لأنه ليس جليسريدًا ثلاثيًّا ولا يحتوي على روابط إستر تتحلل بالقاعدة"]'::jsonb, '[]'::jsonb, '[{"element":"التركيب الأساسي المشترك: أربع حلقات ملتحمة (ثلاث سداسية وواحدة خماسية)","marks":1},{"element":"الكولسترول حلقات ملتحمة، والستيريك سلسلة مستقيمة من 18 ذرة كربون","marks":2},{"element":"الكولسترول فيه مجموعة –OH ولا كربوكسيل، والستيريك فيه مجموعة كربوكسيل –COOH","marks":1},{"element":"لا يتصبن الكولسترول لأنه ليس جليسريدًا ثلاثيًّا ولا يحتوي على روابط إستر تتحلل بالقاعدة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: التركيب الأساسي المشترك: أربع حلقات ملتحمة (ثلاث سداسية وواحدة خماسية)؛ الكولسترول حلقات ملتحمة، والستيريك سلسلة مستقيمة من 18 ذرة كربون؛ الكولسترول فيه مجموعة –OH ولا كربوكسيل، والستيريك فيه مجموعة كربوكسيل –COOH؛ لا يتصبن الكولسترول لأنه ليس جليسريدًا ثلاثيًّا ولا يحتوي على روابط إستر تتحلل بالقاعدة"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف التركيب الأساسي بأنه أربع حلقات سداسية","عدّ مجموعة –OH في الكولسترول مجموعة كربوكسيل","القول إن كل الليبيدات تتصبن بالقاعدة"]'::jsonb, '{"passed":tr