select (select id from public.objectives where code = 'K22-C6-L3-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل الشكل الآتي جزءًا من سلسلة حمض دهني طبيعي غير مشبع. ما التشكل الهندسي حول الرابطة الثنائية؟ وما أثره في شكل السلسلة؟', null, '[{"src":"qimg/chem22/c6-l3b-cis-bond.svg","alt":"جزء من سلسلة حمض دهني: ذرتا كربون C متصلتان برابطة ثنائية (خطان متوازيان)، وعلى كل منهما ذرة H متجهة نحو الأعلى، أي أن ذرتي الهيدروجين في الجهة نفسها من الرابطة الثنائية. وترتبط كل ذرة من ذرتي الكربون من أسفل بمجموعة CH₂ تمتد منها بقية السلسلة خطًّا متعرجًا نحو الأسفل: الطرف الأيسر ينتهي بـ … COOH، والطرف الأيمن ينتهي بـ CH₃ …، فيتباعد جزءا السلسلة على شكل زاوية عند الرابطة الثنائية."}]'::jsonb, '["سيس، فتنثني السلسلة عند الرابطة الثنائية","ترانس، فتنثني السلسلة عند الرابطة الثنائية","سيس، فتبقى السلسلة مستقيمة","ترانس، فتبقى السلسلة مستقيمة"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 220 — درجات انصهار الأحماض الدهنية غير المشبعة'),
('mcq', 2, 'يبين الشكل الآتي ترتيب جزيئات حمضين دهنيين لهما عدد ذرات الكربون نفسه في الحالة الصلبة. أي العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c6-l3b-packing.svg","alt":"لوحتان تمثلان ترتيب جزيئات حمضين دهنيين. في اللوحة (1) ثماني سلاسل متعرجة مستقيمة متوازية ومتقاربة جدًّا، في أعلى كل منها دائرة حمراء تمثل مجموعة الكربوكسيل. وفي اللوحة (2) خمس سلاسل في أعلى كل منها دائرة حمراء، وكل سلسلة تنثني عند نقطة قرب منتصفها فيميل جزؤها السفلي جانبًا، والمسافات بين السلاسل أكبر وترتيبها غير منتظم."}]'::jsonb, '["جزيئات (2) أكثر تراصًّا، فقوى التجاذب بينها أكبر ودرجة انصهارها أعلى","جزيئات (1) غير مشبعة لأن سلاسلها متعرجة، فدرجة انصهارها أقل","جزيئات (2) غير مشبعة وتراصها أقل، فقوى التجاذب أضعف ودرجة الانصهار أقل","قوى التجاذب في (1) و(2) متساوية لتساوي عدد ذرات الكربون في السلاسل"]'::jsonb, 'فهم', 'تحليل شكل', 'متوسط', 'الكتاب ص 220 — درجات انصهار الأحماض الدهنية غير المشبعة'),
('mcq', 3, 'ما سبب ضعف قوى التجاذب بين جزيئات الأحماض الدهنية الطبيعية غير المشبعة مقارنة بالأحماض الدهنية المشبعة؟', null, null, '["احتواؤها على عدد أكبر من ذرات الهيدروجين","روابطها الثنائية بصورة سيس تمنع تراص الجزيئات","خلوّ جزيئاتها من مجموعة الكربوكسيل","روابطها الثنائية بصورة ترانس تجعل سلاسلها مستقيمة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 220 — درجات انصهار الأحماض الدهنية غير المشبعة'),
('mcq', 4, 'يبين الجدول الآتي درجات انصهار تقريبية لثلاثة أحماض دهنية في كل منها 18 ذرة كربون. أي الاستنتاجات الآتية تدعمه البيانات؟', '{"headers":["الحمض الدهني","عدد ذرات الكربون","عدد الروابط الثنائية (سيس)","درجة الانصهار (°C)"],"rows":[["حمض الستيريك","18","0","70"],["حمض الأوليك","18","1","13"],["حمض اللينوليك","18","2","−5"]]}'::jsonb, null, '["تزداد درجة الانصهار بزيادة عدد الروابط الثنائية في السلسلة","لا تتأثر درجة الانصهار بعدد الروابط الثنائية لتساوي عدد ذرات الكربون","تقل درجة الانصهار لأن الروابط الثنائية تزيد قوى التجاذب بين الجزيئات","تقل درجة الانصهار بزيادة الروابط الثنائية سيس لأن انثناءاتها تقلل التراص"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 220 و235 — الأحماض الدهنية (الجدول 6-2)'),
('mcq', 5, 'درجة انصهار حمض اللوريك المشبع (12 ذرة كربون) 44 °C تقريبًا، ودرجة انصهار حمض الأوليك (18 ذرة كربون، رابطة ثنائية سيس واحدة) 13 °C تقريبًا. ما تفسير انخفاض درجة انصهار حمض الأوليك مع أن سلسلته أطول؟', null, null, '["انثناء سلسلته عند الرابطة سيس يقلل التراص، ويطغى ذلك على أثر طول السلسلة","السلاسل الأطول تكون قوى التجاذب بين جزيئاتها أضعف دائمًا، فتنخفض درجة انصهارها","حمض اللوريك غير مشبع وحمض الأوليك مشبع، فجزيئات اللوريك أكثر تراصًّا","حمض الأوليك لا يحتوي على مجموعة كربوكسيل، فلا تتكون بين جزيئاته قوى تجاذب"]'::jsonb, 'تحليل', 'تفسير مقارنة', 'صعب', 'الكتاب ص 220 و235 — الأحماض الدهنية (الجدول 6-2)'),
('mcq', 6, 'درجة انصهار حمض البالمتيك المشبع (16 ذرة كربون) 63 °C. أي الحمضين يُتوقع أن يكون سائلًا في درجة حرارة الغرفة (25 °C): حمض البالمتيك أم حمض البالمتوليك (16 ذرة كربون ورابطة ثنائية سيس واحدة)؟', null, null, '["حمض البالمتيك، لأن سلاسله المستقيمة لا تتراص","حمض البالمتوليك، لأن انثناء سلسلته يقلل التراص وقوى التجاذب","كلاهما صلب، لأن عدد ذرات الكربون فيهما متساوٍ","حمض البالمتوليك، لأن الرابطة الثنائية تزيد كتلته المولية"]'::jsonb, 'تطبيق', 'توقع وتبرير', 'متوسط', 'الكتاب ص 220 — درجات انصهار الأحماض الدهنية غير المشبعة'),
('mcq', 7, 'حمض الأوليك وحمض الإيلايديك كلاهما فيه 18 ذرة كربون ورابطة ثنائية واحدة بين ذرتي الكربون 9 و10، لكن الرابطة في حمض الأوليك بصورة سيس، وفي حمض الإيلايديك بصورة ترانس. فإذا كانت درجة انصهار حمض الأوليك 13 °C تقريبًا ودرجة انصهار حمض الإيلايديك 45 °C تقريبًا، فما تفسير هذا الفرق؟', null, null, '["حمض الإيلايديك مشبع، أما حمض الأوليك فغير مشبع","الرابطة ترانس تجعل الكتلة المولية لحمض الإيلايديك أكبر بكثير","الرابطة سيس أقوى من الرابطة ترانس فتحتاج إلى طاقة أكبر لتنكسر","الرابطة ترانس تبقي السلسلة شبه مستقيمة فتتراص الجزيئات أكثر"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 220 — الأحماض الدهنية غير المشبعة'),
('essay', 1, 'يبين الشكل الآتي ترتيب جزيئات حمضين دهنيين (1) و(2) لهما عدد ذرات الكربون نفسه. حدد أي الترتيبين يمثل حمضًا دهنيًّا مشبعًا وأيهما يمثل حمضًا غير مشبع، ثم فسّر لماذا تكون درجة انصهار الحمض غير المشبع أقل، متتبعًا التسلسل: شكل السلسلة ← التراص ← قوى التجاذب ← درجة الانصهار.', null, '[{"src":"qimg/chem22/c6-l3b-packing.svg","alt":"لوحتان تمثلان ترتيب جزيئات حمضين دهنيين. في اللوحة (1) ثماني سلاسل متعرجة مستقيمة متوازية ومتقاربة جدًّا، في أعلى كل منها دائرة حمراء تمثل مجموعة الكربوكسيل. وفي اللوحة (2) خمس سلاسل في أعلى كل منها دائرة حمراء، وكل سلسلة تنثني عند نقطة قرب منتصفها فيميل جزؤها السفلي جانبًا، والمسافات بين السلاسل أكبر وترتيبها غير منتظم."}]'::jsonb, null, 'فهم', 'تفسير بتسلسل', 'متوسط', 'الكتاب ص 220 — درجات انصهار الأحماض الدهنية غير المشبعة'),
('essay', 2, 'يبين الجدول الآتي درجات انصهار تقريبية لأربعة أحماض دهنية. (أ) رتّب الأحماض تصاعديًّا حسب درجة الانصهار. (ب) صف العلاقة بين عدد الروابط الثنائية ودرجة الانصهار، وفسّرها. (ج) توقع حالة كل حمض (صلب أو سائل) في درجة حرارة الغرفة 25 °C.', '{"headers":["الحمض الدهني","عدد ذرات الكربون","عدد الروابط الثنائية (سيس)","درجة الانصهار (°C)"],"rows":[["حمض الستيريك","18","0","70"],["حمض الأوليك","18","1","13"],["حمض اللينوليك","18","2","−5"],["حمض اللينولينيك","18","3","−11"]]}'::jsonb, null, null, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 220 و235 — الأحماض الدهنية (الجدول 6-2)'),
('essay', 3, 'قال طالب: «درجة انصهار حمض الأوليك أقل من درجة انصهار حمض الستيريك لأن كتلته المولية أقل». علمًا بأن الكتلة المولية لحمض الأوليك 282.5 g/mol ودرجة انصهاره 13 °C تقريبًا، ولحمض الستيريك 284.5 g/mol ودرجة انصهاره 70 °C، ولحمض اللوريك المشبع 200.3 g/mol ودرجة انصهاره 44 °C. قوّم قول الطالب مستعينًا بهذه البيانات، ثم اذكر التفسير الصحيح.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 220 و235 — الأحماض الدهنية (الجدول 6-2)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L3-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'ذرتا الهيدروجين على ذرتي كربون الرابطة الثنائية في الجهة نفسها، فالتشكل سيس، وجزءا السلسلة في الجهة نفسها من الرابطة الثنائية، فتنثني السلسلة عندها.', '["","في التشكل ترانس تكون ذرتا الهيدروجين في جهتين متعاكستين، أما في الشكل فهما في الجهة نفسها.","التشكل سيس فعلًا، لكنه يُحدث انثناءً في السلسلة لا استقامة.","ذرتا الهيدروجين في الجهة نفسها، فالتشكل ليس ترانس، والسلسلة في الشكل منثنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.851Z"}'::jsonb),
('mcq', 2, 2, 'سلاسل (2) منثنية بسبب الروابط الثنائية بصورة سيس، فهي غير مشبعة لا تتراص تراصًّا متقاربًا، فتضعف قوى التجاذب بين جزيئاتها وتنخفض درجة انصهارها مقارنة بسلاسل (1) المستقيمة المشبعة.', '["جزيئات (2) هي الأقل تراصًّا، والمسافات بينها أكبر.","التعرج المنتظم صفة كل سلسلة كربونية؛ أما الانثناء الذي يدل على عدم التشبع فيظهر في (2) لا في (1).","","تساوي عدد ذرات الكربون لا يعني تساوي قوى التجاذب؛ فالتراص يختلف بين الترتيبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.851Z"}'::jsonb),
('mcq', 3, 1, 'توجد الروابط الثنائية في الأحماض الدهنية الطبيعية كلها تقريبًا بصورة سيس، وهذا لا يساعد على تراص جزيئاتها، فلا تتكوّن قوى تجاذب كثيرة بينها كما في المشبعة، ولذلك تكون درجات انصهارها أقل.', '["الحمض غير المشبع يحتوي على عدد أقل من ذرات الهيدروجين مقارنة بالمشبع المماثل له في عدد ذرات الكربون.","","الأحماض الدهنية جميعها أحماض كربوكسيلية تحتوي على مجموعة الكربوكسيل.","الروابط الثنائية في الأحماض الدهنية الطبيعية بصورة سيس لا ترانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.851Z"}'::jsonb),
('mcq', 4, 3, 'مع ثبات عدد ذرات الكربون (18) تنخفض درجة الانصهار من 70 °C (لا روابط ثنائية) إلى 13 °C (رابطة واحدة) ثم إلى −5 °C (رابطتان)؛ فكل رابطة ثنائية سيس تزيد انثناء السلسلة وتقلل تراص الجزيئات فتضعف قوى التجاذب.', '["البيانات تبين العكس: كلما زاد عدد الروابط الثنائية انخفضت درجة الانصهار.","درجات الانصهار مختلفة كثيرًا مع أن عدد ذرات الكربون واحد، فعدد الروابط الثنائية مؤثر.","الاتجاه صحيح لكن التفسير خاطئ: الروابط الثنائية سيس تُضعف قوى التجاذب لأنها تقلل التراص.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.851Z"}'::jsonb),
('mcq', 5, 0, 'زيادة طول السلسلة ترفع درجة الانصهار عادة، لكن الرابطة الثنائية سيس في حمض الأوليك تُحدث انثناءً يمنع تراص الجزيئات فتضعف قوى التجاذب بينها، وهذا الأثر أكبر من أثر زيادة طول السلسلة، فتكون درجة انصهاره أقل.', '["","في الأحماض الدهنية المشبعة ترتفع درجة الانصهار بزيادة عدد ذرات الكربون (مثلًا اللوريك 44 °C والستيريك 70 °C).","عكس الوصف: حمض اللوريك مشبع، وحمض الأوليك غير مشبع لاحتوائه على رابطة ثنائية.","حمض الأوليك حمض دهني، وكل الأحماض الدهنية تحتوي على مجموعة الكربوكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-15T02:47:48.852Z"}'::jsonb),
('mcq', 6, 1, 'حمض البالمتيك مشبع ودرجة انصهاره 63 °C فهو صلب عند 25 °C. أما حمض البالمتوليك فرابطته الثنائية سيس تُحدث انثناءً يقلل تراص جزيئاته فتضعف قوى التجاذب وتنخفض درجة انصهاره كثيرًا، فيُتوقع أن يكون سائلًا في درجة حرارة الغرفة.', '["السلاسل المستقيمة المشبعة تتراص تراصًّا متقاربًا، ودرجة انصهار البالمتيك 63 °C أعلى من 25 °C.","","تساوي عدد ذرات الكربون لا يعني تساوي درجتي الانصهار؛ فالرابطة الثنائية سيس تخفض درجة الانصهار.","الحمض غير المشبع كتلته المولية أقل قليلًا (ذرتا هيدروجين أقل)، والسبب الحقيقي هو قلة التراص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.852Z"}'::jsonb),
('mcq', 7, 3, 'في صورة ترانس يقع جزءا السلسلة في جهتين متعاكستين من الرابطة الثنائية فتبقى السلسلة شبه مستقيمة، فتتراص جزيئات حمض الإيلايديك وتزداد قوى التجاذب بينها، فترتفع درجة انصهاره. أما الرابطة سيس في حمض الأوليك فتسبب انثناء السلسلة فيقل التراص وتنخفض درجة الانصهار.', '["كلا الحمضين فيه رابطة ثنائية بين ذرتي كربون، فكلاهما غير مشبع.","للحمضين الصيغة الجزيئية نفسها والكتلة المولية نفسها؛ فهما متشكلان هندسيان.","الانصهار لا يكسر الروابط داخل الجزيء، بل يتغلب على قوى التجاذب بين الجزيئات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-15T02:47:48.852Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الترتيب (1) حمض دهني مشبع (سلاسل مستقيمة)، والترتيب (2) حمض دهني غير مشبع (سلاسل منثنية). شكل السلسلة: الروابط الثنائية في الأحماض الطبيعية بصورة سيس فتنثني السلسلة عندها. التراص: السلاسل المنثنية لا تتراص تراصًّا متقاربًا كالسلاسل المستقيمة. قوى التجاذب: لا تتكوّن بين جزيئات الحمض غير المشبع قوى تجاذب كثيرة كما في المشبع. درجة الانصهار: يلزم طاقة أقل لفصل الجزيئات، فتكون درجة انصهار الحمض غير المشبع أقل.', '["(1) مشبع و(2) غير مشبع","الرابطة سيس تجعل السلسلة منثنية","الانثناء يقلل التراص","قلة التراص تضعف قوى التجاذب","قوى أضعف ← درجة انصهار أقل"]'::jsonb, '[]'::jsonb, '[{"element":"(1) مشبع و(2) غير مشبع","marks":1},{"element":"الرابطة سيس تجعل السلسلة منثنية","marks":1},{"element":"الانثناء يقلل التراص","marks":1},{"element":"قلة التراص تضعف قوى التجاذب","marks":1},{"element":"قوى أضعف ← درجة انصهار أقل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (1) مشبع و(2) غير مشبع؛ الرابطة سيس تجعل السلسلة منثنية؛ الانثناء يقلل التراص؛ قلة التراص تضعف قوى التجاذب؛ قوى أضعف ← درجة انصهار أقل"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيبين","تفسير الانخفاض بقلة الكتلة المولية","القول إن الروابط الثنائية أضعف فتنكسر عند الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.852Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) اللينولينيك (−11 °C) < اللينوليك (−5 °C) < الأوليك (13 °C) < الستيريك (70 °C). (ب) كلما زاد عدد الروابط الثنائية (سيس) انخفضت درجة الانصهار مع ثبات عدد ذرات الكربون؛ لأن كل رابطة سيس تُحدث انثناءً في السلسلة، فيقل تراص الجزيئات وتضعف قوى التجاذب بينها. (ج) الستيريك صلب (70 °C أعلى من 25 °C)، والأوليك واللينوليك واللينولينيك سائلة (درجات انصهارها أقل من 25 °C).', '["الترتيب التصاعدي الصحيح","العلاقة: زيادة الروابط الثنائية تخفض درجة الانصهار","التفسير: انثناء سيس ← تراص أقل ← قوى تجاذب أضعف","الحالات الصحيحة عند 25 °C"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب التصاعدي الصحيح","marks":1},{"element":"العلاقة: زيادة الروابط الثنائية تخفض درجة الانصهار","marks":1},{"element":"التفسير: انثناء سيس ← تراص أقل ← قوى تجاذب أضعف","marks":2},{"element":"الحالات الصحيحة عند 25 °C","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الترتيب التصاعدي الصحيح؛ العلاقة: زيادة الروابط الثنائية تخفض درجة الانصهار؛ التفسير: انثناء سيس ← تراص أقل ← قوى تجاذب أضعف؛ الحالات الصحيحة عند 25 °C"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترتيب تنازليًّا بدل تصاعديًّا","عدّ حمض الأوليك صلبًا لأن 13 °C قيمة موجبة","تفسير العلاقة بتغير عدد ذرات الكربون مع أنه ثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.853Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. فالفرق في الكتلة المولية بين الأوليك والستيريك 2.0 g/mol فقط (أقل من 1%)، ولا يمكن أن يفسر فرقًا في درجة الانصهار مقداره 57 °C. كما أن حمض اللوريك كتلته المولية أقل بكثير من حمض الأوليك (200.3 g/mol مقابل 282.5 g/mol) ومع ذلك درجة انصهاره أعلى (44 °C مقابل 13 °C)، فالكتلة المولية ليست العامل الحاسم هنا. التفسير الصحيح: حمض الأوليك غير مشبع، ورابطته الثنائية بصورة سيس تجعل سلسلته منثنية فلا تتراص جزيئاته تراصًّا متقاربًا، فتضعف قوى التجاذب بينها وتنخفض درجة انصهاره، أما الستيريك واللوريك فمشبعان سلاسلهما مستقيمة متراصة.', '["الحكم: القول غير صحيح","فرق الكتلة 2.0 g/mol صغير جدًّا مقابل فرق 57 °C","مثال اللوريك: كتلة أقل ودرجة انصهار أعلى من الأوليك","التفسير الصحيح: الرابطة سيس ← انثناء ← تراص أقل","قوى تجاذب أضعف ← درجة انصهار أقل"]'::jsonb, '["284.5 − 282.5 = 2.0 g/mol","70 − 13 = 57 °C","اللوريك: 200.3 g/mol < 282.5 g/mol لكن 44 °C > 13 °C"]'::jsonb, '[{"element":"الحكم: القول غير صحيح","marks":1},{"element":"فرق الكتلة 2.0 g/mol صغير جدًّا مقابل فرق 57 °C","marks":1},{"element":"مثال اللوريك: كتلة أقل ودرجة انصهار أعلى من الأوليك","marks":1},{"element":"التفسير الصحيح: الرابطة سيس ← انثناء ← تراص أقل","marks":1},{"element":"قوى تجاذب أضعف ← درجة انصهار أقل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم: القول غير صحيح؛ فرق الكتلة 2.0 g/mol صغير جدًّا مقابل فرق 57 °C؛ مثال اللوريك: كتلة أقل ودرجة انصهار أعلى من الأوليك؛ التفسير الصحيح: الرابطة سيس ← انثناء ← تراص أقل؛ قوى تجاذب أضعف ← درجة انصهار أقل"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول قول الطالب لأن الاتجاه يبدو متوافقًا","إغفال مقارنة اللوريك بالأوليك","عدم ذكر التشكل سيس في التفسير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.853Z"}'::jsonb)
