('mcq', 2, 'ما الصيغة المكثفة للناتج في التفاعل الآتي؟', null, '[{"src":"qimg/chem22/c6-l3b-palmitoleic-h2.svg","alt":"معادلة كيميائية. في اليسار صيغة هيكلية لحمض دهني: مجموعة كربوكسيل (ذرة كربون عليها O برابطة ثنائية ومجموعة HO)، تليها سلسلة متعرجة، ومجموع ذرات الكربون مع ذرة الكربوكسيل 16 ذرة، وفي السلسلة رابطة ثنائية واحدة بصورة سيس بين ذرتي الكربون التاسعة والعاشرة بدءًا من ذرة الكربوكسيل، تنثني السلسلة عندها نحو الأسفل. ثم إشارة + وH₂، ثم سهم كُتب فوقه Pt، ثم مربع منقط بداخله علامة استفهام تمثل الناتج."}]'::jsonb, '["CH₃(CH₂)₁₄COOH","CH₃(CH₂)₁₆COOH","CH₃(CH₂)₅CH=CH(CH₂)₇COOH","CH₃(CH₂)₁₄CH₂OH"]'::jsonb, 'تطبيق', 'توقع ناتج', 'متوسط', 'الكتاب ص 220 — هدرجة الأحماض الدهنية غير المشبعة'),
('mcq', 3, 'يمثل الشكل الآتي حمض اللينولينيك C₁₈H₃₀O₂. أي المعادلات الآتية تمثل هدرجته التامة تمثيلًا موزونًا؟', null, '[{"src":"qimg/chem22/c6-l3b-linolenic.svg","alt":"صيغة هيكلية لحمض دهني: في اليسار مجموعة كربوكسيل (ذرة كربون عليها O برابطة ثنائية ومجموعة HO)، تليها سلسلة متعرجة، ومجموع ذرات الكربون مع ذرة الكربوكسيل 18 ذرة. في السلسلة ثلاث روابط ثنائية بصورة سيس: بين الذرتين 9 و10، وبين 12 و13، وبين 15 و16 بدءًا من ذرة الكربوكسيل، وتنتهي السلسلة بذرتي كربون بعد آخر رابطة ثنائية."}]'::jsonb, '["C₁₈H₃₀O₂ + H₂ → C₁₈H₃₂O₂","C₁₈H₃₀O₂ + 2H₂ → C₁₈H₃₄O₂","C₁₈H₃₀O₂ + 3H₂ → C₁₈H₃₄O₂","C₁₈H₃₀O₂ + 3H₂ → C₁₈H₃₆O₂"]'::jsonb, 'تطبيق', 'اختيار معادلة موزونة', 'متوسط', 'الكتاب ص 233 — س66 (هدرجة حمض اللينولينيك)'),
('mcq', 4, 'ما كتلة غاز الهيدروجين H₂ اللازمة لهدرجة 56.5 g من حمض الأوليك CH₃(CH₂)₇CH=CH(CH₂)₇COOH هدرجة تامة؟ (الكتلة المولية لحمض الأوليك 282.5 g/mol، ولـ H₂ هي 2.016 g/mol)', null, null, '["0.0992 g","0.202 g","0.403 g","0.806 g"]'::jsonb, 'تطبيق', 'حساب كمية متفاعل', 'صعب', 'الكتاب ص 220 — هدرجة حمض الأوليك'),
('mcq', 5, 'حمض الأراكيدونيك حمض دهني صيغته CH₃(CH₂)₄(CH=CHCH₂)₄(CH₂)₂COOH. ما ناتج هدرجته التامة؟ وكم مولًا من H₂ يلزم لكل 1 mol منه؟', null, null, '["حمض الستيريك CH₃(CH₂)₁₆COOH، و4 mol من H₂","حمض الأراكيديك CH₃(CH₂)₁₈COOH، و2 mol من H₂","حمض الأراكيديك CH₃(CH₂)₁₈COOH، و8 mol من H₂","حمض الأراكيديك CH₃(CH₂)₁₈COOH، و4 mol من H₂"]'::jsonb, 'تطبيق', 'توقع ناتج وحساب', 'متوسط', 'الكتاب ص 220 — هدرجة الأحماض الدهنية غير المشبعة'),
('mcq', 6, 'كم مولًا من H₂ يلزم لهدرجة 1 mol من جليسريد ثلاثي يحتوي كل من سلاسله الثلاث على رابطة ثنائية واحدة؟ وكيف تتغير حالته في درجة حرارة الغرفة؟', null, null, '["3 mol، ويتحول من زيت سائل إلى دهن صلب","1 mol، ويتحول من زيت سائل إلى دهن صلب","3 mol، ويتحول من دهن صلب إلى زيت سائل","6 mol، ويتحول من زيت سائل إلى دهن صلب"]'::jsonb, 'تطبيق', 'حساب وتوقع', 'صعب', 'الكتاب ص 220 — الهدرجة تفاعل إضافة'),
('mcq', 7, 'ما الذي يتغير في الصيغة الجزيئية لحمض دهني عند هدرجة رابطة ثنائية واحدة فيه؟', null, null, '["يقل عدد ذرات الهيدروجين بمقدار 2، ويبقى عدد ذرات الكربون ثابتًا","يزداد عدد ذرات الهيدروجين بمقدار 2، ويبقى عدد ذرات الكربون ثابتًا","يزداد عدد ذرات الكربون بمقدار 2، ويبقى عدد ذرات الهيدروجين ثابتًا","يزداد عدد ذرات الأكسجين بمقدار 1، ويبقى عدد ذرات الكربون ثابتًا"]'::jsonb, 'فهم', 'تفسير تغير الصيغة', 'سهل', 'الكتاب ص 220 — هدرجة الأحماض الدهنية غير المشبعة'),
('essay', 1, 'حمض الميريستوليك حمض دهني غير مشبع صيغته CH₃(CH₂)₃CH=CH(CH₂)₇COOH. (أ) اكتب معادلة هدرجته التامة بالصيغ المكثفة. (ب) كم عدد ذرات الكربون في الناتج؟ وهل هو مشبع أم غير مشبع؟ (ج) اذكر نوع التفاعل، ومثالًا على عامل محفز يُستعمل فيه.', null, null, null, 'تطبيق', 'كتابة معادلة', 'سهل', 'الكتاب ص 220، 235 — هدرجة الأحماض الدهنية غير المشبعة'),
('essay', 2, 'يُهدرج الجليسريد الثلاثي ثلاثي أوليات الجليسريل C₅₇H₁₀₄O₆، الذي ترتبط فيه بالجليسرول ثلاث سلاسل من حمض الأوليك –C(=O)(CH₂)₇CH=CH(CH₂)₇CH₃، هدرجة تامة فيتكون ثلاثي ستيارات الجليسريل C₅₇H₁₁₀O₆. (أ) اكتب المعادلة الموزونة بالصيغ الجزيئية. (ب) احسب كتلة H₂ اللازمة لهدرجة 88.5 g منه، وكتلة الناتج. (الكتل المولية: C₅₇H₁₀₄O₆ = 885.4 g/mol، وC₅₇H₁₁₀O₆ = 891.4 g/mol، وH₂ = 2.016 g/mol) (ج) فسّر لماذا تُستعمل هذه العملية في صناعة السمن من الزيوت النباتية.', null, null, null, 'تطبيق', 'معادلة وحساب', 'صعب', 'الكتاب ص 220 — الهدرجة'),
('essay', 3, 'اكتب معادلة الهدرجة التامة لكل من حمض الأوليك CH₃(CH₂)₇CH=CH(CH₂)₇COOH وحمض اللينولينيك CH₃CH₂CH=CHCH₂CH=CHCH₂CH=CH(CH₂)₇COOH بالصيغ المكثفة، ثم قارن بين التفاعلين من حيث: عدد مولات H₂ اللازمة لكل 1 mol من الحمض، والناتج.', null, null, null, 'تطبيق', 'كتابة معادلات ومقارنة', 'متوسط', 'الكتاب ص 233 — س66 (هدرجة حمض اللينولينيك)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L3-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الهدرجة تفاعل إضافة يتفاعل فيه غاز الهيدروجين مع ذرات الكربون المرتبطة بروابط ثنائية، فتتشبع السلسلة.', '["الحذف يكوّن رابطة ثنائية بنزع ذرات، وهو عكس الهدرجة.","","التصبن تحلل الجليسريد الثلاثي بقاعدة قوية، ولا يدخل فيه H₂.","التكاثف يربط جزيئين مع تحرر جزيء صغير كالماء، والهدرجة لا يتحرر فيها شيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.853Z"}'::jsonb),
('mcq', 2, 0, 'المتفاعل حمض دهني فيه 16 ذرة كربون ورابطة ثنائية واحدة (حمض البالمتوليك CH₃(CH₂)₅CH=CH(CH₂)₇COOH). يضاف جزيء H₂ واحد إلى الرابطة الثنائية فتتشبع السلسلة ويبقى عدد ذرات الكربون 16، فيكون الناتج حمض البالمتيك CH₃(CH₂)₁₄COOH.', '["","هذا حمض الستيريك ذو 18 ذرة كربون، والهدرجة لا تغيّر عدد ذرات الكربون (16).","هذه صيغة المتفاعل نفسه قبل إضافة H₂، والرابطة الثنائية ما زالت فيها.","الهدرجة تُشبع الرابطة الثنائية C=C ولا تحوّل مجموعة الكربوكسيل إلى مجموعة كحول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('mcq', 3, 3, 'في الجزيء ثلاث روابط ثنائية، ويضاف جزيء H₂ لكل رابطة، فيلزم 3H₂. ذرات الهيدروجين في الناتج 30 + 6 = 36، فالناتج C₁₈H₃₆O₂ (حمض الستيريك) والمعادلة C₁₈H₃₀O₂ + 3H₂ → C₁₈H₃₆O₂.', '["عدّ رابطة ثنائية واحدة فقط، والجزيء فيه ثلاث روابط ثنائية.","عدّ رابطتين ثنائيتين فقط، فبقيت رابطة ثنائية دون هدرجة.","المعادلة غير موزونة: في الطرف الأيسر 36 ذرة هيدروجين وفي الأيمن 34.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('mcq', 4, 2, 'عدد مولات الحمض = 56.5 g ÷ 282.5 g/mol = 0.200 mol. في الجزيء رابطة ثنائية C=C واحدة، فيلزم 1 mol من H₂ لكل 1 mol من الحمض: n(H₂) = 0.200 mol، وكتلته = 0.200 mol × 2.016 g/mol = 0.403 g.', '["قُسم عدد مولات H₂ على كتلته المولية (0.200 ÷ 2.016) بدل الضرب فيها.","استُعملت الكتلة المولية لذرة الهيدروجين 1.008 g/mol بدل الكتلة المولية لجزيء H₂.","","عُدّت الرابطة C=O في مجموعة الكربوكسيل رابطة ثنائية تُهدرج، فحُسب 2 mol من H₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('mcq', 5, 3, 'عدد ذرات الكربون: 1 + 4 + (4 × 3) + 2 + 1 = 20، وفي الصيغة أربع روابط ثنائية (CH=CH مكررة 4 مرات)، فيلزم 4 mol من H₂، والناتج حمض مشبع فيه 20 ذرة كربون هو حمض الأراكيديك CH₃(CH₂)₁₈COOH.', '["الهدرجة لا تغيّر عدد ذرات الكربون، والحمض فيه 20 ذرة كربون لا 18.","في الصيغة أربع روابط ثنائية، لا اثنتان.","عدّ ذرات الهيدروجين المضافة (8) بدل جزيئات H₂ (4).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('mcq', 6, 0, 'في الجزيء ثلاث روابط ثنائية (واحدة في كل سلسلة)، ويلزم جزيء H₂ لكل رابطة، فيلزم 3 mol. وبعد الهدرجة تصبح السلاسل مشبعة مستقيمة تتراص بسهولة، فيتحول الزيت السائل إلى دهن صلب، كما في تصنيع السمن من الزيوت النباتية.', '["","يلزم جزيء H₂ لكل رابطة ثنائية، وفي الجزيء ثلاث روابط، لا رابطة واحدة.","عدد المولات صحيح لكن اتجاه التغير معكوس: الهدرجة ترفع درجة الانصهار فيتصلب الزيت.","عدّ ذرات الهيدروجين (6) بدل جزيئات H₂ (3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('mcq', 7, 1, 'يُضاف جزيء H₂ واحد إلى الرابطة الثنائية، فيزداد عدد ذرات الهيدروجين بمقدار 2 فقط، ولا يتغير عدد ذرات الكربون أو الأكسجين (مثل C₁₈H₃₄O₂ + H₂ → C₁₈H₃₆O₂).', '["الهدرجة إضافة للهيدروجين، فيزداد عدده لا يقل.","","الهدرجة لا تضيف ذرات كربون إلى السلسلة.","الهدرجة لا تضيف أكسجين؛ فالمتفاعل المضاف هو H₂ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) CH₃(CH₂)₃CH=CH(CH₂)₇COOH + H₂ → CH₃(CH₂)₁₂COOH. (ب) في الناتج 14 ذرة كربون (الهدرجة لا تغير عدد ذرات الكربون)، وهو حمض دهني مشبع لا روابط ثنائية فيه (حمض الميريستيك). (ج) التفاعل تفاعل إضافة (هدرجة)، ويُستعمل فيه محفز مثل البلاتين Pt.', '["المتفاعلات: الحمض + H₂ واحد","الناتج CH₃(CH₂)₁₂COOH","الناتج مشبع وفيه 14 ذرة كربون (حمض الميريستيك)","نوع التفاعل: إضافة (هدرجة) ومحفز Pt"]'::jsonb, '["عدد ذرات الكربون: 1 + 3 + 2 + 7 + 1 = 14.","يضاف H₂ واحد إلى CH=CH فتصبح CH₂–CH₂، فتصير السلسلة (CH₂)₁₂ بين CH₃ ومجموعة COOH."]'::jsonb, '[{"element":"المتفاعلات: الحمض + H₂ واحد","marks":1},{"element":"الناتج CH₃(CH₂)₁₂COOH","marks":1},{"element":"الناتج مشبع وفيه 14 ذرة كربون (حمض الميريستيك)","marks":1},{"element":"نوع التفاعل: إضافة (هدرجة) ومحفز Pt","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: المتفاعلات: الحمض + H₂ واحد؛ الناتج CH₃(CH₂)₁₂COOH؛ الناتج مشبع وفيه 14 ذرة كربون (حمض الميريستيك)؛ نوع التفاعل: إضافة (هدرجة) ومحفز Pt"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ناتج بعدد مختلف من ذرات الكربون","إضافة 2H₂ لرابطة ثنائية واحدة","تصنيف التفاعل تفاعل حذف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-15T02:47:48.854Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) C₅₇H₁₀₄O₆ + 3H₂ → C₅₇H₁₁₀O₆ (رابطة ثنائية واحدة في كل سلسلة، فثلاث روابط تحتاج إلى 3H₂). (ب) n = 88.5 g ÷ 885.4 g/mol = 0.100 mol؛ n(H₂) = 3 × 0.100 = 0.300 mol؛ m(H₂) = 0.300 mol × 2.016 g/mol = 0.605 g؛ m(الناتج) = 0.100 mol × 891.4 g/mol = 89.1 g (وتساوي 88.5 + 0.605 ≈ 89.1 g). (ج) الهدرجة تحوّل السلاسل غير المشبعة المنثنية إلى سلاسل مشبعة مستقيمة تتراص بسهولة، فترتفع درجة الانصهار ويتحول الزيت السائل إلى دهن صلب في درجة حرارة الغرفة كالسمن.', '["المعادلة C₅₇H₁₀₄O₆ + 3H₂ → C₅₇H₁₁₀O₆","عدد المولات 0.100 mol","كتلة H₂ = 0.605 g","كتلة الناتج = 89.1 g","التفسير: تشبع السلاسل ← تراص ← درجة انصهار أعلى ← صلب"]'::jsonb, '["n = 88.5 ÷ 885.4 = 0.100 mol","n(H₂) = 3 × 0.100 = 0.300 mol","m(H₂) = 0.300 × 2.016 = 0.605 g","m(الناتج) = 0.100 × 891.4 = 89.1 g"]'::jsonb, '[{"element":"المعادلة C₅₇H₁₀₄O₆ + 3H₂ → C₅₇H₁₁₀O₆","marks":2},{"element":"عدد المولات 0.100 mol","marks":1},{"element":"كتلة H₂ = 0.605 g","marks":1},{"element":"كتلة الناتج = 89.1 g","marks":1},{"element":"التفسير: تشبع السلاسل ← تراص ← درجة انصهار أعلى ← صلب","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: المعادلة C₅₇H₁₀₄O₆ + 3H₂ → C₅₇H₁₁₀O₆؛ عدد المولات 0.100 mol؛ كتلة H₂ = 0.605 g؛ كتلة الناتج = 89.1 g؛ التفسير: تشبع السلاسل ← تراص ← درجة انصهار أعلى ← صلب"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال H₂ واحد للجزيء كله","استعمال 1.008 g/mol لـ H₂","القول إن الهدرجة تحوّل الدهن الصلب إلى زيت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-15T02:47:48.855Z"}'::jsonb),
('essay', 3, null::int, null, null, 'حمض الأوليك: CH₃(CH₂)₇CH=CH(CH₂)₇COOH + H₂ → CH₃(CH₂)₁₆COOH. حمض اللينولينيك: CH₃CH₂CH=CHCH₂CH=CHCH₂CH=CH(CH₂)₇COOH + 3H₂ → CH₃(CH₂)₁₆COOH. المقارنة: يلزم 1 mol من H₂ لحمض الأوليك (رابطة ثنائية واحدة) و3 mol لحمض اللينولينيك (ثلاث روابط ثنائية)، أما الناتج فواحد في الحالتين: حمض الستيريك CH₃(CH₂)₁₆COOH المشبع ذو 18 ذرة كربون، لأن للحمضين عدد ذرات الكربون نفسه (18) والهدرجة لا تغيّره.', '["معادلة هدرجة الأوليك صحيحة وموزونة","معادلة هدرجة اللينولينيك صحيحة وموزونة (3H₂)","المقارنة: 1 mol مقابل 3 mol من H₂","الناتج واحد: حمض الستيريك، مع التعليل"]'::jsonb, '["عدد ذرات الكربون في كل حمض = 18.","عدد الروابط الثنائية: الأوليك 1، اللينولينيك 3 ← H₂ واحد لكل رابطة.","الناتج المشبع ذو 18 ذرة كربون: CH₃(CH₂)₁₆COOH."]'::jsonb, '[{"element":"معادلة هدرجة الأوليك صحيحة وموزونة","marks":1},{"element":"معادلة هدرجة اللينولينيك صحيحة وموزونة (3H₂)","marks":2},{"element":"المقارنة: 1 mol مقابل 3 mol من H₂","marks":1},{"element":"الناتج واحد: حمض الستيريك، مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: معادلة هدرجة الأوليك صحيحة وموزونة؛ معادلة هدرجة اللينولينيك صحيحة وموزونة (3H₂)؛ المقارنة: 1 mol مقابل 3 mol من H₂؛ الناتج واحد: حمض الستيريك، مع التعليل"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ناتجين مختلفين للحمضين","استعمال H₂ واحد لحمض اللينولينيك","تغيير عدد ذرات الكربون في الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-15T02:47:48.855Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C6-L3-O10') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L4-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أي مما يأتي يصف الشكل العام لجزيء DNA وصفًا صحيحًا؟', null, null, '["شريط واحد من النيوكليوتيدات ملتف على نفسه","سلسلتان من النيوكليوتيدات ملتفتان معًا حلزونيًّا","ثلاث سلاسل من النيوكليوتيدات مجدولة معًا","سلسلتان من النيوكليوتيدات متوازيتان دون التفاف"]'::jsonb, 'فهم', 'وصف تركيب', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 2, 'ما اسم السكر الخماسي الموجود في نيوكليوتيدات DNA؟', null, null, '["الرايبوز","الجلوكوز","الفركتوز","الديوكسي رايبوز"]'::jsonb, 'تذكر', 'تذكر مكوّن', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 3, 'يمثل الشكل الآتي قطعة من جزيء DNA. مِمَّ يتكون الجزء المشار إليه بالرقم 1؟', null, '[{"src":"qimg/chem22/c6-l4a-dna-parts.svg","alt":"مخطط تخطيطي لقطعة من جزيء DNA مرسومة أفقيًا: شريطان متوازيان، علوي وسفلي. يتكون كل شريط من مخمسات صفراء تتعاقب مع دوائر خضراء على خط واحد، ومن كل مخمس يتجه مستطيل يحمل حرف قاعدة نحو الداخل. قواعد الشريط العلوي من اليسار إلى اليمين: A، T، G، C، A، T، وتقابلها في الشريط السفلي بالترتيب: T، A، C، G، T، A. بين كل مستطيلين متقابلين خطان متقطعان قصيران. الرقم 1 يشير مرتين: إلى الشريط الخارجي العلوي المكوّن من المخمسات والدوائر، وإلى الشريط الخارجي السفلي المماثل. الرقم 2 يشير إلى المنطقة الوسطى بين المستطيلات العلوية والسفلية المتقابلة حيث الخطوط المتقطعة."}]'::jsonb, '["جزيئات سكر ومجموعات فوسفات متعاقبة","قواعد نيتروجينية متزاوجة","أحماض أمينية مرتبطة بروابط ببتيدية","جزيئات جلسرول وأحماض دهنية متعاقبة"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج (الشكل 6-21)'),
('mcq', 4, 'في الشكل الآتي لقطعة من DNA، ما نوع الترابط الذي يمسك السلسلتين معًا في المنطقة المشار إليها بالرقم 2؟', null, '[{"src":"qimg/chem22/c6-l4a-dna-parts.svg","alt":"مخطط تخطيطي لقطعة من جزيء DNA مرسومة أفقيًا: شريطان متوازيان، علوي وسفلي. يتكون كل شريط من مخمسات صفراء تتعاقب مع دوائر خضراء على خط واحد، ومن كل مخمس يتجه مستطيل يحمل حرف قاعدة نحو الداخل. قواعد الشريط العلوي من اليسار إلى اليمين: A، T، G، C، A، T، وتقابلها في الشريط السفلي بالترتيب: T، A، C، G، T، A. بين كل مستطيلين متقابلين خطان متقطعان قصيران. الرقم 1 يشير مرتين: إلى الشريط الخارجي العلوي المكوّن من المخمسات والدوائر، وإلى الشريط الخارجي السفلي المماثل. الرقم 2 يشير إلى المنطقة الوسطى بين المستطيلات العلوية والسفلية المتقابلة حيث الخطوط المتقطعة."}]'::jsonb, '["روابط ببتيدية بين جزيئات السكر في السلسلتين","روابط تساهمية بين مجموعات الفوسفات المتقابلة","روابط هيدروجينية بين القواعد النيتروجينية المتقابلة","روابط أيونية بين السكر في سلسلة والقاعدة في الأخرى"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 5, 'يمثل الشكل الآتي قطعة من جزيء DNA، وقد أُخفيت إحدى القواعد في الشريط السفلي ووُضعت مكانها علامة «؟». ما القاعدة المخفية؟', null, '[{"src":"qimg/chem22/c6-l4a-dna-unknown.svg","alt":"مخطط تخطيطي لقطعة من جزيء DNA مرسومة أفقيًا: شريطان، علوي وسفلي. يتكون كل شريط من مخمسات صفراء تتعاقب مع دوائر خضراء على خط واحد، ومن كل مخمس يتجه مستطيل يحمل حرف قاعدة نحو الداخل، وبين كل مستطيلين متقابلين خطان متقطعان. قواعد الشريط العلوي من اليسار إلى اليمين: T، A، G، C، G، A. وقواعد الشريط السفلي المقابلة لها بالترتيب: A، T، C، ؟، C، T؛ أي أن علامة الاستفهام في الموضع الرابع، مقابل القاعدة C في الشريط العلوي."}]'::jsonb, '["السايتوسين (C)","الأدينين (A)","الجوانين (G)","اليوراسيل (U)"]'::jsonb, 'تطبيق', 'تطبيق تزاوج القواعد', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج (الشكل 6-22)'),
('mcq', 6, 'حُلِّلت عينة من DNA فوُجد أن الأدينين (A) يشكّل 30% من قواعدها النيتروجينية. ما النسبة المئوية للجوانين (G) في العينة؟', null, null, '["20%","30%","40%","70%"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 225 — أزواج القواعد المتطابقة؛ ص 236 اختبار مقنن س3'),
('mcq', 7, 'أي العبارات الآتية تصف أزواج القواعد النيتروجينية في DNA وصفًا صحيحًا؟', null, null, '["يرتبط الأدينين بالجوانين لأن كلًّا منهما ذو حلقتين","يتكون كل زوج من قاعدة ذات حلقتين وقاعدة ذات حلقة واحدة","يرتبط الثايمين بالسايتوسين لأن كلًّا منهما ذو حلقة واحدة","يرتبط الأدينين بالثايمين بثلاث روابط هيدروجينية"]'::jsonb, 'فهم', 'وصف وتمييز', 'صعب', 'الكتاب ص 225 — DNA: اللولب المزدوج (الشكل 6-22)'),
('essay', 1, 'صف تركيب جزيء DNA، موضحًا: عدد سلاسله وشكله، ومكونات الجزء الخارجي (العمود الفقري)، وموقع القواعد النيتروجينية، وما يربط السلسلتين معًا.', null, null, null, 'فهم', 'وصف تركيب', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج (الشكل 6-21)'),
('essay', 2, 'يحتوي أحد شريطي جزيء DNA على الترتيب القاعدي الآتي: C-C-G-T-G-G-A-C-A-T-T-A
(أ) اكتب ترتيب القواعد على الشريط الآخر.
(ب) احسب عدد القواعد ذات الحلقتين وعدد القواعد ذات الحلقة الواحدة في القطعة كلها (الشريطين معًا)، وفسّر النتيجة في ضوء تزاوج القواعد.', null, null, null, 'تطبيق', 'كتابة الشريط المكمل وحساب', 'متوسط', 'الكتاب ص 234 — تقويم الفصل س74؛ ص 225 الشكل 6-22'),
('essay', 3, 'قطعة من جزيء DNA تحتوي على 1200 نيوكليوتيد، منها 360 نيوكليوتيدًا تحتوي على الجوانين (G).
(أ) احسب عدد النيوكليوتيدات التي تحتوي على كل من السايتوسين (C) والأدينين (A) والثايمين (T).
(ب) احسب النسبة المئوية لكل قاعدة.
(ج) فسّر القاعدة التي اعتمدت عليها في حساباتك.', null, null, null, 'تحليل', 'حساب واستنتاج', 'صعب', 'الكتاب ص 225 — أزواج القواعد المتطابقة؛ ص 236 اختبار مقنن (بيانات النيوكليوتيدات)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L4-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يتكون DNA من سلسلتين طويلتين من النيوكليوتيدات ملتفتين معًا لتشكلا بناءً حلزونيًّا؛ ولأن هذا البناء اللولبي يتكون من سلسلتين فهو يُعرف باللولب المزدوج.', '["الشريط الواحد صفة RNA لا DNA؛ فـDNA يتكون من سلسلتين.","","يتكون DNA من سلسلتين فقط لا من ثلاث سلاسل.","السلسلتان في DNA ملتفتان حلزونيًّا (لولب مزدوج) وليستا مستقيمتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.855Z"}'::jsonb),
('mcq', 2, 3, 'يحتوي كل نيوكليوتيد في DNA على سكر الديوكسي رايبوز، وهو سكر خماسي ذو خمس ذرات كربون منقوص الأكسجين.', '["الرايبوز سكر RNA؛ أما DNA فيحتوي على الديوكسي رايبوز الذي توجد فيه ذرة H بدل مجموعة OH في أحد المواقع.","الجلوكوز سكر أحادي سداسي الكربون، وليس من مكونات النيوكليوتيدات.","الفركتوز سكر أحادي سداسي الكربون، وليس من مكونات النيوكليوتيدات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.855Z"}'::jsonb),
('mcq', 3, 0, 'الجزء 1 هو الجزء الخارجي (العمود الفقري) لكل سلسلة في DNA، ويتكون من جزيئات السكر (الديوكسي رايبوز) ومجموعات الفوسفات المتعاقبة، أما القواعد النيتروجينية فتوجد داخل التركيب.', '["","القواعد النيتروجينية توجد داخل اللولب (المستطيلات المتجهة إلى الداخل)، لا في العمود الفقري الخارجي.","الأحماض الأمينية والروابط الببتيدية تكوّن البروتينات لا الأحماض النووية.","الجلسرول والأحماض الدهنية مكونات الجليسريدات الثلاثية (الليبيدات) لا الأحماض النووية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-15T02:47:48.855Z"}'::jsonb),
('mcq', 4, 2, 'تقابل كل قاعدة نيتروجينية على أحد الشريطين قاعدة على الشريط المقابل، وتتكوّن بينهما روابط هيدروجينية؛ فهذه الروابط هي التي تمسك السلسلتين معًا داخل اللولب.', '["الرابطة الببتيدية رابطة أميد بين حمضين أمينيين في البروتينات، ولا توجد بين سلسلتي DNA.","مجموعات الفوسفات في الجزء الخارجي لكل سلسلة، ولا تربط السلسلتين ببعضهما.","","السكر جزء من العمود الفقري الخارجي ولا يرتبط بقواعد السلسلة الأخرى؛ والترابط بين السلسلتين هيدروجيني بين القواعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb),
('mcq', 5, 2, 'القاعدة المقابلة في الشريط العلوي هي السايتوسين (C)، والسايتوسين يرتبط دائمًا بالجوانين في DNA؛ لذا فالقاعدة المخفية هي الجوانين (G).', '["لا تتزاوج القاعدة مع قاعدة مماثلة لها؛ فالسايتوسين يقابله الجوانين.","الأدينين يرتبط دائمًا بالثايمين لا بالسايتوسين.","","اليوراسيل لا يوجد في DNA؛ فهو من قواعد RNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb),
('mcq', 6, 0, 'لأن A يرتبط دائمًا بـT فإن نسبة T تساوي نسبة A = 30%، فيكون A + T = 60%. يتبقى 100% − 60% = 40% لـG وC معًا، وبما أن كمية G تساوي كمية C فإن G = 40% ÷ 2 = 20%.', '["","30% نسبة الأدينين نفسها (وتساوي نسبة الثايمين)، والجوانين لا يساوي الأدينين بل يساوي السايتوسين.","40% مجموع نسبتي G وC معًا؛ نُسيت القسمة على 2 مع أن G = C.","70% ناتج طرح نسبة A وحدها من 100%، دون طرح نسبة T المساوية لها ودون القسمة على 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb),
('mcq', 7, 1, 'الأدينين والجوانين قاعدتان ذواتا حلقتين، والثايمين والسايتوسين ذواتا حلقة واحدة، والأزواج في DNA هي A–T وG–C؛ لذا يتكون كل زوج من قاعدة ذات حلقتين وأخرى ذات حلقة واحدة.', '["الأدينين يرتبط دائمًا بالثايمين لا بالجوانين، فلا يتكون زوج من قاعدتين ذواتي حلقتين.","","الثايمين يرتبط دائمًا بالأدينين، والسايتوسين يرتبط دائمًا بالجوانين.","الأدينين والثايمين يرتبطان برابطتين هيدروجينيتين، أما الروابط الثلاث فبين الجوانين والسايتوسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتكون DNA من سلسلتين طويلتين من النيوكليوتيدات ملتفتين معًا حلزونيًّا، ولذلك يُعرف باللولب المزدوج. يحتوي كل نيوكليوتيد فيه على مجموعة فوسفات وسكر الديوكسي رايبوز وقاعدة نيتروجينية. تشكّل جزيئات السكر ومجموعات الفوسفات المتعاقبة في كل سلسلة الجزء الخارجي (العمود الفقري)، أما القواعد النيتروجينية فتوجد داخل التركيب، وتقابل كل قاعدة على أحد الشريطين قاعدة على الشريط المقابل (A مع T، وG مع C)، وتتكون بين القاعدتين المتقابلتين روابط هيدروجينية تمسك السلسلتين معًا.', '["سلسلتان من النيوكليوتيدات ملتفتان حلزونيًّا (لولب مزدوج)","العمود الفقري من السكر (الديوكسي رايبوز) والفوسفات المتعاقبة في الخارج","القواعد النيتروجينية في الداخل، متقابلة في أزواج A–T وG–C","روابط هيدروجينية بين القواعد المتقابلة تربط السلسلتين"]'::jsonb, '[]'::jsonb, '[{"element":"عدد السلاسل وشكل اللولب المزدوج","marks":1},{"element":"مكونات العمود الفقري الخارجي","marks":1},{"element":"موقع القواعد وتقابلها","marks":1},{"element":"الروابط الهيدروجينية بين القواعد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل للعناصر الأربعة"},{"level":"2–3 درجات","description":"وصف صحيح لعنصرين أو ثلاثة"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف DNA بأنه شريط مفرد","جعل القواعد في الخارج والسكر والفوسفات في الداخل","القول إن السلسلتين ترتبطان بروابط ببتيدية أو تساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يرتبط A دائمًا بـT، ويرتبط G دائمًا بـC؛ فترتيب الشريط الآخر: G-G-C-A-C-C-T-G-T-A-A-T.
(ب) القواعد ذات الحلقتين هي الأدينين والجوانين، وذات الحلقة الواحدة هي الثايمين والسايتوسين. في الشريط المعطى 6 قواعد ذات حلقتين (3 G و3 A) و6 ذات حلقة واحدة، وفي الشريط الآخر 6 ذات حلقتين (3 G و3 A) و6 ذات حلقة واحدة؛ فالمجموع 12 قاعدة ذات حلقتين و12 قاعدة ذات حلقة واحدة. والعددان متساويان لأن كل زوج قاعدي (A–T أو G–C) يتكون من قاعدة ذات حلقتين وقاعدة ذات حلقة واحدة، وفي القطعة 12 زوجًا.', '["الشريط الآخر G-G-C-A-C-C-T-G-T-A-A-T","12 قاعدة ذات حلقتين و12 قاعدة ذات حلقة واحدة","التفسير: كل زوج A–T أو G–C فيه قاعدة ذات حلقتين وقاعدة ذات حلقة واحدة"]'::jsonb, '["تطبيق قاعدة التزاوج على كل قاعدة بالترتيب: A مع T، وG مع C","الشريط الآخر: G-G-C-A-C-C-T-G-T-A-A-T","ذوات الحلقتين (A وG): 6 في الشريط المعطى + 6 في الشريط الآخر = 12","ذوات الحلقة الواحدة (T وC): 6 + 6 = 12","12 زوجًا × (قاعدة ذات حلقتين + قاعدة ذات حلقة واحدة) يفسّر التساوي"]'::jsonb, '[{"element":"كتابة الشريط الآخر كاملًا وصحيحًا","marks":2},{"element":"عدّ القواعد ذات الحلقتين وذات الحلقة الواحدة","marks":1},{"element":"تفسير التساوي بتزاوج القواعد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شريط صحيح وعدّ صحيح وتفسير صحيح"},{"level":"2–3 درجات","description":"شريط صحيح مع خطأ في العدّ أو نقص في التفسير"},{"level":"1 درجة","description":"تطبيق جزئي لقاعدة التزاوج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة U بدل T في الشريط الآخر","نسخ الشريط المعطى نفسه بدل الشريط المكمل","عدّ الثايمين أو السايتوسين من القواعد ذات الحلقتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لأن الجوانين يرتبط دائمًا بالسايتوسين فإن عدد C = عدد G = 360. عدد A وT معًا = 1200 − (360 + 360) = 480، وبما أن عدد A = عدد T فإن A = T = 480 ÷ 2 = 240.
(ب) G = 360 ÷ 1200 × 100 = 30%، وC = 30%، وA = 240 ÷ 1200 × 100 = 20%، وT = 20%.
(ج) في جزيء DNA تقابل كل قاعدة على أحد الشريطين قاعدة معينة على الشريط الآخر: الأدينين مع الثايمين دائمًا، والجوانين مع السايتوسين دائمًا؛ لذا تساوي كمية الأدينين كمية الثايمين، وتساوي كمية السايتوسين كمية الجوانين.', '["C = 360","A = T = 240","G = C = 30%، A = T = 20%","التفسير: تزاوج A مع T وG مع C في الشريطين"]'::jsonb, '["C = G = 360","A + T = 1200 − 720 = 480","A = T = 480 ÷ 2 = 240","نسبة G = نسبة C = 360 ÷ 1200 × 100 = 30%","نسبة A = نسبة T = 240 ÷ 1200 × 100 = 20%"]'::jsonb, '[{"element":"عدد C","marks":1},{"element":"عددا A وT","marks":2},{"element":"النسب المئوية الأربع","marks":2},{"element":"تفسير قاعدة التزاوج","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة كاملة مع تفسير صحيح"},{"level":"3–5 درجات","description":"حساب الأعداد صحيح مع خطأ في النسب أو نقص في التفسير"},{"level":"1–2 درجة","description":"تحديد C = G فقط أو ذكر قاعدة التزاوج دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل A = G أو A = C","نسيان قسمة 480 على 2","حساب النسب من 600 بدل 1200"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.856Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
