from (values
('mcq', 1, 2, 'قواعد RNA هي الأدينين والسايتوسين والجوانين واليوراسيل، ولا يوجد الثايمين أبدًا في RNA؛ فاليوراسيل هو القاعدة التي ينفرد بها RNA.', '["الثايمين يوجد في DNA ولا يوجد أبدًا في RNA، أي عكس المطلوب.","الأدينين يوجد في كل من DNA وRNA.","","الجوانين يوجد في كل من DNA وRNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('mcq', 2, 0, 'يتكون RNA من شريط واحد دون وجود روابط هيدروجينية بين القواعد، في حين يكون DNA عادة على شكل لولب ثنائي تربط الروابط الهيدروجينية سلسلتيه عن طريق قواعدهما.', '["","الشريطان المرتبطان بروابط هيدروجينية بين القواعد صفة DNA (اللولب المزدوج) لا RNA.","الروابط الببتيدية توجد في البروتينات، وRNA شريط واحد لا شريطان.","RNA يتكون من شريط واحد لا من ثلاثة أشرطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('mcq', 3, 1, 'يحتوي RNA على سكر الرايبوز، في حين يحتوي DNA على الديوكسي رايبوز الذي توجد فيه ذرة H بدل مجموعة OH في أحد المواقع. التركيب (1) تحمل فيه ذرتا الكربون السفليتان مجموعتي OH، أما (2) فيحمل OH وH؛ لذا فالتركيب (1) هو الرايبوز الموجود في RNA.', '["التركيب (2) هو الديوكسي رايبوز (منقوص الأكسجين) الموجود في DNA؛ لأن ذرة H تحل فيه محل مجموعة OH.","","كلا التركيبين يحتوي على ذرة أكسجين داخل الحلقة، فهذه الصفة لا تميّز سكر RNA.","كلا السكرين خماسي ذو خمس ذرات كربون، فهذه الصفة لا تميّز أحدهما، والتركيب (2) هو سكر DNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('mcq', 4, 3, 'تختلف القاعدتان في أن (X) تحمل مجموعة CH₃ في حين تحمل (Y) ذرة H في الموقع نفسه؛ فـ(X) هي الثايمين الموجود في DNA، و(Y) هي اليوراسيل الذي يوجد في RNA ولا يوجد في DNA.', '["(X) تحمل مجموعة CH₃ فهي الثايمين، وهو قاعدة في DNA لا في RNA.","(Y) لا تحمل مجموعة CH₃ فهي اليوراسيل لا الثايمين.","لا يوجد الثايمين (X) أبدًا في RNA؛ فـRNA يحتوي على اليوراسيل بدلًا منه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('mcq', 5, 0, 'القطعة شريط مفرد لا تقابل قواعده قواعد شريط آخر، وتحتوي على اليوراسيل (U) الذي لا يوجد في DNA أبدًا؛ لذا فهي RNA.', '["","الأدينين والجوانين يوجدان في DNA وRNA معًا فلا يدلان على DNA، ووجود U والشريط المفرد يدلان على RNA.","النتيجة صحيحة لكن الدليل خطأ؛ فالسايتوسين والجوانين يوجدان في الحمضين كليهما.","كل الأحماض النووية تتكون من نيوكليوتيدات فيها سكر وفوسفات وقاعدة، فهذا لا يميّز DNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('mcq', 6, 3, 'يختلف DNA وRNA في ثلاثة أمور: القواعد (T في DNA وU في RNA)، والسكر (الديوكسي رايبوز مقابل الرايبوز)، وعدد الأشرطة (شريطان مقابل شريط واحد). أما مجموعة الفوسفات فهي نفسها في جميع النيوكليوتيدات، فليست فرقًا بينهما.', '["هذا فرق حقيقي: DNA يحتوي على الديوكسي رايبوز وRNA يحتوي على الرايبوز.","هذا فرق حقيقي: DNA شريطان (لولب مزدوج) وRNA شريط واحد.","هذا فرق حقيقي: الثايمين في DNA فقط واليوراسيل في RNA فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('mcq', 7, 1, 'يحتوي RNA على الأدينين والسايتوسين والجوانين واليوراسيل، ولا يوجد الثايمين أبدًا في RNA.', '["هذه قواعد DNA؛ فـRNA لا يحتوي على الثايمين أبدًا.","","الثايمين لا يوجد في RNA، كما أن هذه المجموعة تخلو من السايتوسين.","الثايمين لا يوجد في RNA، كما أن هذه المجموعة تخلو من الأدينين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.857Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) RNA (حمض الرايبونيوكليك) بوليمر من النيوكليوتيدات، ويتكون كل نيوكليوتيد فيه من مجموعة فوسفات، وسكر خماسي هو الرايبوز، وقاعدة نيتروجينية هي إحدى القواعد: الأدينين (A) أو السايتوسين (C) أو الجوانين (G) أو اليوراسيل (U)، ولا يوجد فيه الثايمين أبدًا.
(ب) يرتبط سكر كل نيوكليوتيد بمجموعة فوسفات النيوكليوتيد الذي يليه، فتتكون سلسلة من السكر والفوسفات المتعاقبة، وترتبط بكل سكر قاعدة نيتروجينية تبرز من السلسلة.
(ج) يتكون RNA من شريط واحد، ولا توجد روابط هيدروجينية بين قواعده.', '["النيوكليوتيد: فوسفات + سكر خماسي + قاعدة نيتروجينية","السكر هو الرايبوز","القواعد A وC وG وU (لا ثايمين)","سلسلة سكر وفوسفات متعاقبة تبرز منها القواعد","شريط واحد دون روابط هيدروجينية بين القواعد"]'::jsonb, '[]'::jsonb, '[{"element":"أجزاء النيوكليوتيد","marks":1},{"element":"تسمية السكر (الرايبوز)","marks":1},{"element":"القواعد الأربع","marks":1},{"element":"طريقة ارتباط النيوكليوتيدات","marks":1},{"element":"شريط واحد دون روابط هيدروجينية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح كامل للعناصر الخمسة"},{"level":"3–4 درجات","description":"ثلاثة عناصر أو أربعة صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الثايمين من قواعد RNA","تسمية السكر الديوكسي رايبوز","وصف RNA بأنه شريطان تربطهما روابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.858Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) (X) هو DNA؛ لأنه يتكون من شريطين متقابلين تتزاوج قواعدهما (A مع T، وG مع C)، ويحتوي على الثايمين (T). و(Y) هو RNA؛ لأنه شريط مفرد لا تقابل قواعده قواعد شريط آخر، ويحتوي على اليوراسيل (U) بدل الثايمين.
