from (values
('mcq', 1, 'ما الوظيفة الرئيسة للحمض النووي DNA في الخلية؟', null, null, '["تزويد الخلية بالطاقة اللازمة لأنشطتها","تسريع التفاعلات الكيميائية في الخلية","تخزين المعلومات الوراثية للخلية","تكوين الأغشية المحيطة بالخلايا"]'::jsonb, 'تذكر', 'تذكر وظيفة', 'سهل', 'الكتاب ص 226 — وظيفة DNA'),
('mcq', 2, 'أين يوجد DNA بشكل رئيس في الخلية؟', null, null, '["في الغشاء الخلوي","في نواة الخلية","في السائل المحيط بالخلية","على سطح الخلية الخارجي"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 224 — تركيب الأحماض النووية؛ ص 226 وظيفة DNA؛ ص 233 تقويم الفصل س70'),
('mcq', 3, 'لماذا يُنسخ DNA قبل انقسام الخلية؟', null, null, '["ليتحول DNA إلى RNA داخل النواة قبل أن تنقسم الخلية","ليزيد عدد الأحماض الأمينية المتاحة للخلايا الجديدة","لتحصل الخلية على الطاقة التي تلزمها في أثناء الانقسام","ليحصل الجيل الجديد من الخلايا على المعلومات الوراثية نفسها"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 226 — وظيفة DNA'),
('mcq', 4, 'تخزن قواعد DNA الأربع المعلومات الوراثية بطريقة تشبه لغة مكتوبة. أي مما يأتي يوضح ذلك؟', null, null, '["يحدد عدد مجموعات الفوسفات نوع المعلومة المخزنة","يحمل تسلسل القواعد معنى خاصًّا كما يحمل تسلسل الحروف معنى الجملة","يخزن كل نوع من السكر في الجزيء صفة وراثية مختلفة","تحفظ الروابط الهيدروجينية المعلومات بحسب أطوالها"]'::jsonb, 'فهم', 'تفسير بالتشبيه', 'متوسط', 'الكتاب ص 226 — وظيفة DNA'),
('mcq', 5, 'يمثل الشكل الآتي أحد شريطي DNA في أثناء التضاعف، ويُبنى مقابله شريط جديد من نيوكليوتيدات حرة. ما ترتيب القواعد في الشريط الجديد من اليسار إلى اليمين؟', null, '[{"src":"qimg/chem22/c6-l4a-template.svg","alt":"مخطط تخطيطي لشريطين أفقيين من DNA: العلوي مكتوب بجانبه «الشريط القالب»، والسفلي مكتوب بجانبه «الشريط الجديد». يتكون كل شريط من مخمسات صفراء تتعاقب مع دوائر خضراء على خط واحد، ومن كل مخمس يتجه مستطيل يحمل حرف قاعدة نحو الداخل، وبين المستطيلات المتقابلة خطان متقطعان. قواعد الشريط القالب من اليسار إلى اليمين: A، T، C، G، G، T. أما مستطيلات الشريط الجديد الستة فتحمل كلها علامة «؟»."}]'::jsonb, '["A-T-C-G-G-T","U-A-G-C-C-A","T-A-G-C-C-A","G-C-T-A-A-C"]'::jsonb, 'تطبيق', 'تطبيق التضاعف', 'متوسط', 'الكتاب ص 226 — مختبر حل المشكلات: كيف يتضاعف DNA؟'),
('mcq', 6, 'تحتوي خلية بكتيريا إيشيريشيا كولاي (E.coli) على 4.2 × 10⁶ زوجًا من قواعد DNA، في حين تحتوي كل خلية بشرية على نحو 3 × 10⁹ زوجًا من قواعد DNA. ما النسبة المئوية التي يمثلها DNA في E.coli بالنسبة إلى DNA الخلية البشرية؟', null, null, '["0.14%","0.0014%","7.1 × 10⁴%","1.4%"]'::jsonb, 'تطبيق', 'حسابي', 'متوسط', 'الكتاب ص 234 — تقويم الفصل س77؛ ص 226 وظيفة DNA'),
('mcq', 7, 'لُوِّنت قطعة DNA أصلية باللون الأحمر، ولُوِّنت النيوكليوتيدات الحرة المستعملة في تضاعفها باللون الأزرق. كيف تكون ألوان قطعتي DNA الناتجتين؟', null, null, '["إحداهما حمراء بالكامل والأخرى زرقاء بالكامل","كل منهما زرقاء بالكامل","كل منهما مكونة من شريط أحمر وشريط أزرق","كل شريط فيهما مكوّن من أجزاء حمراء وزرقاء متناوبة"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 226 — مختبر حل المشكلات: كيف يتضاعف DNA؟ (التفكير الناقد س2)'),
('essay', 1, 'ما الوظيفة الرئيسة لـDNA في الخلية؟ وأين يوجد؟ ولماذا يُنسخ قبل انقسام الخلية؟', null, null, null, 'فهم', 'توضيح وظيفة', 'سهل', 'الكتاب ص 226 — وظيفة DNA'),
('essay', 2, 'اربط وظيفة DNA بتركيبه، موضحًا:
(أ) كيف يجعل تزاوج القواعد المتطابقة نسخ المادة الوراثية ممكنًا.
(ب) كيف يمكن لأربع قواعد فقط أن تخزن معلومات تكفي لتنوع هائل من المخلوقات الحية.', null, null, null, 'تحليل', 'ربط التركيب بالوظيفة', 'صعب', 'الكتاب ص 226 — وظيفة DNA؛ ص 227 تقويم 6-4 س21'),
('essay', 3, 'يُنسخ DNA قبل كل انقسام للخلية. توقّع كيف يمكن أن يتأثر المخلوق الحي إذا حدث خطأ في أثناء تضاعف DNA فيه، فارتبط أحد النيوكليوتيدات الحرة بقاعدة غير مكملة له. وهل تكون التأثيرات دائمة؟ وضّح إجابتك.', null, null, null, 'تحليل', 'وصف عملية وتطبيقها', 'صعب', 'الكتاب ص 226 — وظيفة DNA؛ مختبر حل المشكلات (التفكير الناقد س3)')
