('mcq', 3, 3, 'يُنسخ DNA قبل انقسام الخلية حتى يحصل الجيل الجديد من الخلايا على المعلومات الوراثية نفسها؛ فتحصل كل من الخليتين الجديدتين على مجموعة كاملة من التعليمات الوراثية.', '["النسخ قبل الانقسام يُنتج نسختين من DNA نفسه، ولا يتحول فيه DNA إلى RNA.","تضاعف DNA لا يهدف إلى زيادة الأحماض الأمينية.","DNA لا يزوّد الخلية بالطاقة؛ فوظيفته تخزين المعلومات الوراثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-15T02:47:48.858Z"}'::jsonb),
('mcq', 4, 1, 'تتخذ قواعد DNA الأربع حروفًا أبجدية في لغة تخزين المعلومات؛ فالتسلسل المحدد لهذه الحروف يمثل التعليمات الشاملة للمخلوق الحي، كما يحمل تسلسل الحروف في كلمات جملةٍ ما معنى خاصًّا.', '["مجموعة الفوسفات واحدة في جميع النيوكليوتيدات، فلا تحمل معلومات.","","السكر في DNA نوع واحد (الديوكسي رايبوز)، فلا يميّز معلومة من أخرى.","الروابط الهيدروجينية تربط الشريطين، والمعلومة في تسلسل القواعد لا في الروابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.859Z"}'::jsonb),
('mcq', 5, 2, 'ترتبط النيوكليوتيدات الحرة بالقواعد المكشوفة على الشريط القالب: الأدينين مع الثايمين، والسايتوسين مع الجوانين. فمقابل A-T-C-G-G-T يُبنى الشريط T-A-G-C-C-A.', '["هذا ترتيب الشريط القالب نفسه؛ والشريط الجديد مكمل له لا مطابق.","اليوراسيل لا يوجد في DNA؛ فالأدينين يرتبط في DNA بالثايمين.","","قوبل الأدينين بالجوانين والثايمين بالسايتوسين، وهذا تزاوج خاطئ؛ فالأزواج الصحيحة A–T وG–C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.859Z"}'::jsonb),
('mcq', 6, 0, 'النسبة المئوية = (4.2 × 10⁶ ÷ 3 × 10⁹) × 100 = 0.0014 × 100 = 0.14%؛ أي أن DNA البكتيريا جزء صغير جدًّا من DNA الخلية البشرية التي تحتوي على نحو ثلاثة مليارات زوج من القواعد.', '["","0.0014 هو ناتج القسمة فقط؛ نُسي الضرب في 100 لتحويله إلى نسبة مئوية.","قُلبت القسمة (3 × 10⁹ ÷ 4.2 × 10⁶ ≈ 714) ثم ضُرب الناتج في 100؛ والمطلوب نسبة DNA البكتيريا إلى DNA الإنسان.","خطأ في الأسس: عوملت 10⁹ كأنها 10⁸، فجاء الناتج أكبر بعشر مرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.859Z"}'::jsonb),
('mcq', 7, 2, 'في التضاعف ينفصل الشريطان الأصليان، ويُبنى مقابل كل منهما شريط جديد كامل من النيوكليوتيدات الحرة، ثم يرتبط كل شريط من الجزيء الأصلي بشريط جديد؛ فتتكون كل قطعة ناتجة من شريط أصلي أحمر وشريط جديد أزرق.', '["الشريطان الأصليان ينفصلان ولا يبقيان معًا؛ فكل شريط أصلي يرتبط بشريط جديد.","كل شريط أصلي يبقى ويُستعمل قالبًا، فلا تكون أي قطعة ناتجة جديدة بالكامل.","","يُبنى كل شريط جديد كاملًا من النيوكليوتيدات الحرة مقابل شريط أصلي كامل، فلا تتناوب الألوان داخل الشريط الواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.859Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يخزن DNA المعلومات الوراثية للخلية، ويوجد في النواة. ويُنسخ قبل انقسام الخلية حتى يحصل الجيل الجديد من الخلايا على المعلومات الوراثية نفسها؛ أي تحصل كل من الخليتين الجديدتين على مجموعة كاملة من التعليمات الوراثية.', '["الوظيفة: تخزين المعلومات الوراثية","المكان: النواة","سبب النسخ: حصول الخلايا الجديدة على المعلومات الوراثية نفسها كاملة"]'::jsonb, '[]'::jsonb, '[{"element":"الوظيفة","marks":1},{"element":"المكان","marks":1},{"element":"سبب النسخ قبل الانقسام","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة كاملة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"إجابة صحيحة لجزأين، أو سبب النسخ ناقص"},{"level":"1 درجة","description":"إجابة صحيحة لجزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل وظيفة DNA صنع الطاقة","القول إن DNA يوجد في الغشاء الخلوي","القول إن DNA يُنسخ ليتحول إلى RNA"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-15T02:47:48.860Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) سلسلتا لولب DNA تكمل إحداهما الأخرى؛ لأن الأدينين يرتبط دائمًا بالثايمين، والجوانين يرتبط دائمًا بالسايتوسين. لذا عند انفصال الشريطين يصلح كل شريط قالبًا يحدد ترتيب القواعد في الشريط الجديد المبني مقابله، فينتج جزيئان مطابقان للجزيء الأصلي، أي أن الأزواج القاعدية المتطابقة تنسخ المادة الوراثية للخلية بطريقة آلية.
(ب) تعمل القواعد الأربع عمل حروف أبجدية في لغة لتخزين المعلومات؛ فتسلسلها المحدد يحمل التعليمات الشاملة للمخلوق الحي كما يحمل تسلسل الحروف في الكلمات معنى الجملة. ويختلف تسلسل القواعد في كل نوع من المخلوقات الحية، ولأن جزيء DNA طويل جدًّا (يحتوي DNA الخلية البشرية على نحو ثلاثة مليارات زوج من القواعد مرتبة في تسلسل خاص) فإن عدد التسلسلات الممكنة هائل، وهذا يسمح بتنوع ضخم من أشكال الحياة.', '["السلسلتان متكاملتان: A–T وG–C","كل شريط قالب يحدد ترتيب الشريط الجديد فيُنسخ DNA آليًّا","القواعد كحروف أبجدية وتسلسلها يحمل المعنى","اختلاف التسلسل بين المخلوقات وطول DNA (نحو ثلاثة مليارات زوج في الإنسان) يسمحان بتنوع هائل"]'::jsonb, '[]'::jsonb, '[{"element":"تكامل السلسلتين بقاعدة التزاوج","marks":1},{"element":"دور الشريط قالبًا في النسخ","marks":2},{"element":"تشبيه القواعد بالحروف وأهمية التسلسل","marks":2},{"element":"اختلاف التسلسل وطول DNA","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"ربط كامل وصحيح في الجزأين"},{"level":"3–5 درجات","description":"ربط صحيح في جزء واحد مع ربط ناقص في الآخر"},{"level":"1–2 درجة","description":"ذكر قاعدة التزاوج أو تشبيه الحروف دون ربط بالوظيفة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المعلومات مخزنة في نوع السكر أو الفوسفات","إغفال أن كل شريط يُستعمل قالبًا","القول إن كل قاعدة تحمل صفة وراثية مستقلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.860Z"}'::jsonb),
('essay', 3, null::int, null, null, 'إذا ارتبط نيوكليوتيد حر بقاعدة غير مكملة له، تكوّن في أحد الجزيئين الناتجين شريط جديد فيه قاعدة خاطئة؛ أي تغيّر تسلسل القواعد في هذا الجزء من DNA. ولأن المعلومات الوراثية مخزنة في تسلسل القواعد (كما يحمل تسلسل الحروف معنى الجملة)، فإن التعليمات المخزنة في هذا الجزء تتغير. وDNA يحمل الخطط الرئيسة لبناء البروتينات، فقد يُصنع بروتين بتسلسل أحماض أمينية مختلف لا يؤدي وظيفته، فيتأثر عمل الخلية والمخلوق الحي.
وتكون التأثيرات دائمة في الخلايا الناتجة؛ لأن الشريط الذي يحمل الخطأ يُستعمل قالبًا في التضاعف التالي، فيُنسخ الخطأ كما تُنسخ بقية المعلومات، وتحصل كل الخلايا التي تنتج من هذه الخلية بالانقسام على التسلسل الخاطئ نفسه.', '["الخطأ يغيّر تسلسل القواعد في الجزيء الناتج","تغيّر التسلسل يعني تغيّر المعلومات (التعليمات) المخزنة","قد يُصنع بروتين بتسلسل خاطئ لا يؤدي وظيفته","التأثير دائم لأن الشريط الخاطئ يصبح قالبًا فيُنسخ الخطأ إلى الخلايا الناتجة"]'::jsonb, '[]'::jsonb, '[{"element":"تغيّر تسلسل القواعد","marks":1},{"element":"تغيّر المعلومات المخزنة","marks":1},{"element":"الأثر في البروتين ووظيفته","marks":2},{"element":"ديمومة التأثير وتعليلها بالنسخ","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"توقع منطقي كامل مع تعليل صحيح لديمومة التأثير"},{"level":"3–5 درجات","description":"توقع صحيح للأثر مع تعليل ناقص للديمومة، أو العكس"},{"level":"1–2 درجة","description":"توقع عام دون ربط بتسلسل القواعد أو بالنسخ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخطأ يختفي في التضاعف التالي","القول إن الخطأ يغيّر نوع السكر أو الفوسفات","إغفال أن الشريط الخاطئ يصبح قالبًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.860Z"}'::jsonb)
