select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يخزن DNA المعلومات الوراثية، في حين يمكّن RNA الخلايا من استخدام المعلومات الموجودة في DNA؛ إذ يُستعمل RNA لصنع البروتينات.', '["تخزين المعلومات الوراثية في النواة وظيفة DNA لا RNA.","العمود الفقري لـDNA يتكون من سكر الديوكسي رايبوز والفوسفات، وRNA جزيء مستقل عنه.","الطاقة تأتي من الكربوهيدرات والدهون لا من RNA.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.860Z"}'::jsonb),
('mcq', 2, 0, 'يُستعمل RNA لصنع بروتينات بتسلسل من الأحماض الأمينية يتقرر بترتيب القواعد النيتروجينية في RNA، وتسمى هذه التسلسلات الشفرة الوراثية.', '["","السكر في RNA نوع واحد (الرايبوز) في جميع النيوكليوتيدات، فلا يحمل معلومات.","مجموعة الفوسفات واحدة في جميع النيوكليوتيدات، فلا تحدد ترتيب الأحماض الأمينية.","RNA شريط مفرد لا توجد روابط هيدروجينية بين قواعده، والمعلومة في ترتيب القواعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('mcq', 3, 2, 'كل حمض أميني تدل عليه ثلاث قواعد؛ فعدد القواعد = 3 × 577 = 1731 قاعدة.', '["هذا عدد الأحماض الأمينية نفسه؛ أُهمل أن كل حمض أميني يحتاج إلى ثلاث قواعد.","ضُرب العدد في 2 بدل 3، والشفرة ثلاثية لا ثنائية.","","قُسم العدد على 3 بدل ضربه فيه؛ فعدد القواعد أكبر من عدد الأحماض الأمينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (51%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('mcq', 4, 1, 'عدد الأحماض الأمينية = عدد القواعد ÷ 3 = 4.50 × 10³ ÷ 3 = 1.50 × 10³ حمض أميني.', '["ضُرب عدد القواعد في 3 بدل القسمة عليه؛ فعدد الأحماض الأمينية أقل من عدد القواعد.","","قُسم العدد على 2 بدل 3، والشفرة ثلاثية.","عُدّت كل قاعدة شفرةً لحمض أميني واحد، وهذا يهمل أن الشفرة ثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('mcq', 5, 3, 'البروتينات هي الأدوات الجزيئية التي تقوم بمعظم النشاطات في الخلية، وهي تُصنع وفق الشفرة المخزنة في DNA عن طريق RNA؛ لذا يُعدّ DNA في النهاية المسؤول عن التحكم في آلاف التفاعلات الكيميائية في الخلايا.', '["DNA لا يشترك مباشرة في التفاعلات؛ بل يتحكم فيها عبر البروتينات التي تُصنع وفق شفرته.","DNA لا يزوّد التفاعلات بالطاقة؛ وظيفته تخزين المعلومات الوراثية.","الإنزيمات بروتينات تُصنع وفق شفرة DNA، والقواعد نفسها لا تعمل عمل الإنزيمات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('mcq', 6, 0, 'المعلومات الوراثية مخزنة في تسلسل قواعد DNA، وتستعمل الخلية هذا التسلسل لتكوين RNA، ثم يُستعمل RNA لصنع البروتين؛ فالاتجاه من DNA إلى RNA ثم إلى البروتين.', '["","المعلومات مخزنة أصلًا في DNA، وRNA يُكوَّن من تسلسل DNA لا العكس.","البروتين هو الناتج النهائي لا مصدر المعلومات.","البروتين يُصنع باستعمال RNA، فلا يأتي RNA بعد البروتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('mcq', 7, 2, 'مقابل T يوضع A، ومقابل A يوضع U (لأن RNA لا يحتوي على الثايمين)، ومقابل C يوضع G، ومقابل G يوضع C؛ فمقابل T-A-C-G-G-A يتكون الشريط A-U-G-C-C-U.', '["هذا ترتيب شريط DNA نفسه؛ وقواعد RNA مكملة له لا مطابقة.","هذا هو الشريط المكمل في DNA؛ لكن RNA لا يحتوي على الثايمين، فيحل U محل T.","","استُبدل T بـU في الشريط نفسه دون كتابة القواعد المكملة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يخزن DNA المعلومات الوراثية في صورة تسلسل من القواعد النيتروجينية. تستعمل الخلية تسلسل قواعد DNA لتكوين RNA بتسلسل قواعد متطابق (مكمل) له. ثم يُستعمل RNA لصنع البروتينات؛ إذ يتحدد تسلسل الأحماض الأمينية في البروتين بترتيب القواعد في RNA، وتسمى هذه التسلسلات الشفرة الوراثية، وكل ثلاث قواعد متعاقبة في RNA تدل على حمض أميني واحد. وهكذا يمكّن RNA الخلية من استخدام المعلومات المخزنة في DNA.', '["DNA يخزن المعلومات في تسلسل القواعد","يُكوَّن RNA من تسلسل قواعد DNA","ترتيب قواعد RNA يحدد تسلسل الأحماض الأمينية","الشفرة الوراثية: ثلاث قواعد لكل حمض أميني"]'::jsonb, '[]'::jsonb, '[{"element":"دور DNA","marks":1},{"element":"تكوين RNA من DNA","marks":1},{"element":"دور RNA في تحديد تسلسل الأحماض الأمينية","marks":1},{"element":"الشفرة الوراثية الثلاثية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل للعناصر الأربعة"},{"level":"2–3 درجات","description":"شرح صحيح لدوري الحمضين مع نقص"},{"level":"1 درجة","description":"ذكر دور أحد الحمضين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن DNA يصنع البروتين مباشرة","القول إن RNA يخزن المعلومات الوراثية في النواة","جعل كل قاعدة تدل على حمض أميني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عدد القواعد = 3 × 51 = 153 قاعدة.
(ب) عدد الأحماض الأمينية = 2.73 × 10⁴ ÷ 3 = 9.10 × 10³ حمض أميني.', '["153 قاعدة","9.10 × 10³ حمض أميني"]'::jsonb, '["كل حمض أميني ↔ 3 قواعد","(أ) 3 × 51 = 153 قاعدة","(ب) 2.73 × 10⁴ ÷ 3 = 9.10 × 10³ حمض أميني"]'::jsonb, '[{"element":"حساب (أ)","marks":2},{"element":"حساب (ب)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان مع الخطوات"},{"level":"2–3 درجات","description":"حساب واحد صحيح، أو الحسابان صحيحان دون خطوات"},{"level":"1 درجة","description":"كتابة العلاقة الثلاثية دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على 3 في (أ) والضرب في (ب)","إهمال الشفرة الثلاثية وجعل العدد نفسه","كتابة 9100 بأرقام معنوية غير مناسبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (51%)"}],"at":"2026-11-15T02:47:48.861Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تستعمل الخلية تسلسل قواعد DNA لتكوين RNA بتسلسل مكمل، فإذا كان تسلسل DNA خاطئًا انتقل الخطأ إلى RNA. ولأن ترتيب القواعد في RNA يحدد ترتيب الأحماض الأمينية في البروتين (كل ثلاث قواعد لحمض أميني)، فقد يدخل حمض أميني غير صحيح في السلسلة أو يتغير تسلسل الأحماض الأمينية. ويتغير بذلك تركيب البروتين، فقد يعجز عن أداء وظيفته، كأن يفقد إنزيم قدرته على تحفيز تفاعل معين. ولأن البروتينات تقوم بمعظم نشاطات الخلية، فقد يتأثر عمل الخلية والمخلوق الحي.', '["الخطأ ينتقل إلى RNA","يتغير تسلسل الأحماض الأمينية في البروتين","يتغير تركيب البروتين فقد يفقد وظيفته","تتأثر نشاطات الخلية لأن البروتينات تقوم بمعظمها"]'::jsonb, '[]'::jsonb, '[{"element":"انتقال الخطأ إلى RNA","marks":1},{"element":"تغير تسلسل الأحماض الأمينية","marks":2},{"element":"تغير تركيب البروتين ووظيفته","marks":2},{"element":"الأثر في الخلية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تتبع كامل منطقي من DNA إلى وظيفة البروتين"},{"level":"3–5 درجات","description":"تتبع صحيح ناقص حلقة أو حلقتين"},{"level":"1–2 درجة","description":"توقع عام (البروتين يتغير) دون تتبع"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخطأ لا يؤثر لأن RNA يصححه","إغفال دور RNA في نقل الخطأ","الخلط بين تسلسل القواعد وعدد الروابط الهيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C6-L4-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L4-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الأجزاء الثلاثة التي يتكون منها النيوكليوتيد؟', null, null, '["حمض أميني وسكر خماسي ومجموعة فوسفات","مجموعة فوسفات وسكر خماسي وقاعدة نيتروجينية","جلسرول وحمض دهني ومجموعة فوسفات","قاعدة نيتروجينية وسكر سداسي ومجموعة أمين"]'::jsonb, 'تذكر', 'تذكر مكونات', 'سهل', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('mcq', 2, 'يمثل الشكل الآتي تركيب نيوكليوتيد. ماذا يمثل الجزء المشار إليه بالحرف B؟', null, '[{"src":"qimg/chem22/c6-l4a-nt-deoxy-c.svg","alt":"صيغة بنائية لنيوكليوتيد مع ثلاثة أحرف تشير إلى أجزائه. على اليسار ذرة فوسفور P ترتبط بذرة O برابطة ثنائية (إلى الأعلى)، وبمجموعتي OH (إلى اليسار وإلى الأسفل)، وبذرة O (إلى اليمين) ترتبط بدورها بمجموعة CH₂؛ ويشير الحرف A إلى الجزء الذي يضم ذرة P. ترتبط مجموعة CH₂ بحلقة خماسية تحتوي على ذرة أكسجين O وأربع ذرات كربون، تحمل إحدى ذرتي الكربون السفليتين مجموعة OH والأخرى ذرة H؛ ويشير الحرف B إلى هذه الحلقة الخماسية. ترتبط ذرة الكربون اليمنى في الحلقة الخماسية بذرة N في حلقة سداسية تحتوي على ذرتي نيتروجين N، وتحمل ذرة O برابطة ثنائية ومجموعة NH₂ وذرتي H، وفي الحلقة رابطتان ثنائيتان؛ ويشير الحرف C إلى هذه الحلقة السداسية."}]'::jsonb, '["مجموعة فوسفات","قاعدة نيتروجينية","سكر خماسي","حمض أميني"]'::jsonb, 'تذكر', 'تحديد جزء في شكل', 'سهل', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('mcq', 3, 'في الشكل الآتي لنيوكليوتيد، أي الأجزاء المشار إليها بالأحرف يكون واحدًا لا يتغير في جميع النيوكليوتيدات؟', null, '[{"src":"qimg/chem22/c6-l4a-nt-deoxy-c.svg","alt":"صيغة بنائية لنيوكليوتيد مع ثلاثة أحرف تشير إلى أجزائه. على اليسار ذرة فوسفور P ترتبط بذرة O برابطة ثنائية (إلى الأعلى)، وبمجموعتي OH (إلى اليسار وإلى الأسفل)، وبذرة O (إلى اليمين) ترتبط بدورها بمجموعة CH₂؛ ويشير الحرف A إلى الجزء الذي يضم ذرة P. ترتبط مجموعة CH₂ بحلقة خماسية تحتوي على ذرة أكسجين O وأربع ذرات كربون، تحمل إحدى ذرتي الكربون السفليتين مجموعة OH والأخرى ذرة H؛ ويشير الحرف B إلى هذه الحلقة الخماسية. ترتبط ذرة الكربون اليمنى في الحلقة الخماسية بذرة N في حلقة سداسية تحتوي على ذرتي نيتروجين N، وتحمل ذرة O برابطة ثنائية ومجموعة NH₂ وذرتي H، وفي الحلقة رابطتان ثنائيتان؛ ويشير الحرف C إلى هذه الحلقة السداسية."}]'::jsonb, '["الجزء A","الجزء B","الجزء C","الجزآن B وC معًا"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('mcq', 4, 'كم ذرة كربون في السكر الأحادي الموجود في النيوكليوتيد؟', null, null, '["3","4","6","5"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('mcq', 5, 'الحمض النووي بوليمر حيوي. ما اسم وحدة البناء التي يتكون منها، وكم جزءًا فيها؟', null, null, '["النيوكليوتيد، وله ثلاثة أجزاء","النيوكليوتيد، وله جزآن فقط","الحمض الأميني، وله ثلاثة أجزاء","السكر الأحادي، وله جزآن فقط"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'متوسط', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('mcq', 6, 'كيف ترتبط النيوكليوتيدات بعضها ببعض لتكوين سلسلة الحمض النووي؟', null, null, '["ترتبط القواعد النيتروجينية في السلسلة بعضها ببعض بروابط ببتيدية","ترتبط مجموعات الفوسفات بعضها ببعض مباشرة","يرتبط سكر كل نيوكليوتيد بسكر النيوكليوتيد الذي يليه","يرتبط سكر كل نيوكليوتيد بمجموعة فوسفات النيوكليوتيد الذي يليه"]'::jsonb, 'فهم', 'وصف ترابط', 'متوسط', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('mcq', 7, 'شريط من RNA يتكون من 120 نيوكليوتيدًا. ما عدد جزيئات السكر ومجموعات الفوسفات والقواعد النيتروجينية فيه؟', null, null, '["120 سكر رايبوز، و60 مجموعة فوسفات، و120 قاعدة","120 سكر رايبوز، و120 مجموعة فوسفات، و120 قاعدة","40 سكر رايبوز، و40 مجموعة فوسفات، و40 قاعدة","120 سكر ديوكسي رايبوز، و120 مجموعة فوسفات، و120 قاعدة"]'::jsonb, 'تطبيق', 'تطبيق', 'صعب', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)؛ ص 227 RNA'),
('essay', 1, 'حدّد الأجزاء الثلاثة التي يتكون منها النيوكليوتيد، ثم وضّح كيف ترتبط النيوكليوتيدات لتكوين سلسلة حمض نووي.', null, null, null, 'تذكر', 'تحديد ووصف', 'متوسط', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)'),
('essay', 2, 'يمثل الشكل الآتي تركيب نيوكليوتيد.
(أ) ماذا تمثل الأجزاء المشار إليها بالأحرف X وY وZ؟
(ب) إلى أي الحمضين النوويين DNA أم RNA ينتمي هذا النيوكليوتيد؟ اذكر دليلين من الشكل.', null, '[{"src":"qimg/chem22/c6-l4a-nt-ribo-u.svg","alt":"صيغة بنائية لنيوكليوتيد مع ثلاثة أحرف تشير إلى أجزائه. على اليسار ذرة فوسفور P ترتبط بذرة O برابطة ثنائية (إلى الأعلى)، وبمجموعتي OH، وبذرة O (إلى اليمين) ترتبط بدورها بمجموعة CH₂؛ ويشير الحرف X إلى الجزء الذي يضم ذرة P. ترتبط مجموعة CH₂ بحلقة خماسية تحتوي على ذرة أكسجين O وأربع ذرات كربون، وتحمل كل من ذرتي الكربون السفليتين مجموعة OH؛ ويشير الحرف Y إلى هذه الحلقة الخماسية. ترتبط ذرة الكربون اليمنى في الحلقة الخماسية بذرة N في حلقة سداسية تحتوي على ذرتي نيتروجين N (تحمل إحداهما ذرة H)، وترتبط بذرتي كربون منها ذرتا O برابطتين ثنائيتين، وفيها رابطة ثنائية بين ذرتي كربون تحمل كل منهما ذرة H؛ ويشير الحرف Z إلى هذه الحلقة السداسية."}]'::jsonb, null, 'فهم', 'تفسير شكل وتصنيف', 'صعب', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)؛ ص 227 الشكل 6-23؛ ص 237 اختبار مقنن س11'),
('essay', 3, 'قارن بين نيوكليوتيدات DNA ونيوكليوتيدات RNA من حيث كل جزء من أجزائها الثلاثة، ثم حدّد الجزء الذي يجعل الأحماض النووية أحماضًا، علمًا بأن الحمض مادة تمنح أيون الهيدروجين H⁺، وأن مجموعات OH المرتبطة بذرة الفوسفور تمنح H⁺ بسهولة بخلاف مجموعات OH المرتبطة بذرات الكربون في السكر.', null, null, null, 'تحليل', 'مقارنة وتحديد', 'صعب', 'الكتاب ص 224 — تركيب الأحماض النووية (الشكل 6-20)؛ ص 227 RNA؛ تقويم 6-4 س20 وس22')
