from (values
('mcq', 1, 1, 'لكل نيوكليوتيد ثلاثة أجزاء: مجموعة فوسفات غير عضوية، وسكر أحادي ذو خمس ذرات كربون، وتركيب يحتوي على نيتروجين يسمى قاعدة نيتروجينية.', '["الحمض الأميني وحدة بناء البروتينات، ولا يدخل في تركيب النيوكليوتيد.","","الجلسرول والحمض الدهني والفوسفات من مكونات الليبيدات الفوسفورية لا النيوكليوتيدات.","سكر النيوكليوتيد خماسي لا سداسي، ومجموعة الأمين ليست أحد أجزائه الثلاثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('mcq', 2, 2, 'الجزء B حلقة خماسية تحتوي على ذرة أكسجين وأربع ذرات كربون، وترتبط بمجموعة CH₂؛ فهو السكر الخماسي الذي يرتبط بمجموعة الفوسفات من جهة وبالقاعدة النيتروجينية من جهة أخرى.', '["مجموعة الفوسفات هي الجزء A الذي يحتوي على ذرة الفوسفور P.","القاعدة النيتروجينية هي الجزء C، وهي الحلقة السداسية التي تحتوي على ذرتي نيتروجين.","","لا يدخل الحمض الأميني في تركيب النيوكليوتيد؛ فهو وحدة بناء البروتينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('mcq', 3, 0, 'الجزء A هو مجموعة الفوسفات، وهي نفسها في جميع النيوكليوتيدات، أما السكر (B) والقاعدة النيتروجينية (C) فيختلفان؛ فالسكر رايبوز أو ديوكسي رايبوز، والقاعدة إحدى القواعد A أو T أو C أو G أو U.', '["","الجزء B هو السكر الخماسي، وهو يختلف بين الرايبوز في RNA والديوكسي رايبوز في DNA.","الجزء C هو القاعدة النيتروجينية، وهي تختلف من نيوكليوتيد إلى آخر.","السكر والقاعدة هما الجزآن اللذان يختلفان بين النيوكليوتيدات، لا اللذان يبقيان ثابتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('mcq', 4, 3, 'السكر في النيوكليوتيد سكر أحادي خماسي (بنتوز) يتكون من 5 ذرات كربون.', '["3 ذرات أقل من عدد ذرات كربون سكر النيوكليوتيد؛ فهو سكر خماسي (بنتوز).","الحلقة الخماسية للسكر فيها 4 ذرات كربون وذرة أكسجين، لكن ذرة الكربون الخامسة في مجموعة CH₂ خارج الحلقة.","6 ذرات كربون عدد كربون الجلوكوز والفركتوز (سكريات سداسية)، وسكر النيوكليوتيد خماسي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('mcq', 5, 0, 'تسمى وحدة البناء الأساسية للحمض النووي النيوكليوتيد، ولكل نيوكليوتيد ثلاثة أجزاء: مجموعة فوسفات، وسكر خماسي، وقاعدة نيتروجينية.', '["","الوحدة هي النيوكليوتيد فعلًا، لكن له ثلاثة أجزاء لا جزآن.","الحمض الأميني وحدة بناء البروتينات لا الأحماض النووية.","السكر الأحادي جزء واحد من النيوكليوتيد، ووحدة بناء الكربوهيدرات المعقدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('mcq', 6, 3, 'يرتبط السكر في أحد النيوكليوتيدات بمجموعة فوسفات نيوكليوتيد آخر، وهكذا تتكون سلسلة من السكر والفوسفات المتعاقبة، ويرتبط بكل سكر قاعدة نيتروجينية تبرز من السلسلة.', '["القواعد تبرز من السلسلة ولا يرتبط بعضها ببعض فيها، والرابطة الببتيدية خاصة بالبروتينات.","مجموعات الفوسفات لا يرتبط بعضها ببعض؛ بل تتعاقب مع السكر.","السكريات لا يرتبط بعضها ببعض مباشرة؛ فبين كل سكرين مجموعة فوسفات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('mcq', 7, 1, 'يحتوي كل نيوكليوتيد على سكر واحد ومجموعة فوسفات واحدة وقاعدة نيتروجينية واحدة، وسكر RNA هو الرايبوز؛ لذا يحتوي الشريط على 120 سكر رايبوز و120 مجموعة فوسفات و120 قاعدة.', '["لكل نيوكليوتيد مجموعة فوسفات واحدة، فعددها يساوي عدد النيوكليوتيدات لا نصفه.","","قُسم العدد على 3 خلطًا بين الأجزاء الثلاثة وعدد النيوكليوتيدات؛ فكل نيوكليوتيد يحتوي على جزء واحد من كل نوع.","الأعداد صحيحة لكن سكر RNA هو الرايبوز لا الديوكسي رايبوز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.862Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتكون النيوكليوتيد من ثلاثة أجزاء: مجموعة فوسفات غير عضوية، وسكر أحادي ذو خمس ذرات كربون (سكر خماسي)، وقاعدة نيتروجينية (تركيب يحتوي على النيتروجين). وترتبط النيوكليوتيدات بأن يرتبط سكر أحد النيوكليوتيدات بمجموعة فوسفات نيوكليوتيد آخر، وهكذا تتكون سلسلة من السكر والفوسفات المتعاقبة، ويرتبط بكل سكر قاعدة نيتروجينية تبرز من السلسلة، فتشبه القواعد درجات السلم.', '["مجموعة فوسفات","سكر خماسي","قاعدة نيتروجينية","ارتباط سكر نيوكليوتيد بفوسفات النيوكليوتيد التالي","سلسلة سكر وفوسفات متعاقبة تبرز منها القواعد"]'::jsonb, '[]'::jsonb, '[{"element":"الأجزاء الثلاثة","marks":3},{"element":"ارتباط السكر بفوسفات النيوكليوتيد التالي","marks":1},{"element":"سلسلة متعاقبة تبرز منها القواعد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة وطريقة الارتباط كاملة"},{"level":"3–4 درجات","description":"الأجزاء الثلاثة مع وصف ناقص للارتباط"},{"level":"1–2 درجة","description":"ذكر جزء أو جزأين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر سكر سداسي بدل الخماسي","ذكر الحمض الأميني جزءًا من النيوكليوتيد","القول إن القواعد ترتبط ببعضها لتكوين السلسلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-15T02:47:48.863Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) X: مجموعة فوسفات (تحتوي على ذرة الفوسفور P). Y: سكر خماسي (حلقة خماسية فيها ذرة أكسجين وترتبط بمجموعة CH₂). Z: قاعدة نيتروجينية (حلقة سداسية تحتوي على ذرتي نيتروجين).
(ب) ينتمي إلى RNA؛ لأن السكر Y تحمل فيه كل من ذرتي الكربون السفليتين مجموعة OH، فهو الرايبوز لا الديوكسي رايبوز الذي توجد فيه ذرة H بدل إحدى مجموعتي OH. ولأن القاعدة Z لا تحمل مجموعة CH₃، بل ذرة H، فهي اليوراسيل الذي يوجد في RNA ولا يوجد في DNA.', '["X مجموعة فوسفات","Y سكر خماسي","Z قاعدة نيتروجينية","ينتمي إلى RNA","الدليلان: السكر رايبوز (OH في الموقعين)، والقاعدة يوراسيل"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد X وY وZ","marks":3},{"element":"الحكم بأنه RNA","marks":1},{"element":"الدليلان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد الأجزاء الثلاثة والحكم مع الدليلين"},{"level":"3–5 درجات","description":"تحديد الأجزاء صحيح مع حكم ناقص الأدلة"},{"level":"1–2 درجة","description":"تحديد جزء أو جزأين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين السكر والقاعدة","الحكم بأنه DNA لوجود الفوسفات","عدّ القاعدة ثايمين دون ملاحظة غياب CH₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-15T02:47:48.863Z"}'::jsonb),
('essay', 3, null::int, null, null, 'مجموعة الفوسفات: واحدة في نيوكليوتيدات DNA وRNA.
السكر الخماسي: الديوكسي رايبوز في DNA، والرايبوز في RNA؛ ويحمل الديوكسي رايبوز ذرة H بدل مجموعة OH في أحد المواقع.
القاعدة النيتروجينية: في DNA إحدى القواعد A أو T أو C أو G، وفي RNA إحدى القواعد A أو U أو C أو G؛ فالثايمين في DNA فقط واليوراسيل في RNA فقط.
الجزء الذي يجعلها أحماضًا: مجموعة الفوسفات؛ لاحتوائها على مجموعة OH مرتبطة بذرة الفوسفور يمكن أن تمنح أيون الهيدروجين H⁺.', '["الفوسفات نفسها في الحمضين","السكر: ديوكسي رايبوز (DNA) ورايبوز (RNA)","القواعد: T في DNA وU في RNA، وA وC وG مشتركة","مجموعة الفوسفات هي الجزء الحمضي"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة الفوسفات","marks":1},{"element":"مقارنة السكر","marks":2},{"element":"مقارنة القواعد","marks":2},{"element":"تحديد الجزء الحمضي","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة للأجزاء الثلاثة مع تحديد الجزء الحمضي"},{"level":"3–5 درجات","description":"مقارنة صحيحة لجزأين أو ثلاثة دون تحديد الجزء الحمضي"},{"level":"1–2 درجة","description":"مقارنة جزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفوسفات تختلف بين الحمضين","عكس السكرين بين DNA وRNA","عدّ القاعدة النيتروجينية هي الجزء الحمضي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-15T02:47:48.863Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C6-L4-O05') and x.type = v.type and x.number = v.number
