insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L4-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل الشكل الآتي زوجًا من القواعد النيتروجينية في DNA. أي زوج من القواعد يمثله الشكل؟', null, '[{"src":"qimg/chem22/c6-l4b-pair3.svg","alt":"مخطط تخطيطي لزوج من القواعد النيتروجينية في DNA. على اليسار قاعدة ذات حلقة واحدة (شكل سداسي برتقالي فاتح) يتصل بها خط مائل إلى خماسي أصفر صغير مكتوب تحته «ديوكسي رايبوز». على اليمين قاعدة ذات حلقتين ملتحمتين (شكل سداسي أزرق فاتح ملتصق به شكل خماسي من جهة اليمين) يتصل بها من أسفل خماسي أصفر صغير مكتوب تحته «ديوكسي رايبوز». بين القاعدتين ثلاثة خطوط حمراء متقطعة أفقية متوازية تصل الحلقة الواحدة بالحلقتين. وفي أعلى الشكل مفتاح يبين أن الخط الأحمر المتقطع يمثل «رابطة هيدروجينية». لا تظهر على القاعدتين حروف أو أسماء."}]'::jsonb, '["الأدينين مع الثايمين (A–T)","الجوانين مع السايتوسين (G–C)","الأدينين مع السايتوسين (A–C)","الجوانين مع الثايمين (G–T)"]'::jsonb, 'تطبيق', 'تفسير شكل', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج (الشكل 6-22)'),
('mcq', 2, 'لماذا تتزاوج القواعد النيتروجينية في DNA دائمًا بطريقة معينة (A مع T، وG مع C)؟', null, null, '["لأن ترتيب المجموعات الوظيفية في كل زوج يتيح تكوين أكبر عدد من الروابط الهيدروجينية بينهما","لأن القاعدتين في كل زوج ترتبطان بروابط تساهمية قوية لا تتكون بين غيرهما","لأن القاعدتين المتزاوجتين متماثلتان في عدد الحلقات وفي حجم الجزيء","لأن كل قاعدة ترتبط بمجموعة الفوسفات في الشريط المقابل لها مباشرة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 3, 'يحتوي أحد شريطي قطعة من DNA على تتابع القواعد الآتي: A-G-G-C-T-A-T-C. ما تتابع القواعد في الشريط المكمل له؟', null, null, '["U-C-C-G-A-U-A-G","A-G-G-C-T-A-T-C","G-A-A-T-C-G-C-T","T-C-C-G-A-T-A-G"]'::jsonb, 'تطبيق', 'كتابة الشريط المكمل', 'سهل', 'الكتاب ص 225، ص 234 — تزاوج القواعد (س74)'),
('mcq', 4, 'يحتوي أحد شريطي قطعة من DNA على 12 قاعدة أدينين (A)، و8 قواعد ثايمين (T)، و15 قاعدة جوانين (G)، و5 قواعد سايتوسين (C). كم قاعدة جوانين (G) في الشريط المكمل له؟', null, null, '["15","8","5","12"]'::jsonb, 'تطبيق', 'حساب بقاعدة التزاوج', 'متوسط', 'الكتاب ص 225 — تزاوج القواعد'),
('mcq', 5, 'يمثل الشكل الآتي قطعة من DNA مرقمة أزواج قواعدها. أي الأزواج المرقمة لا يتفق مع قاعدة تزاوج القواعد؟', null, '[{"src":"qimg/chem22/c6-l4b-mismatch.svg","alt":"مخطط تخطيطي لقطعة من DNA مرسومة أفقيًا: شريطان علوي وسفلي، يتكون كل منهما من مخمسات صفراء تتعاقب مع دوائر خضراء على خط واحد، ومن كل مخمس يتجه نحو الداخل مستطيل يحمل حرف قاعدة، وبين كل مستطيلين متقابلين خطان متقطعان قصيران. الأزواج مرقمة أسفل الشكل من اليسار إلى اليمين، وفي كل زوج قاعدة الشريط العلوي ثم قاعدة الشريط السفلي: (1) G مقابل C، (2) A مقابل T، (3) C مقابل G، (4) T مقابل C، (5) C مقابل G، (6) A مقابل T."}]'::jsonb, '["الزوج (2)","الزوج (4)","الزوج (5)","الزوج (1)"]'::jsonb, 'تطبيق', 'تفسير شكل', 'متوسط', 'الكتاب ص 225 — تزاوج القواعد'),
('mcq', 6, 'في جزيء DNA ذي الشريطين، ما قيمة النسبة: (عدد قواعد A + عدد قواعد G) ÷ (عدد قواعد T + عدد قواعد C)؟', null, null, '["تساوي 1 دائمًا","تختلف باختلاف المخلوق الحي","تساوي 2 دائمًا","تساوي 0.5 دائمًا"]'::jsonb, 'تحليل', 'استنتاج من قاعدة التزاوج', 'صعب', 'الكتاب ص 225، ص 234 — تزاوج القواعد (س73)'),
('mcq', 7, 'قطعتان من DNA في كل منهما 10 أزواج من القواعد: القطعة (X) فيها 7 أزواج G–C والباقي A–T، والقطعة (Y) فيها 3 أزواج G–C والباقي A–T. أي العبارات الآتية صحيحة عن عدد الروابط الهيدروجينية بين شريطي كل منهما؟', null, null, '["في القطعة (Y) روابط هيدروجينية أكثر من (X) بـ 4 روابط","في القطعتين العدد نفسه من الروابط الهيدروجينية (20 رابطة)","في القطعة (X) روابط هيدروجينية أكثر من (Y) بـ 12 رابطة","في القطعة (X) روابط هيدروجينية أكثر من (Y) بـ 4 روابط"]'::jsonb, 'تطبيق', 'حساب الروابط الهيدروجينية', 'صعب', 'الكتاب ص 225 — الشكل 6-22'),
('essay', 1, 'وضّح قاعدة تزاوج القواعد النيتروجينية في DNA، مبينًا: (أ) القاعدة التي ترتبط بها كل من القواعد الأربع، (ب) عدد الحلقات في كل قاعدة، (ج) عدد الروابط الهيدروجينية في كل زوج، (د) سبب تزاوجها بهذه الطريقة، (هـ) ما يترتب على ذلك بالنسبة لكميات القواعد في جزيء DNA.', null, null, null, 'فهم', 'توضيح قاعدة', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج (الشكل 6-22)'),
('essay', 2, 'يحتوي أحد شريطي قطعة من DNA على 30 قاعدة نيتروجينية: 10 أدينين (A)، و6 ثايمين (T)، و9 جوانين (G)، و5 سايتوسين (C).
(أ) اكتب عدد كل قاعدة في الشريط المكمل.
(ب) احسب العدد الكلي لكل قاعدة في القطعة (الشريطين معًا)، وبيّن أن النتيجة تتفق مع قاعدة التزاوج.
(ج) احسب عدد الروابط الهيدروجينية بين الشريطين.', null, null, null, 'تطبيق', 'حساب بقاعدة التزاوج', 'متوسط', 'الكتاب ص 225 — تزاوج القواعد (الشكل 6-22)'),
('essay', 3, 'طُلب من طالبين كتابة الشريط المكمل لشريط DNA تتابعه: T-A-C-G-G-A-T-C، ثم حساب عدد الروابط الهيدروجينية بين الشريطين.
• الطالب الأول كتب: A-U-G-C-C-U-A-G.
• الطالب الثاني كتب: A-T-G-C-C-T-A-G، وقال: «عدد الروابط الهيدروجينية 16 رابطة؛ لأن في القطعة 8 أزواج وكل زوج يرتبط برابطتين».
قوّم إجابة كل طالب، وصحّح الخطأ إن وُجد.', null, null, null, 'تقويم', 'تقويم إجابة وتصحيحها', 'صعب', 'الكتاب ص 225، ص 227 — تزاوج القواعد وقواعد RNA')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
