from (values
('mcq', 1, 1, 'في الشكل قاعدة ذات حلقتين تقابل قاعدة ذات حلقة واحدة، ويرتبطان بثلاث روابط هيدروجينية. والزوج الوحيد الذي يرتبط بثلاث روابط هيدروجينية هو الجوانين (حلقتان) مع السايتوسين (حلقة واحدة)؛ لذا يمثل الشكل الزوج G–C.', '["يرتبط A مع T برابطتين هيدروجينيتين فقط، والشكل يبيّن ثلاث روابط.","","A وC لا يكوّنان زوجًا في DNA؛ فالأدينين يرتبط دائمًا بالثايمين.","G وT لا يكوّنان زوجًا في DNA؛ فالجوانين يرتبط دائمًا بالسايتوسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.863Z"}'::jsonb),
('mcq', 2, 0, 'لكل قاعدة نيتروجينية ترتيب فريد من المجموعات الوظيفية القادرة على تكوين روابط هيدروجينية، فتتزاوج القواعد دائمًا بالطريقة التي يتكون فيها أكبر عدد من الروابط الهيدروجينية: A مع T، وG مع C.', '["","القواعد المتقابلة ترتبط بروابط هيدروجينية لا بروابط تساهمية.","كل زوج يتكون من قاعدة ذات حلقتين (A أو G) وقاعدة ذات حلقة واحدة (T أو C)، فهما غير متماثلتين في عدد الحلقات.","القواعد ترتبط بالسكر في شريطها، وتتجه نحو داخل اللولب لتقابل قاعدة أخرى لا مجموعة فوسفات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-15T02:47:48.863Z"}'::jsonb),
('mcq', 3, 3, 'بتطبيق قاعدة التزاوج على كل قاعدة بالترتيب (A مع T، وG مع C): A→T، G→C، G→C، C→G، T→A، A→T، T→A، C→G؛ فيكون الشريط المكمل T-C-C-G-A-T-A-G.', '["وُضع اليوراسيل U مقابل الأدينين، واليوراسيل لا يوجد في DNA؛ فمقابل A في DNA يكون T.","هذا تكرار للشريط المعطى نفسه، لا الشريط المكمل له.","زُوِّجت القاعدتان ذواتا الحلقتين معًا (A مع G) وذواتا الحلقة الواحدة معًا (T مع C)، وهذا مخالف لقاعدة التزاوج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-15T02:47:48.864Z"}'::jsonb),
('mcq', 4, 2, 'كل قاعدة G في الشريط المكمل تقابل قاعدة C في الشريط المعطى؛ لأن الجوانين يرتبط دائمًا بالسايتوسين. وفي الشريط المعطى 5 قواعد C، إذن في الشريط المكمل 5 قواعد G.', '["15 هو عدد قواعد G في الشريط المعطى؛ وهذه تقابلها قواعد C في الشريط المكمل لا قواعد G.","8 هو عدد قواعد T في الشريط المعطى، وهي تقابلها قواعد A لا G.","","12 هو عدد قواعد A في الشريط المعطى، وهي تقابلها قواعد T لا G."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-15T02:47:48.864Z"}'::jsonb),
('mcq', 5, 1, 'حسب قاعدة التزاوج يقابل A دائمًا T، ويقابل G دائمًا C. الأزواج (1) G–C و(2) A–T و(3) C–G و(5) C–G و(6) A–T صحيحة، أما الزوج (4) ففيه الثايمين T مقابل السايتوسين C، وهذا لا يتفق مع القاعدة؛ إذ يجب أن يقابل T الأدينينَ A.', '["الزوج (2) هو A مقابل T، وهو زوج صحيح.","","الزوج (5) هو C مقابل G، وهو زوج صحيح.","الزوج (1) هو G مقابل C، وهو زوج صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-15T02:47:48.864Z"}'::jsonb),
('mcq', 6, 0, 'في DNA ذي الشريطين يقابل كل A قاعدة T، ويقابل كل G قاعدة C؛ فعدد A = عدد T، وعدد G = عدد C. إذن (A + G) = (T + C)، والنسبة بينهما تساوي 1 دائمًا مهما كان المخلوق.', '["","النسب المئوية لكل قاعدة تختلف بين المخلوقات، لكن تساوي A مع T وG مع C يجعل هذه النسبة 1 في كل DNA ذي شريطين.","قيمة 2 تنتج من توهم أن عدد القواعد ذات الحلقتين ضعف عدد القواعد ذات الحلقة الواحدة، مع أن كل زوج يحتوي على واحدة من كل نوع.","قيمة 0.5 تنتج من قلب المنطق السابق؛ وكل زوج فيه قاعدة واحدة من A أو G تقابلها قاعدة واحدة من T أو C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-15T02:47:48.864Z"}'::jsonb),
('mcq', 7, 3, 'يرتبط كل زوج G–C بثلاث روابط هيدروجينية، وكل زوج A–T برابطتين. القطعة (X): 7 × 3 + 3 × 2 = 21 + 6 = 27 رابطة. القطعة (Y): 3 × 3 + 7 × 2 = 9 + 14 = 23 رابطة. الفرق = 27 − 23 = 4؛ أي أن في القطعة (X) روابط هيدروجينية أكثر من (Y) بـ 4 روابط.', '["عُكست النتيجة؛ القطعة الغنية بأزواج G–C (وهي X) هي التي فيها روابط أكثر.","افتُرض أن كل زوج يرتبط برابطتين، مع أن أزواج G–C ترتبط بثلاث روابط.","حُسبت روابط أزواج G–C فقط (21 − 9 = 12) وأُهملت روابط أزواج A–T؛ والفرق الصحيح 27 − 23 = 4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.864Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) يرتبط الأدينين (A) دائمًا بالثايمين (T)، ويرتبط الجوانين (G) دائمًا بالسايتوسين (C)، ويُسمى الزوجان A–T وG–C أزواجًا قاعدية متطابقة.
(ب) الأدينين والجوانين ذوا حلقتين، والثايمين والسايتوسين ذوا حلقة واحدة؛ فكل زوج يتكون من قاعدة ذات حلقتين وقاعدة ذات حلقة واحدة.
(ج) يرتبط A مع T برابطتين هيدروجينيتين، ويرتبط G مع C بثلاث روابط هيدروجينية.
(د) لكل قاعدة ترتيب فريد من المجموعات الوظيفية التي تستطيع تكوين روابط هيدروجينية، فتتزاوج القواعد دائمًا بالطريقة التي يتكون فيها أكبر عدد من الروابط الهيدروجينية.
(هـ) تتساوى كمية الأدينين مع كمية الثايمين، وكمية السايتوسين مع كمية الجوانين في جزيء DNA.', '["A مع T، وG مع C","A وG ذوا حلقتين، وT وC ذوا حلقة واحدة","A–T رابطتان، وG–C ثلاث روابط هيدروجينية","ترتيب المجموعات الوظيفية يتيح أكبر عدد من الروابط الهيدروجينية","كمية A = كمية T، وكمية G = كمية C"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الأزواج","marks":1},{"element":"عدد الحلقات","marks":1},{"element":"عدد الروابط الهيدروجينية","marks":1},{"element":"سبب التزاوج","marks":1},{"element":"تساوي الكميات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"العناصر الخمسة صحيحة"},{"level":"3–4 درجات","description":"الأزواج والروابط صحيحة مع نقص في السبب أو الحلقات أو الكميات"},{"level":"1–2 درجة","description":"تحديد الأزواج فقط أو مع عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس عدد الروابط (ثلاث لـ A–T ورابطتان لـ G–C)","القول إن A وT ذوا حلقتين","استنتاج أن كميات القواعد الأربع متساوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-15T02:47:48.864Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يقابل كل A قاعدة T، وكل T قاعدة A، وكل G قاعدة C، وكل C قاعدة G؛ فالشريط المكمل فيه: T = 10، وA = 6، وC = 9، وG = 5 (المجموع 30).
(ب) A = 10 + 6 = 16، T = 6 + 10 = 16، G = 9 + 5 = 14، C = 5 + 9 = 14؛ فكمية A تساوي كمية T، وكمية G تساوي كمية C، كما تقتضي قاعدة التزاوج.
(ج) عدد أزواج A–T = 16، وعدد أزواج G–C = 14. الروابط = 16 × 2 + 14 × 3 = 32 + 42 = 74 رابطة هيدروجينية.', '["الشريط المكمل: T = 10، A = 6، C = 9، G = 5","المجموع: A = T = 16، G = C = 14","أزواج A–T = 16 وG–C = 14","عدد الروابط = 74"]'::jsonb, '["كل A في الشريط المعطى يقابله T في المكمل: T = 10، وكل T يقابله A: A = 6","كل G يقابله C: C = 9، وكل C يقابله G: G = 5","A الكلي = 10 + 6 = 16، وT الكلي = 6 + 10 = 16، وG الكلي = 9 + 5 = 14، وC الكلي = 5 + 9 = 14","عدد الأزواج = 30: منها 16 زوج A–T و14 زوج G–C","الروابط الهيدروجينية = 16 × 2 + 14 × 3 = 32 + 42 = 74"]'::jsonb, '[{"element":"تكوين الشريط المكمل","marks":2},{"element":"المجموع الكلي والتحقق من القاعدة","marks":1},{"element":"حساب الروابط الهيدروجينية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"الشريط المكمل والمجموع صحيحان مع خطأ في حساب الروابط"},{"level":"1–2 درجة","description":"الشريط المكمل فقط صحيح أو جزئيًّا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نقل أعداد الشريط المعطى نفسها إلى الشريط المكمل دون تبديل","عدّ أزواج A–T بـ 10 فقط بدل 16","ضرب جميع الأزواج في رابطتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-15T02:47:48.865Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطالب الأول: إجابته خاطئة؛ لأنه وضع اليوراسيل U مقابل الأدينين، واليوراسيل لا يوجد في DNA (يوجد في RNA). الصحيح أن يقابل A في DNA قاعدةُ T.
الطالب الثاني: الشريط المكمل الذي كتبه صحيح: A-T-G-C-C-T-A-G. لكن حسابه للروابط خاطئ؛ لأن أزواج G–C ترتبط بثلاث روابط لا برابطتين. في القطعة 4 أزواج A–T (المواقع 1، 2، 6، 7) و4 أزواج G–C (المواقع 3، 4، 5، 8)؛ فعدد الروابط = 4 × 2 + 4 × 3 = 8 + 12 = 20 رابطة هيدروجينية.', '["خطأ الطالب الأول: استعمال U بدل T في DNA","الشريط المكمل الصحيح A-T-G-C-C-T-A-G","خطأ الطالب الثاني: معاملة أزواج G–C كأنها ترتبط برابطتين","4 أزواج A–T و4 أزواج G–C","عدد الروابط الصحيح 20"]'::jsonb, '["الشريط المكمل: T→A، A→T، C→G، G→C، G→C، A→T، T→A، C→G، أي A-T-G-C-C-T-A-G","أزواج A–T في المواقع 1، 2، 6، 7: عددها 4؛ وأزواج G–C في المواقع 3، 4، 5، 8: عددها 4","الروابط = 4 × 2 + 4 × 3 = 8 + 12 = 20"]'::jsonb, '[{"element":"تقويم إجابة الطالب الأول وتصحيحها","marks":2},{"element":"تأكيد صحة شريط الطالب الثاني","marks":1},{"element":"تحديد خطأ الحساب وتعليله","marks":1},{"element":"الحساب الصحيح للروابط (20)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تقويم صحيح ومعلل للطالبين مع التصحيح والحساب الصحيح"},{"level":"4–5 درجات","description":"تقويم صحيح للطالبين مع خطأ بسيط في العدّ أو الحساب"},{"level":"2–3 درجات","description":"تقويم أحد الطالبين فقط تقويمًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ إجابة الطالب الأول صحيحة لأن U يقابل A","قبول عدد 16 رابطة دون مراجعة نوع الأزواج","إعادة حساب الروابط بضرب جميع الأزواج في 3"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-15T02:47:48.865Z"}'::jsonb)
