('mcq', 2, 'في جزيء DNA تتساوى نسبة الأدينين مع نسبة الثايمين، أما في عينة من RNA فكانت نسبة الأدينين 24% ونسبة اليوراسيل 31%. ما التفسير الصحيح لعدم تساوي A وU في RNA؟', null, null, '["لأن اليوراسيل يرتبط بالجوانين في RNA بدل الأدينين","لأن RNA يحتوي على سكر الرايبوز الذي يمنع تزاوج القواعد","لأن نصف قواعد RNA تتحول إلى ثايمين في أثناء صنع البروتين","لأن RNA شريط واحد لا ترتبط قواعده بقواعد شريط مقابل، فلا يلزم تساوي A وU"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 225، ص 227 — تزاوج القواعد وRNA'),
('mcq', 3, 'أي مجموعة من القواعد النيتروجينية الآتية توجد في كل من DNA وRNA؟', null, null, '["الأدينين، والجوانين، والسايتوسين","الأدينين، والثايمين، واليوراسيل","الثايمين، والجوانين، والسايتوسين","اليوراسيل، والجوانين، والسايتوسين"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 227 — RNA (الشكل 6-23)'),
('mcq', 4, 'حُلِّلت عينة من حمض نووي فوُجد أن السكر في جميع نيوكليوتيداتها هو الرايبوز. أي القواعد النيتروجينية الآتية لا يُتوقع وجودها في هذه العينة؟', null, null, '["الأدينين","الثايمين","اليوراسيل","السايتوسين"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 227 — RNA (الشكل 6-23)'),
('mcq', 5, 'أي العبارات الآتية تقارن بين وظيفتي DNA وRNA مقارنة صحيحة؟', null, null, '["كلاهما يخزن المعلومات الوراثية في النواة دون أن تستعملها الخلية","يصنع DNA البروتينات مباشرة، ويخزن RNA المعلومات الوراثية","يخزن DNA المعلومات الوراثية، ويمكّن RNA الخلية من استعمالها في صنع البروتينات","يزود DNA الخلية بالطاقة، ويسرّع RNA تفاعلاتها"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 227 — RNA'),
('mcq', 6, 'يمثل الشكل الآتي تركيب نيوكليوتيد قاعدته النيتروجينية هي الجوانين. إلى أي الحمضين النوويين ينتمي هذا النيوكليوتيد؟', null, '[{"src":"qimg/chem22/c6-l4b-g-ribo-nt.svg","alt":"صيغة بنائية لنيوكليوتيد. على اليسار مجموعة فوسفات: ذرة P مرتبطة بذرة O برابطة ثنائية إلى الأعلى، وبمجموعة HO إلى اليسار، وبمجموعة OH إلى الأسفل، وبذرة O إلى اليمين تتصل بمجموعة CH₂. ترتبط CH₂ بحلقة سكر خماسية فيها ذرة أكسجين واحدة وأربع ذرات كربون، وتحمل كل من ذرتي الكربون السفليتين في الحلقة مجموعة OH (أي مجموعتا OH متجاورتان أسفل الحلقة). ترتبط ذرة الكربون اليمنى في حلقة السكر بذرة N في قاعدة نيتروجينية ذات حلقتين ملتحمتين: حلقة خماسية فيها ذرتا N وذرة C تحمل H، وحلقة سداسية تحمل مجموعة C=O إلى الأعلى وذرة N مرتبطة بـH ومجموعة NH₂ إلى اليمين."}]'::jsonb, '["إلى DNA وRNA كليهما؛ لأن الجوانين يوجد في الحمضين","إلى DNA فقط؛ لأن قاعدته ذات حلقتين","إلى DNA فقط؛ لأن سكره يحمل مجموعتي OH","إلى RNA فقط؛ لأن سكره هو الرايبوز"]'::jsonb, 'تحليل', 'تفسير شكل', 'صعب', 'الكتاب ص 227 الشكل 6-23؛ ص 237 اختبار مقنن س11'),
('mcq', 7, 'أُضيفت إلى خلايا حية نيوكليوتيدات تحتوي على قاعدة اليوراسيل ومميَّزة بمادة يمكن الكشف عنها. في أي الجزيئات يُتوقع أن تظهر هذه المادة بعد استعمال الخلايا لهذه النيوكليوتيدات؟', null, null, '["في جزيئات RNA فقط","في جزيئات DNA فقط","في جزيئات DNA وRNA معًا","في جزيئات البروتين فقط"]'::jsonb, 'تحليل', 'توقع وتعليل', 'متوسط', 'الكتاب ص 227 — RNA'),
