from (values
('mcq', 1, 2, 'اليوراسيل (U) يوجد في RNA ولا يوجد في DNA، والثايمين (T) يوجد في DNA ولا يوجد أبدًا في RNA. العينة (2) هي الوحيدة التي تحتوي على U ولا تحتوي على T؛ فهي من RNA، أما العينتان (1) و(3) ففيهما T، وتتساوى فيهما A مع T وG مع C كما في DNA.', '["العينة (1) فيها الثايمين وتتساوى فيها A مع T، وهذه صفات DNA؛ ونسبة A الكبيرة لا تدل على نوع الحمض.","تساوي G مع C ووجود الثايمين في العينة (3) من صفات DNA لا RNA.","","الأدينين يوجد في DNA وRNA معًا، فلا يصلح للتمييز بينهما؛ والعينة (2) فيها اليوراسيل فهي RNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.865Z"}'::jsonb),
('mcq', 2, 3, 'تساوي A مع T وG مع C في DNA ناتج عن تزاوج قواعد الشريطين: كل A يقابله T. أما RNA فيتكون من شريط واحد دون روابط هيدروجينية بين القواعد، فلا تقابل كل A قاعدة U، ولذلك لا يلزم أن تتساوى نسبتاهما.', '["لا يتزاوج اليوراسيل مع الجوانين في RNA؛ فقواعد RNA غير متزاوجة أصلًا لأنه شريط واحد.","نوع السكر ليس سبب عدم التساوي؛ والسبب أن RNA شريط مفرد لا تتقابل فيه القواعد.","الثايمين لا يوجد أبدًا في RNA، ولا تتحول قواعده إلى ثايمين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('mcq', 3, 0, 'يحتوي DNA على A وT وC وG، ويحتوي RNA على A وC وG وU؛ فالقواعد المشتركة بينهما هي الأدينين والجوانين والسايتوسين.', '["","الثايمين يوجد في DNA فقط، واليوراسيل يوجد في RNA فقط.","الثايمين يوجد في DNA فقط ولا يوجد أبدًا في RNA.","اليوراسيل يوجد في RNA فقط ولا يوجد في DNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('mcq', 4, 1, 'سكر الرايبوز يوجد في RNA، أما DNA فسكره الديوكسي رايبوز؛ فالعينة من RNA. وقواعد RNA هي الأدينين والسايتوسين والجوانين واليوراسيل، ولا يوجد الثايمين أبدًا في RNA؛ لذا لا يُتوقع وجود الثايمين في العينة.', '["الأدينين قاعدة مشتركة بين DNA وRNA، فهو متوقع في العينة.","","اليوراسيل قاعدة يختص بها RNA، والعينة من RNA لأن سكرها الرايبوز، فهو متوقع فيها.","السايتوسين قاعدة مشتركة بين DNA وRNA، فهو متوقع في العينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('mcq', 5, 2, 'يخزن DNA المعلومات الوراثية للخلية، في حين يمكّن RNA الخلايا من استعمال هذه المعلومات؛ إذ تستعمل الخلية RNA لصنع البروتينات بتسلسل الأحماض الأمينية الذي يحدده ترتيب قواعده.', '["RNA لا يقتصر على التخزين؛ بل يمكّن الخلية من استعمال المعلومات في صنع البروتينات.","عُكست الوظيفتان؛ فـDNA هو مخزن المعلومات، وRNA هو المستعمل في صنع البروتينات.","","تزويد الطاقة وتسريع التفاعلات ليسا من وظائف الأحماض النووية؛ فالإنزيمات (بروتينات) هي التي تسرّع التفاعلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('mcq', 6, 3, 'الجوانين قاعدة مشتركة بين DNA وRNA، فلا تحدد نوع الحمض. أما السكر في الشكل فتحمل كل من ذرتي الكربون السفليتين في حلقته مجموعة OH، وهذا هو سكر الرايبوز؛ أما الديوكسي رايبوز فيحمل ذرة H بدل إحدى المجموعتين. إذن ينتمي النيوكليوتيد إلى RNA فقط.', '["وجود الجوانين في الحمضين لا يكفي؛ فالسكر هو الذي يحدد نوع الحمض، وسكر الشكل رايبوز.","عدد حلقات القاعدة لا يميز بين الحمضين؛ فالجوانين ذو الحلقتين موجود في الحمضين.","السكر الذي يحمل مجموعتي OH هو الرايبوز، وهو سكر RNA لا DNA.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('mcq', 7, 0, 'اليوراسيل قاعدة توجد في RNA ولا توجد في DNA؛ فالنيوكليوتيدات التي تحتوي عليه لا تدخل إلا في بناء RNA، ولذلك تظهر المادة المميِّزة في جزيئات RNA فقط.', '["","DNA لا يحتوي على اليوراسيل؛ فقاعدته المقابلة هي الثايمين.","اليوراسيل غير موجود في DNA، فلا تدخل نيوكليوتيداته في بنائه.","البروتينات تتكون من أحماض أمينية لا من نيوكليوتيدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) السكر: DNA يحتوي على الديوكسي رايبوز (منقوص الأكسجين، فيه H بدل OH في أحد المواقع)، وRNA يحتوي على الرايبوز.
(ب) القواعد: DNA فيه A وT وC وG، وRNA فيه A وC وG وU (اليوراسيل بدل الثايمين).
(ج) الأشرطة: DNA شريطان ملتفان على شكل لولب مزدوج، وRNA شريط واحد.
(د) الروابط الهيدروجينية: في DNA تربط الروابط الهيدروجينية قواعد الشريطين (A–T وG–C)، وفي RNA لا توجد روابط هيدروجينية بين القواعد.
(هـ) الوظيفة: DNA يخزن المعلومات الوراثية، وRNA يمكّن الخلية من استعمالها في صنع البروتينات.
مما يشتركان فيه: كلاهما بوليمر من نيوكليوتيدات تتكون من مجموعة فوسفات وسكر خماسي وقاعدة نيتروجينية، وكلاهما يحتوي على القواعد A وG وC (ويخزنان معلومات للخلية).', '["الديوكسي رايبوز مقابل الرايبوز","T في DNA وU في RNA","شريطان مقابل شريط واحد","روابط هيدروجينية بين القواعد في DNA فقط","DNA يخزن المعلومات وRNA يستعملها لصنع البروتينات","وجهان للتشابه"]'::jsonb, '[]'::jsonb, '[{"element":"السكر","marks":1},{"element":"القواعد","marks":1},{"element":"عدد الأشرطة","marks":1},{"element":"الروابط الهيدروجينية","marks":1},{"element":"الوظيفة","marks":1},{"element":"وجها التشابه","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة صحيحة مع وجهي التشابه"},{"level":"4–5 درجات","description":"أربعة أو خمسة عناصر صحيحة"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الديوكسي رايبوز إلى RNA","القول إن RNA يحتوي على الثايمين واليوراسيل معًا","عدّ مجموعة الفوسفات فرقًا بين الحمضين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-15T02:47:48.866Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) W: DNA؛ لأنها تحتوي على الثايمين ولا تحتوي على اليوراسيل، وA = T = 29% وG = C = 21%. X: RNA؛ لأنها تحتوي على اليوراسيل ولا تحتوي على الثايمين، وA لا تساوي U. Y: DNA؛ لأنها تحتوي على الثايمين، وA = T = 33% وG = C = 17%. Z: RNA؛ لأنها تحتوي على اليوراسيل ولا تحتوي على الثايمين.
(ب) الرأي خاطئ؛ فاليوراسيل لا يوجد في DNA أبدًا، ووجوده يكفي للحكم بأن العينة RNA. وتساوي A مع U في Z مصادفة؛ لأن RNA شريط واحد لا تتزاوج قواعده، كما أن G (25%) لا تساوي C (23%).
(ج) العينة W؛ لأن نسبة أزواج G–C فيها أكبر (21% من القواعد G مقابل 17% في Y)، وكل زوج G–C يرتبط بثلاث روابط مقابل رابطتين لـ A–T. لكل 100 زوج: W فيها 42 زوج G–C و58 زوج A–T، أي 42 × 3 + 58 × 2 = 242 رابطة؛ وY فيها 34 زوج G–C و66 زوج A–T، أي 34 × 3 + 66 × 2 = 234 رابطة.', '["W وY من DNA (فيهما T وتساوي A=T وG=C)","X وZ من RNA (فيهما U)","وجود U يحسم أن Z من RNA، وتساوي A وU مصادفة","W تحتاج روابط أكثر لأن نسبة G–C فيها أكبر","حساب 242 مقابل 234 رابطة"]'::jsonb, '["في DNA: نسبة أزواج G–C من الأزواج = 2 × نسبة G؛ W: 2 × 21 = 42 زوجًا لكل 100 زوج، Y: 2 × 17 = 34 زوجًا","W: 42 × 3 + 58 × 2 = 126 + 116 = 242 رابطة","Y: 34 × 3 + 66 × 2 = 102 + 132 = 234 رابطة","إذن W أكثر روابط"]'::jsonb, '[{"element":"تصنيف العينات الأربع مع الدليل","marks":2},{"element":"تحليل رأي الطالب","marks":2},{"element":"تحديد W مع التعليل والحساب","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف صحيح ومعلل، وتحليل صحيح للرأي، واختيار W مع تعليل"},{"level":"4–5 درجات","description":"تصنيف صحيح مع نقص في تحليل الرأي أو في تعليل (ج)"},{"level":"2–3 درجات","description":"تصنيف صحيح فقط أو مع جزء يسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف Z على أنها DNA لتساوي A وU","الحكم بنسبة A وحدها دون النظر إلى وجود T أو U","اختيار Y لأن نسبة A فيها أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.867Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الصحيح: كلا الحمضين بوليمر من نيوكليوتيدات، وكل نيوكليوتيد يتكون من مجموعة فوسفات وسكر خماسي وقاعدة نيتروجينية، ويشتركان في القواعد A وG وC.
الخطأ: أنهما ليسا جزيئًا واحدًا؛ إذ يختلفان في ثلاث طرائق مهمة: (1) سكر DNA الديوكسي رايبوز وسكر RNA الرايبوز، (2) في DNA الثايمين وفي RNA اليوراسيل بدلًا منه، (3) DNA شريطان ملتفان في لولب مزدوج تربط قواعدَهما روابط هيدروجينية، وRNA شريط واحد دون روابط هيدروجينية بين القواعد.
ارتباط التركيب بالوظيفة: الشريطان المتكاملان في DNA وتزاوج قواعدهما (A–T وG–C) يجعلانه مناسبًا لتخزين المعلومات الوراثية ونسخها بدقة قبل انقسام الخلية؛ فكل شريط قالب لبناء الآخر. أما RNA فشريط واحد يحمل تسلسل قواعد متطابقًا مع تسلسل DNA، فتستعمله الخلية لصنع البروتينات بتسلسل الأحماض الأمينية الذي يحدده ترتيب قواعده؛ أي أن DNA يخزن المعلومات وRNA يمكّن الخلية من استعمالها.', '["الصحيح: كلاهما من نيوكليوتيدات بالأجزاء الثلاثة","الفرق في السكر","الفرق في القواعد (T وU)","الفرق في عدد الأشرطة والروابط الهيدروجينية","ربط الشريطين المتكاملين في DNA بالتخزين والنسخ","ربط RNA بصنع البروتينات"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الصحيح في العبارة","marks":1},{"element":"الفروق الثلاثة","marks":3},{"element":"ربط التركيب بالوظيفة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحليل كامل: الصحيح والفروق الثلاثة وربط مقنع بالوظيفة"},{"level":"4–5 درجات","description":"الفروق الثلاثة صحيحة مع ربط ناقص بالوظيفة"},{"level":"2–3 درجات","description":"فرق أو فرقان مع إشارة يسيرة إلى الوظيفة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن الأجزاء الثلاثة متشابهة","ذكر الفروق دون ربطها بالوظيفة","القول إن RNA يخزن المعلومات وDNA يصنع البروتينات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-15T02:47:48.867Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
