insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L4-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في أي عام حدد جيمس واطسون وفرانسيس كريك تركيب DNA ذا اللولب المزدوج؟', null, null, '["1828م","1953م","1865م","1903م"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 2, 'يمثل الشكل الآتي نموذج تركيب DNA الذي يشبه سلّمًا ملتويًا. من العالِمان اللذان حددا هذا التركيب؟', null, '[{"src":"qimg/chem22/c6-l4b-helix.svg","alt":"رسم لنموذج جزيء طويل على شكل سلّم ملتوٍ رأسيًّا: شريطان رماديان سميكان يلتف كل منهما حول الآخر التفافًا حلزونيًّا منتظمًا، وتصل بين الشريطين درجات عرضية ملونة (أخضر وأحمر وأزرق وبرتقالي)، تتكون كل درجة من نصفين بلونين مختلفين يلتقيان في منتصف المسافة بين الشريطين. لا توجد كتابة على الشكل."}]'::jsonb, '["فريدريك فوهلر ولويس باستور","جيمس واطسون وماري شفايتزر","جيمس واطسون وفرانسيس كريك","فرانسيس كريك وفريدريك فوهلر"]'::jsonb, 'تذكر', 'تعرّف من شكل', 'سهل', 'الكتاب ص 225 — الشكل 6-21'),
('mcq', 3, 'ما الملاحظة التي استعملها واطسون وكريك في تحديد تركيب DNA؟', null, null, '["تساوي كميات القواعد الأربع في جميع جزيئات DNA","تساوي كمية الأدينين مع كمية الجوانين، وكمية الثايمين مع كمية السايتوسين","كمية الجوانين في DNA ضعف كمية الأدينين","تساوي كمية الأدينين مع كمية الثايمين، وكمية السايتوسين مع كمية الجوانين"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 4, 'كيف توصل واطسون وكريك إلى تحديد تركيب DNA؟', null, null, '["بتجميع أعمال عدد كبير من العلماء الذين درسوا DNA وتحليلها","بإجراء عدد كبير من التجارب المخبرية بنفسيهما","بتحضير DNA في المختبر من مواد غير عضوية","بفصل شريطي DNA ثم عدّ قواعد كل شريط على حدة"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 5, 'بعد أن حدد واطسون وكريك تركيب DNA، استعملا نموذجهما لتوقع كيف يؤدي تركيبه وظيفته. أي مما يأتي أدركاه؟', null, null, '["أن سلسلتي اللولب متكاملتان، فتنسخ الأزواج القاعدية المادة الوراثية آليًّا","أن DNA شريط واحد ينسخ نفسه دون الحاجة إلى تزاوج القواعد","أن قواعد الشريطين ترتبط بروابط تساهمية تمنع انفصالهما في أثناء النسخ","أن RNA هو الذي يخزن المعلومات الوراثية وينسخها قبل انقسام الخلية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 226 — وظيفة DNA'),
('mcq', 6, 'يبين الجدول الآتي النسب المئوية التقريبية للقواعد في DNA لثلاثة مخلوقات حية. أي العبارات الآتية تصف النمط الذي تظهره البيانات، وهو النمط الذي استعمله واطسون وكريك؟', '{"headers":["المخلوق الحي","A (%)","T (%)","G (%)","C (%)"],"rows":[["الإنسان","30.9","29.4","19.9","19.8"],["القمح","27.3","27.1","22.7","22.8"],["بكتيريا E.coli","24.7","23.6","26.0","25.7"]]}'::jsonb, null, '["نسب القواعد الأربع متساوية في كل مخلوق","نسبة A تساوي تقريبًا نسبة G، ونسبة T تساوي تقريبًا نسبة C في كل مخلوق","نسبة A تساوي تقريبًا نسبة T، ونسبة G تساوي تقريبًا نسبة C في كل مخلوق","نسب القواعد متطابقة في جميع المخلوقات"]'::jsonb, 'فهم', 'تحليل بيانات', 'صعب', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('mcq', 7, 'يُعدّ تحديد واطسون وكريك لتركيب DNA من أعظم الاكتشافات العلمية في أي قرن؟', null, null, '["القرن التاسع عشر","القرن العشرين","القرن الحادي والعشرين","القرن الثامن عشر"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('essay', 1, 'اكتب فقرة تبين دور واطسون وكريك في تحديد تركيب DNA، تذكر فيها: اسمي العالمين، وعام الاكتشاف، والتركيب الذي حدداه، والملاحظة التي استعملاها، والطريقة التي حققا بها الإنجاز.', null, null, null, 'تذكر', 'فقرة استرجاعية', 'متوسط', 'الكتاب ص 225 — DNA: اللولب المزدوج'),
('essay', 2, 'فسّر كيف يوضح نموذج واطسون وكريك للولب DNA المزدوج كلًّا مما يأتي:
(أ) تساوي كمية الأدينين مع الثايمين، وكمية الجوانين مع السايتوسين في DNA.
(ب) قدرة الخلية على نسخ المادة الوراثية قبل انقسامها.', null, null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 225، ص 226 — اللولب المزدوج ووظيفة DNA'),
('essay', 3, 'كتب طالب: «اكتشف واطسون وكريك تركيب DNA بعد أن أجريا آلاف التجارب في مختبرهما وحدهما، وكان اكتشافهما وصفًا لشكل الجزيء فقط دون أي تفسير لوظيفته». قوّم هذه العبارة، وصحّح ما فيها من أخطاء، ثم بيّن ما تعلمه هذه القصة عن طبيعة العمل العلمي.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 225، ص 226 — اللولب المزدوج ووظيفة DNA')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C6-L4-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'في عام 1953م استعمل جيمس واطسون وفرانسيس كريك ملاحظة تساوي كميات القواعد المتزاوجة، فحددا تركيب DNA ذا اللولب المزدوج.', '["1828م ليس عام تحديد تركيب DNA؛ فقد حدده واطسون وكريك عام 1953م.","","1865م ليس عام تحديد تركيب DNA؛ فقد حدده واطسون وكريك عام 1953م.","1903م يسبق تحديد تركيب DNA بخمسين عامًا؛ والصحيح 1953م في منتصف القرن العشرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-15T02:47:48.867Z"}'::jsonb),
('mcq', 2, 2, 'الشكل هو اللولب المزدوج لـDNA، والعالمان اللذان حددا هذا التركيب عام 1953م هما جيمس واطسون وفرانسيس كريك.', '["فوهلر أول من حضّر مركبًا عضويًّا في المختبر، وباستور درس بلورات حمض الطرطريك، ولم يشارك أي منهما في تحديد تركيب DNA.","ماري شفايتزر عالمة درست بقايا عظام ديناصور، ولم تشارك في تحديد تركيب DNA؛ وشريك واطسون هو كريك.","","فوهلر لم يشارك في تحديد تركيب DNA؛ وشريك كريك هو واطسون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-15T02:47:48.867Z"}'::jsonb),
('mcq', 3, 3, 'لاحظ العلماء أن كمية الأدينين في جزيء DNA تساوي دائمًا كمية الثايمين، وأن كمية السايتوسين تساوي دائمًا كمية الجوانين، واستعمل واطسون وكريك هذه الملاحظة عندما حددا تركيب DNA ذا اللولب المزدوج.', '["لا تتساوى القواعد الأربع بالضرورة؛ فالتساوي يكون بين A وT، وبين C وG فقط.","A وG كلاهما ذو حلقتين ولا يتزاوجان؛ فالتساوي بين A وT، وبين G وC.","لا توجد علاقة ثابتة من هذا النوع؛ والثابت هو تساوي G مع C.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.867Z"}'::jsonb),
('mcq', 4, 0, 'حقق واطسون وكريك هذا الإنجاز دون أن يقوما بالعديد من التجارب المخبرية؛ بل قاما بتجميع أعمال عدد كبير من العلماء الذين درسوا DNA وتحليلها.', '["","لم يحققا الإنجاز بإجراء العديد من التجارب المخبرية، بل بتحليل أعمال غيرهما.","لم يحضّرا DNA في المختبر؛ وإنما حللا نتائج علماء آخرين.","لم يعتمدا على عدّ القواعد بأنفسهما؛ بل استعملا ملاحظات علماء آخرين وأعمالهم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-15T02:47:48.867Z"}'::jsonb),
('mcq', 5, 0, 'أدرك واطسون وكريك أن سلسلتي لولب DNA تكمل إحداهما الأخرى، وأن الأزواج القاعدية المتطابقة (A–T وG–C) تنسخ المادة الوراثية للخلية بطريقة آلية؛ فكل شريط يحدد تتابع الشريط المكمل له.', '["","DNA يتكون من شريطين متكاملين، وتزاوج القواعد هو أساس نسخه.","قواعد الشريطين ترتبط بروابط هيدروجينية تنفصل في أثناء النسخ، لا بروابط تساهمية.","DNA هو الذي يخزن المعلومات الوراثية ويُنسخ قبل الانقسام، لا RNA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-15T02:47:48.868Z"}'::jsonb),
('mcq', 6, 2, 'في كل مخلوق تتقارب نسبة A مع نسبة T (مثلًا 27.3% و27.1% في القمح)، وتتقارب نسبة G مع نسبة C (22.7% و22.8%)، مع أن النسب تختلف من مخلوق لآخر. وهذه هي ملاحظة تساوي A مع T وC مع G التي استعملها واطسون وكريك.', '["النسب غير متساوية؛ ففي الإنسان A نحو 31% بينما G نحو 20%.","A لا تساوي G؛ ففي الإنسان A نحو 31% وG نحو 20%.","","النسب تختلف بين المخلوقات؛ فنسبة A في الإنسان 30.9% وفي البكتيريا 24.7%."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-15T02:47:48.868Z"}'::jsonb),
('mcq', 7, 1, 'حدد واطسون وكريك تركيب DNA عام 1953م، وجعلتهما هذه الملاحظة يقومان بأحد أعظم الاكتشافات العلمية في القرن العشرين.', '["القرن التاسع عشر انتهى عام 1900م، أي قبل الاكتشاف بأكثر من نصف قرن.","","القرن الحادي والعشرون يبدأ عام 2001م، والاكتشاف كان عام 1953م.","القرن الثامن عشر سبق الاكتشاف بنحو قرنين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-15T02:47:48.868Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في عام 1953م حدد العالمان جيمس واطسون وفرانسيس كريك تركيب DNA ذا اللولب المزدوج، أي سلسلتين طويلتين من النيوكليوتيدات ملتفتين حلزونيًّا. واستعملا في ذلك ملاحظة أن كمية الأدينين في DNA تساوي دائمًا كمية الثايمين، وأن كمية السايتوسين تساوي دائمًا كمية الجوانين. وحققا هذا الإنجاز دون أن يقوما بالعديد من التجارب المخبرية، بل بتجميع أعمال عدد كبير من العلماء الذين درسوا DNA وتحليلها، ويُعدّ ذلك من أعظم الاكتشافات العلمية في القرن العشرين.', '["جيمس واطسون وفرانسيس كريك","عام 1953م","اللولب المزدوج","A = T وC = G","تجميع أعمال علماء آخرين وتحليلها"]'::jsonb, '[]'::jsonb, '[{"element":"اسما العالمين","marks":1},{"element":"العام","marks":1},{"element":"التركيب","marks":1},{"element":"الملاحظة","marks":1},{"element":"الطريقة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"العناصر الخمسة صحيحة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إنهما حددا تركيب RNA","ذكر أنهما أجريا تجارب كثيرة بأنفسهما","قلب الملاحظة إلى A = G"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-15T02:47:48.868Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في النموذج تتجه القواعد النيتروجينية إلى داخل اللولب، وتقابل كلُّ قاعدة في شريط قاعدةً في الشريط الآخر وترتبطان بروابط هيدروجينية، ويرتبط الأدينين دائمًا بالثايمين، والجوانين دائمًا بالسايتوسين. فكل A يقابله T وكل G يقابله C؛ ولذلك تتساوى كمية A مع T، وكمية G مع C في الجزيء.
(ب) أدرك واطسون وكريك أن سلسلتي اللولب تكمل إحداهما الأخرى؛ فإذا انفصل الشريطان أمكن أن يحدد كل شريط تتابع الشريط المكمل له، فتنسخ الأزواج القاعدية المتطابقة المادة الوراثية بطريقة آلية، ويحصل كل جيل جديد من الخلايا على المعلومات الوراثية نفسها.', '["القواعد في الداخل متقابلة بروابط هيدروجينية","A يقابل T دائمًا وG يقابل C دائمًا فتتساوى الكميات","الشريطان متكاملان","كل شريط يحدد تتابع الآخر فيُنسخ DNA آليًّا"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير تساوي الكميات بالتزاوج","marks":2},{"element":"تفسير النسخ بتكامل الشريطين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح ومترابط للجزأين"},{"level":"2–3 درجات","description":"تفسير أحد الجزأين كاملًا مع نقص في الآخر"},{"level":"1 درجة","description":"ذكر قاعدة التزاوج دون ربطها بالمطلوب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير التساوي بأن عدد القواعد الأربع متساوٍ","القول إن الشريط الجديد مطابق للشريط الذي يرتبط به","إغفال دور تكامل الشريطين في النسخ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-15T02:47:48.868Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة تحتوي على خطأين:
1) لم يحقق واطسون وكريك إنجازهما بإجراء العديد من التجارب المخبرية، بل بتجميع أعمال عدد كبير من العلماء الذين درسوا DNA وتحليلها، ومنها ملاحظة تساوي كمية A مع T وكمية C مع G.
2) لم يكن اكتشافهما وصفًا للشكل فقط؛ فقد استعملا نموذجهما لتوقع كيف يؤدي تركيب DNA وظيفته، وأدركا أن سلسلتي اللولب تكمل إحداهما الأخرى، وأن الأزواج القاعدية المتطابقة تنسخ المادة الوراثية بطريقة آلية.
الصحيح في العبارة: أنهما حددا تركيب DNA (اللولب المزدوج) عام 1953م.
ما تعلمه القصة: العلم تراكمي وتعاوني؛ فقد يأتي الاكتشاف الكبير من تحليل نتائج علماء آخرين وربطها بنموذج يفسرها، ويُعدّ هذا الاكتشاف من أعظم اكتشافات القرن العشرين.', '["تصحيح الطريقة: تجميع أعمال علماء آخرين وتحليلها","تصحيح: النموذج فسّر الوظيفة (التكامل والنسخ الآلي)","إقرار الصحيح: تحديد اللولب المزدوج عام 1953م","استنتاج عن طبيعة العلم (تراكمي وتعاوني)"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح الخطأ الأول","marks":2},{"element":"تصحيح الخطأ الثاني","marks":2},{"element":"استنتاج عن طبيعة العلم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصحيح الخطأين بدقة مع استنتاج مناسب"},{"level":"3–4 درجات","description":"تصحيح الخطأين مع استنتاج ناقص، أو خطأ واحد مع استنتاج"},{"level":"1–2 درجة","description":"تصحيح خطأ واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول عبارة «آلاف التجارب»","إغفال أن النموذج فسّر آلية النسخ","الاكتفاء بالحكم دون تصحيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-15T02:47:48.868Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C6-L4-O08') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C6-L4-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما أول ما يحدث عندما يبدأ DNA في التضاعف؟', null, null, '["ترتبط النيوكليوتيدات الحرة بالقواعد النيتروجينية المكشوفة","ترتبط السكريات بمجموعات الفوسفات لتكوين عمود فقري جديد","يرتبط كل شريط أصلي بشريط جديد مكتمل","يبدأ شريطا النيوكليوتيد بالانفكاك والانفصال أحدهما عن الآخر"]'::jsonb, 'تذكر', 'ترتيب خطوات', 'سهل', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('mcq', 2, 'في أثناء تضاعف DNA يعمل إنزيم على فصل الشريطين. أي الروابط يفكها هذا الإنزيم؟', null, null, '["الروابط بين السكر ومجموعة الفوسفات في كل شريط","الروابط الهيدروجينية بين القواعد النيتروجينية في الشريطين","الروابط بين القاعدة النيتروجينية والسكر في كل نيوكليوتيد","الروابط الببتيدية بين النيوكليوتيدات المتجاورة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('mcq', 3, 'من أين تأتي النيوكليوتيدات الحرة التي تُبنى منها الأشرطة الجديدة في أثناء تضاعف DNA؟', null, null, '["من الوسط المحيط بـDNA داخل الخلية","من تفكيك أحد الشريطين الأصليين إلى نيوكليوتيدات","من تفكك جزيئات البروتين في الخلية","من انفصال القواعد النيتروجينية عن الشريطين الأصليين"]'::jsonb, 'تذكر', 'استرجاع', 'متوسط', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('mcq', 4, 'بعد أن ترتبط النيوكليوتيدات الحرة بالقواعد المكشوفة بروابط هيدروجينية، كيف يتكون العمود الفقري للشريط الجديد؟', null, null, '["ترتبط القواعد النيتروجينية المتجاورة بعضها ببعض جنبًا إلى جنب","ترتبط السكريات المتجاورة بعضها ببعض بروابط هيدروجينية","ترتبط السكريات والفوسفات المتجاورة بعضها ببعض بروابط تساهمية","ترتبط مجموعات الفوسفات بالقواعد المكشوفة في الشريط الأصلي"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('mcq', 5, 'يمثل الشكل الآتي جزيء DNA في أثناء التضاعف، وفيه ثلاث مناطق مرقمة. في أي منطقة فُكّت الروابط الهيدروجينية بين القواعد ولم ترتبط القواعد المكشوفة بعدُ بنيوكليوتيدات حرة؟', null, '[{"src":"qimg/chem22/c6-l4b-fork.svg","alt":"مخطط تخطيطي لجزيء DNA في أثناء التضاعف. المخمسات الصفراء نيوكليوتيدات الشريطين الأصليين، والمخمسات الزرقاء نيوكليوتيدات حرة أو جديدة، والدوائر الخضراء فوسفات، والمستطيلات قواعد بحروفها. الشريط الأصلي العلوي أفقي كامل، وقواعده من اليسار إلى اليمين: G، A، T، C، C، A، T، G. المنطقة (1) على اليسار: تقابل القواعد الثلاث الأولى للشريط العلوي قواعدَ الشريط الأصلي السفلي C، T، A، وبين كل زوج خطان متقطعان قصيران. بعد ذلك ينحرف الشريط الأصلي السفلي إلى أسفل الشكل، وقواعده المكشوفة المتجهة إلى الأعلى من اليسار: G، G، T، A، C. المنطقة (2) في الوسط تحت القواعد المكشوفة للشريط العلوي (C، C، A، T، G) التي لا يقابلها شريط، ويقترب منها نيوكليوتيدان حران أزرقان غير مرتبطين يحملان G وA. المنطقة (3) في أسفل اليمين: شريط أزرق قصير من ثلاثة نيوكليوتيدات قواعدها A وT وG، ترتبط بخطوط متقطعة بالقواعد T وA وC في الشريط الأصلي السفلي، ونيوكليوتيداته متصلة بعضها ببعض بخط واحد عبر الفوسفات."}]'::jsonb, '["المنطقة (1)","المنطقة (3)","المنطقتان (1) و(3)","المنطقة (2)"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('mcq', 6, 'لماذا يكون جزيئا DNA الناتجان من التضاعف متطابقين مع الجزيء الأصلي في تسلسل القواعد؟', null, null, '["لأن الإنزيم ينسخ الجزيء كاملًا دفعة واحدة دون أن يفصل شريطيه أحدهما عن الآخر","لأن كل قاعدة مكشوفة لا ترتبط إلا بقاعدة مكملة لها، فيُبنى شريط مماثل للشريط الذي انفصل عنها","لأن النيوكليوتيدات الحرة ترتبط عشوائيًّا ثم يُعاد ترتيبها بعد اكتمال بناء الشريط","لأن جزيء RNA هو الذي يحدد ترتيب القواعد في الشريط الجديد عند بنائه"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 226 — وظيفة DNA ومختبر حل المشكلات'),
('mcq', 7, 'قطعة من DNA فيها 50 زوجًا من القواعد، منها 20 زوج G–C والباقي أزواج A–T. كم نيوكليوتيدًا حرًّا يحتوي على السايتوسين (C) يلزم لتضاعف هذه القطعة مرة واحدة؟', null, null, '["40","30","20","10"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('essay', 1, 'يمثل الشكل الآتي جزيء DNA في أثناء التضاعف.
(أ) صف ما يحدث في كل من المناطق (1) و(2) و(3)، مرتبةً حسب تسلسل خطوات التضاعف.
(ب) حدّد نوع الروابط التي تُفك ونوع الروابط التي تتكون في أثناء ذلك.
(ج) ما القاعدة التي يجب أن تحملها النيوكليوتيدات الحرة التي سترتبط بالقاعدتين المكشوفتين C وC في الشريط العلوي؟', null, '[{"src":"qimg/chem22/c6-l4b-fork.svg","alt":"مخطط تخطيطي لجزيء DNA في أثناء التضاعف. المخمسات الصفراء نيوكليوتيدات الشريطين الأصليين، والمخمسات الزرقاء نيوكليوتيدات حرة أو جديدة، والدوائر الخضراء فوسفات، والمستطيلات قواعد بحروفها. الشريط الأصلي العلوي أفقي كامل، وقواعده من اليسار إلى اليمين: G، A، T، C، C، A، T، G. المنطقة (1) على اليسار: تقابل القواعد الثلاث الأولى للشريط العلوي قواعدَ الشريط الأصلي السفلي C، T، A، وبين كل زوج خطان متقطعان قصيران. بعد ذلك ينحرف الشريط الأصلي السفلي إلى أسفل الشكل، وقواعده المكشوفة المتجهة إلى الأعلى من اليسار: G، G، T، A، C. المنطقة (2) في الوسط تحت القواعد المكشوفة للشريط العلوي (C، C، A، T، G) التي لا يقابلها شريط، ويقترب منها نيوكليوتيدان حران أزرقان غير مرتبطين يحملان G وA. المنطقة (3) في أسفل اليمين: شريط أزرق قصير من ثلاثة نيوكليوتيدات قواعدها A وT وG، ترتبط بخطوط متقطعة بالقواعد T وA وC في الشريط الأصلي السفلي، ونيوكليوتيداته متصلة بعضها ببعض بخط واحد عبر الفوسفات."}]'::jsonb, null, 'فهم', 'وصف خطوات من شكل', 'سهل', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا'),
('essay', 2, 'قطعة من DNA تتابع قواعد شريطها العلوي G-A-T-C-C-A، وتتابع قواعد شريطها السفلي C-T-A-G-G-T.
(أ) اكتب تتابع الشريط الجديد الذي يُبنى مقابل الشريط العلوي في أثناء التضاعف، وتتابع الشريط الجديد الذي يُبنى مقابل الشريط السفلي.
(ب) قارن بين تتابع كل شريط جديد وتتابع الشريط الأصلي الذي يرتبط به، ثم قارنه بتتابع الشريط الأصلي الآخر.
(ج) فسّر ما توصلت إليه، وبيّن أهميته للخلية.', null, null, null, 'تحليل', 'مقارنة تتابعات', 'صعب', 'الكتاب ص 226 — مختبر حل المشكلات (التفكير الناقد س1)'),
('essay', 3, 'صمّم نموذجًا يمكن صنعه من مواد بسيطة (أوراق ملونة، مشابك، خيوط…) لتوضيح تضاعف DNA لزملائك. حدّد: (أ) ما يمثل كل جزء من أجزاء النيوكليوتيد والروابط في نموذجك، (ب) كيف يُظهر النموذج قاعدة التزاوج، (ج) الخطوات التي ستعرضها بالنموذج بالترتيب، (د) كيف تُظهر بالنموذج مصير الشريطين الأصليين في الجزيئين الناتجين.', null, null, null, 'إبداع', 'تصميم نموذج', 'صعب', 'الكتاب ص 226 — مختبر حل المشكلات: كوّن نموذجًا')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
